TRAIN_IMAGE_EXTS = {".png", ".jpg", ".jpeg", ".webp"}
TRAIN_MAX_BYTES_PER_IMAGE = 32 * 1024 * 1024     # 32 MB per image upload

# Hard cap on bodies for the generic urlencoded POST fallback (the catch-all
# at the end of do_POST that handles /run, /queue/add, characters, etc.).
# Endpoints with their own larger caps (uploads, multipart, JSON bodies)
# enforce those locally before reading. 1 MB is well above any legitimate
# urlencoded form on Phosphene; without this cap a malformed Content-Length
# 500s the handler and a multi-GB declared CL allocates before any check.
MAX_FORM_BYTES = 1024 * 1024


# ---- multipart/form-data parsing (stdlib email, not deprecated cgi) ----------
# `cgi` / `cgi.FieldStorage` is removed in Python 3.13. The panel only needs
# simple text fields + file uploads, so the stdlib email parser covers it and
# keeps Phosphene 3.13-ready. Adopted from the community PR by @ssfeather (#22);
# binary integrity verified (get_payload(decode=True) — no text re-encoding of
# image/audio/zip bytes). Callers enforce a Content-Length cap before calling.
class _MultipartFile:
    """File-field wrapper exposing the `.filename` + `.file` (a BytesIO) surface
    the upload handlers used from cgi.FieldStorage."""

    def __init__(self, filename: str, data: bytes) -> None:
        self.filename = filename
        self.file = io.BytesIO(data)


class _MultipartForm:
    def __init__(self) -> None:
        self._fields: dict[str, "str | _MultipartFile"] = {}

    def __contains__(self, key: str) -> bool:
        return key in self._fields

    def __getitem__(self, key: str) -> "str | _MultipartFile":
        return self._fields[key]

    def set(self, key: str, value: "str | _MultipartFile") -> None:
        self._fields[key] = value

    def getvalue(self, key: str, default: "str | None" = None) -> "str | None":
        value = self._fields.get(key)
        if isinstance(value, _MultipartFile):
            return default
        return value if value is not None else default


def _parse_multipart_form(rfile, ctype: str, content_length: int) -> _MultipartForm:
    """Parse a multipart/form-data body without the deprecated stdlib cgi APIs.
    The caller is responsible for enforcing a Content-Length cap first."""
    body = rfile.read(content_length)
    header = (f"Content-Type: {ctype}\r\nMIME-Version: 1.0\r\n\r\n").encode("utf-8")
    message = BytesParser(policy=policy.default).parsebytes(header + body)
    if not message.is_multipart():
        raise ValueError("invalid multipart/form-data body")
    form = _MultipartForm()
    for part in message.iter_parts():
        if part.get_content_disposition() != "form-data":
            continue
        name = part.get_param("name", header="content-disposition")
        if not name:
            continue
        payload = part.get_payload(decode=True)
        if payload is None:
            content = part.get_content()
            payload = content.encode(part.get_content_charset() or "utf-8") \
                if isinstance(content, str) else bytes(content)
        filename = part.get_filename()
        if filename is not None:
            form.set(name, _MultipartFile(filename, payload))
        else:
            form.set(name, payload.decode(part.get_content_charset() or "utf-8", "replace"))
    return form


class MultipartTooLarge(ValueError):
    """A streamed part exceeded the caller's byte cap. Distinct from a plain
    ValueError so the handler can answer 413 instead of 400."""


def _multipart_boundary(ctype: str) -> bytes:
    """The boundary token of a multipart Content-Type, as bytes."""
    probe = _EmailMessage()
    probe["Content-Type"] = ctype
    boundary = probe.get_param("boundary")
    if isinstance(boundary, tuple):           # RFC 2231 (charset, lang, value)
        boundary = boundary[2]
    if not boundary:
        raise ValueError("multipart/form-data body has no boundary")
    return b"--" + str(boundary).encode("ascii", "replace")


def _stream_multipart_file_part(rfile, ctype: str, content_length: int,
                                field_name: str,
                                chunk: int = 1024 * 1024):
    """Advance a multipart body to one file field WITHOUT buffering it.

    Returns `(filename, drain, fields)`:
      filename  the part's declared filename (never trusted as a path)
      drain     `drain(fh, max_bytes) -> int` copies exactly that part's
                payload into the open binary file `fh` and returns the count
      fields    the plain text fields seen before it, if any

    Why this exists rather than `_parse_multipart_form`: that function reads
    the body into `bytes`, hands it to the email parser (copy), calls
    `get_payload(decode=True)` (copy), wraps the result in a BytesIO (copy) and
    the caller then does `.read()` (copy). Measured on this panel, importing a
    310 MB adapter that way cost **+1.88 GB of RSS** — about 6x the file — and
    the peak lands next to H3's ~40 GiB render footprint. It is fine for the
    reference images and caption bundles it was written for; it is the wrong
    shape for a multi-gigabyte weight file. This walks the same wire format
    with a bounded window instead: the resident cost is one `chunk` plus the
    boundary tail, whatever the adapter weighs.

    Deliberately narrow. It reads the ONE file field the caller names and does
    not pretend to be a general parser — no nested multipart, no base64
    Content-Transfer-Encoding (browsers do not send it for file inputs, and
    silently mis-decoding weights is worse than refusing).
    """
    delim = _multipart_boundary(ctype)
    remaining = max(0, int(content_length))
    buf = bytearray()

    def pull() -> bool:
        nonlocal remaining
        if remaining <= 0:
            return False
        got = rfile.read(min(chunk, remaining))
        if not got:
            remaining = 0
            return False
        remaining -= len(got)
        buf.extend(got)
        return True

    def read_line(limit: int = 8192) -> bytes:
        while True:
            i = buf.find(b"\r\n")
            if i >= 0:
                line = bytes(buf[:i])
                del buf[: i + 2]
                return line
            if len(buf) > limit:
                raise ValueError("malformed multipart/form-data body")
            if not pull():
                raise ValueError("truncated multipart/form-data body")

    needle = b"\r\n" + delim
    keep = len(needle) - 1

    def drain_into(sink) -> None:
        """Copy this part's payload to `sink` up to the closing boundary."""
        while True:
            i = buf.find(needle)
            if i >= 0:
                if i:
                    sink(bytes(buf[:i]))
                del buf[: i + len(needle)]
                return
            if len(buf) > keep:
                cut = len(buf) - keep
                sink(bytes(buf[:cut]))
                del buf[:cut]
            if not pull():
                raise ValueError(
                    "truncated multipart/form-data body — no closing boundary")

    def discard_rest() -> None:
        """Leave the socket at the end of the body. The response is written
        after this returns, and a connection with unread request bytes on it
        is a connection the next request reads garbage from."""
        nonlocal remaining
        buf.clear()
        while remaining > 0:
            got = rfile.read(min(chunk, remaining))
            if not got:
                break
            remaining -= len(got)

    # Preamble, then the opening delimiter.
    while True:
        if read_line().rstrip() == delim:
            break

    fields: dict[str, str] = {}
    while True:
        raw_headers = bytearray()
        while True:
            line = read_line()
            if not line:
                break
            raw_headers.extend(line + b"\r\n")
        part = BytesParser(policy=policy.default).parsebytes(
            bytes(raw_headers) + b"\r\n")
        name = part.get_param("name", header="content-disposition")
        filename = part.get_filename()
        cte = str(part.get("content-transfer-encoding") or "").strip().lower()
        if cte and cte not in ("binary", "8bit", "7bit"):
            raise ValueError(
                f"unsupported Content-Transfer-Encoding {cte!r} on {name!r}")

        if filename is not None and name == field_name:
            def drain(fh, max_bytes: int | None = None) -> int:
                written = 0

                def sink(block: bytes) -> None:
                    nonlocal written
                    written += len(block)
                    if max_bytes is not None and written > max_bytes:
                        raise MultipartTooLarge(
                            f"upload exceeds {max_bytes // (1024 * 1024)} MB")
                    fh.write(block)

                try:
                    drain_into(sink)
                finally:
                    discard_rest()
                return written

            # A caller may refuse the upload BEFORE draining it — a wrong
            # extension, a name already in the library — and would then leave
            # the whole adapter sitting unread on the socket. Today that is
            # survivable only because this handler never sets
            # `protocol_version`, so HTTP/1.0 closes after every response; the
            # storyboard-edit docstring in do_GET already names that same
            # dependency ("turning on keep-alive would make those bytes the
            # head of the next response"). This route would make that latent
            # hazard a multi-gigabyte one, so it does not lean on it.
            drain.discard = discard_rest
            return str(filename), drain, fields

        # Not the field we were asked for: consume it, keeping only a small
        # head of a text field so ordinary form values still reach the caller.
        collected = bytearray()

        def skip(block: bytes, _c=collected) -> None:
            if len(_c) < 64 * 1024:
                _c.extend(block[: 64 * 1024 - len(_c)])

        drain_into(skip)
        if filename is None and name:
            fields[str(name)] = collected.decode("utf-8", "replace")

        while len(buf) < 2 and pull():
            pass
        if bytes(buf[:2]) == b"--":
            raise ValueError(f"no {field_name!r} file field in the upload")
        read_line()


# User-provided captions. Industry convention: `image_001.png` pairs with
# `image_001.txt` (same stem) in the same upload. Caption body uses LTX's
# canonical format:
#   [VISUAL]: <trigger>, <50-80 word description of what VARIES in this shot>
#   [TEXT]: None
# See ~/.claude/skills/ltx-lora/SKILL.md (caption rules) and Aria_v2 / Bizarro_v2
# datasets for validated examples.
TRAIN_CAPTION_EXTS = {".txt", ".json"}            # .json reserved for future
TRAIN_CAPTION_MAX_BYTES = 64 * 1024              # 64 KB per caption (huge headroom)

# /train/upload-bundle limits — covers 50 images × ~10 MB each, plus captions.
TRAIN_BUNDLE_MAX_BYTES = 500 * 1024 * 1024        # 500 MB upper bound
TRAIN_BUNDLE_MAX_ENTRIES = 200                    # paranoia cap on ZIP entries
# Allowed entry name pattern — basename only, no subdirs, no path traversal.
#
# 2026-08-16 (#61): the old pattern was `[A-Za-z0-9_\-]{1,64}` + a
# lower-case extension, which silently rejected the filenames people
# actually have. A user dropped 18 images and 12 arrived; the six that
# vanished were ordinary names. All of these FAILED:
#
#     image (1).png     parentheses — what every browser download looks like
#     shot 04.png       a space
#     ComfyUI.00012.png a dot inside the stem
#     IMG_2213.PNG      an upper-case extension
#
# Path safety never depended on this regex: the caller already reduces the
# entry to `Path(info.filename).name`, and Pass 1 RENUMBERS every image on
# save, so the user's characters never reach the filesystem. The pattern's
# only real job is to keep out separators, control characters and the wrong
# file types. It now says exactly that instead of also enforcing a house
# style nobody was told about.
TRAIN_BUNDLE_NAME_RE = re.compile(
    r"^(?![.\s])[^/\\\x00-\x1f]{1,120}\.(?:png|jpe?g|webp|txt)$",
    re.IGNORECASE,
)

# Voice clip rules. The voice clip is optional — if the user uploads one and
# flips the toggle, run_train_job_inner chains a second `lora_lab.train_audio`
# subprocess after the face phase. The clip itself is preserved under the
# dataset dir as `voice.<ext>` (single file, overwrites on re-upload) and
# copied to LORAS_DIR/<trigger>.voice.<ext> on success so the Characters tab
# can find it.
TRAIN_VOICE_EXTS = {".wav", ".mp3", ".m4a", ".flac"}
TRAIN_VOICE_MAX_BYTES = 50 * 1024 * 1024         # 50 MB
TRAIN_VOICE_MIN_SECONDS = 3                       # advisory; we don't ffprobe
TRAIN_VOICE_MAX_SECONDS = 60                      # advisory; we don't ffprobe

# Audio-phase defaults. Measured ~4 s/step on M4 Max during an end-to-end
# voice-LoRA run on 2026-05-15 (250 steps in 17 min). The original 30 s/step
# heuristic massively overestimated — chip labels were showing 2 h for what
# is actually ~17 min, scaring users off the voice phase. The audit's earlier
# 24 s/step number conflated preprocess + setup time with pure training.
TRAIN_AUDIO_DEFAULT_STEPS = 250
TRAIN_AUDIO_DEFAULT_RANK = 16
TRAIN_AUDIO_DEFAULT_LR = 1e-4
TRAIN_AUDIO_SLICE_SECONDS = 4.0
TRAIN_AUDIO_SECONDS_PER_STEP = 4.0                # heuristic for ETA strip


def _existing_voice_file(dataset_dir: Path) -> Path | None:
    """Return the single voice clip in `<dataset_dir>/voice.*` if present.
    Only the file's stem matters — extension picks among TRAIN_VOICE_EXTS."""
    if not dataset_dir.is_dir():
        return None
    for ext in TRAIN_VOICE_EXTS:
        candidate = dataset_dir / f"voice{ext}"
        if candidate.is_file():
            return candidate
    return None

# Counter for new training-job ids — short, sortable, unique-per-day.
_TRAIN_COUNTER = 0
_TRAIN_COUNTER_LOCK = threading.Lock()


def _new_train_job_id() -> str:
    """Return a short identifier like `trn-20260510-1430-a3` — sortable,
    human-scannable, unique per panel run (the suffix counter avoids
    collisions within the same minute)."""
    global _TRAIN_COUNTER
    with _TRAIN_COUNTER_LOCK:
        _TRAIN_COUNTER += 1
        n = _TRAIN_COUNTER
    ts = time.strftime("%Y%m%d-%H%M")
    suffix = base36 = ""
    # Two-char base36 to keep the id terse; rolls over after ~1300 calls.
    _v = n
    alpha = "0123456789abcdefghijklmnopqrstuvwxyz"
    while _v > 0 and len(base36) < 3:
        base36 = alpha[_v % 36] + base36
        _v //= 36
    suffix = (base36 or "0").rjust(2, "0")
    return f"trn-{ts}-{suffix}"


def _train_dataset_dir(job_id: str) -> Path:
    """Per-job dataset folder. Holds images/, captions/, spec.json."""
    p = TRAIN_DIR / job_id
    return p


def _safe_job_id(job_id: str) -> str:
    """Reject anything that isn't `^[A-Za-z0-9_-]+$`. Prevents
    path-traversal via crafted job_id form values."""
    if not job_id or not re.fullmatch(r"[A-Za-z0-9_\-]+", job_id):
        raise ValueError(f"invalid job_id: {job_id!r}")
    if len(job_id) > 64:
        raise ValueError("job_id too long")
    return job_id


def _normalise_caption_text(text: str, trigger: str | None = None) -> str:
    """Coerce a caption body into LTX format:
        [VISUAL]: <trigger>, <description>
        [TEXT]: <on-screen text or None>

    Forgiving on input shape:
      * Strips BOM + CRLF.
      * If the first non-empty line lacks `[VISUAL]:` and a trigger is known,
        prepend `[VISUAL]: <trigger>, ` — only when the line doesn't already
        start with the trigger (avoid double-trigger).
      * If `[TEXT]:` is missing entirely, append `[TEXT]: None`.

    Does not enforce content rules — the UI surfaces a soft warning when the
    caption is < 10 words. Returns a normalised string ready to write to disk.
    """
    if not text:
        return ""
    # Strip UTF-8 BOM + normalise line endings.
    text = text.lstrip("﻿").replace("\r\n", "\n").replace("\r", "\n").strip()

    # Auto-prepend [VISUAL]: when missing. Match case-insensitive at the
    # very start of the first non-empty line.
    if not re.match(r"^\s*\[VISUAL\]\s*:", text, re.IGNORECASE):
        prefix = "[VISUAL]: "
        first_line = text.split("\n", 1)[0].strip()
        if trigger and first_line.lower().startswith(trigger.lower()):
            # Line already starts with trigger — just add the [VISUAL]: tag.
            text = prefix + text
        elif trigger:
            # No trigger yet; add `[VISUAL]: <trigger>, ` so the trainer sees a
            # token at position 0 of the [VISUAL]: body.
            text = f"{prefix}{trigger}, {text}"
        else:
            text = prefix + text

    # Auto-append [TEXT]: None if absent.
    if not re.search(r"^\s*\[TEXT\]\s*:", text, re.IGNORECASE | re.MULTILINE):
        text = text.rstrip() + "\n[TEXT]: None"
    return text + ("\n" if not text.endswith("\n") else "")


def _decode_caption_bytes(data: bytes) -> str:
    """Best-effort UTF-8 decode; fall back to latin-1 for legacy Win-1252
    captions. Strip nothing — `_normalise_caption_text` handles cleanup."""
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        return data.decode("latin-1", errors="replace")


def _caption_word_count(text: str) -> int:
    """Cheap word count for the < 10 words warning. Excludes the `[VISUAL]:` /
    `[TEXT]:` tag tokens so a sparse `[VISUAL]: bizarrotrn, man` doesn't read
    as 4 words and slip past the threshold."""
    body = re.sub(r"\[(?:VISUAL|TEXT)\]\s*:", " ", text, flags=re.IGNORECASE)
    return len([w for w in re.split(r"\s+", body.strip()) if w])


# ---------- Caption ↔ Image pairing helpers ----------------------------------
# Each training dataset records a `caption_map.json` next to images/ + captions/
# that maps the user's original filename stem (e.g. `image_001`) to the
# panel-renumbered saved stem (e.g. `char_001`). This lets a user upload
# `image_001.png` + `image_001.txt` in any order and have them pair correctly.

_TRAIN_CAPTION_MAP_NAME = "caption_map.json"


def _train_caption_map_path(dataset_dir: Path) -> Path:
    return dataset_dir / _TRAIN_CAPTION_MAP_NAME


def _train_read_caption_map(dataset_dir: Path) -> dict[str, str]:
    p = _train_caption_map_path(dataset_dir)
    if not p.is_file():
        return {}
    try:
        data = json.loads(p.read_text(encoding="utf-8"))
        if isinstance(data, dict):
            return {str(k): str(v) for k, v in data.items()
                    if isinstance(k, str) and isinstance(v, str)}
    except (OSError, json.JSONDecodeError):
        pass
    return {}


def _train_write_caption_map(dataset_dir: Path, mapping: dict[str, str]) -> None:
    p = _train_caption_map_path(dataset_dir)
    try:
        p.write_text(json.dumps(mapping, indent=2), encoding="utf-8")
    except OSError:
        pass


def _train_set_caption_map_entry(dataset_dir: Path,
                                 original_stem: str,
                                 saved_stem: str) -> None:
    m = _train_read_caption_map(dataset_dir)
    m[original_stem] = saved_stem
    _train_write_caption_map(dataset_dir, m)


def _train_reconcile_one(dataset_dir: Path,
                         original_stem: str,
                         saved_stem: str) -> bool:
    """If a caption file exists under `original_stem.txt`, rename it to
    `saved_stem.txt`. Used when the user uploads `image_001.txt` BEFORE its
    matching `image_001.png` arrives. Returns True if a paired caption now
    sits under `<captions>/<saved_stem>.txt`."""
    captions_dir = dataset_dir / "captions"
    saved_path = captions_dir / f"{saved_stem}.txt"
    if saved_path.is_file():
        return True
    if original_stem == saved_stem:
        return False
    parked = captions_dir / f"{original_stem}.txt"
    if parked.is_file():
        try:
            parked.rename(saved_path)
            return True
        except OSError:
            return False
    return False


def _train_reconcile_captions(dataset_dir: Path) -> tuple[int, int, list[str]]:
    """Called on training start. Walks images/ + captions/, ensures every
    caption under an *original* stem in caption_map.json is moved to its
    saved stem so the trainer's per-image lookup hits. Returns
    (paired_count, total_images, warnings)."""
    images_dir = dataset_dir / "images"
    captions_dir = dataset_dir / "captions"
    cmap = _train_read_caption_map(dataset_dir)
    if not images_dir.is_dir():
        return 0, 0, ["images dir missing"]
    images = [p for p in sorted(images_dir.iterdir())
              if p.is_file() and p.suffix.lower() in TRAIN_IMAGE_EXTS]
    total = len(images)
    warnings: list[str] = []
    if not captions_dir.is_dir():
        return 0, total, warnings
    for original, saved in cmap.items():
        if original == saved:
            continue
        parked = captions_dir / f"{original}.txt"
        target = captions_dir / f"{saved}.txt"
        if parked.is_file() and not target.is_file():
            try:
                parked.rename(target)
            except OSError as e:
                warnings.append(f"could not move {parked.name} → {target.name}: {e}")
    paired = sum(1 for img in images
                 if (captions_dir / f"{img.stem}.txt").is_file())
    return paired, total, warnings


def _suggest_trigger_token() -> str:
    """Generate a rare, LETTERS-ONLY token of the form `<3 consonants>trn`
    (e.g. `mrztrn`, `kvdtrn`).

    The previous shape was `<3 consonants><2 digits>` (`mrz07`). Through
    Gemma's tokenizer that is `m / rz / 0 / 7` — two of the four pieces
    are single digits, among the most common tokens the model knows, with
    a prior that has nothing to do with a face. Every trigger that has
    ever carried an identity here is letters-only and ends in `trn`
    (`bizarrotrn` -> b / izarro / trn; `elontrn`; `ariatrn`), and the
    trainings reported in #62 as "active but no identity" all used the
    digit shape the panel itself suggested (`mmx26`, `sfw25`, `3Mar26`).
    Whether the digits are THE cause is being A/B'd; suggesting the shape
    that is known to work costs nothing. `trn` keeps the family readable
    at a glance in the LoRA list; three consonants keep it phonotactically
    rare in English (no common bigrams like 'th', 'st', 'sh').
    """
    consonants = "bcdfghjkmnpqrstvwxyz"
    while True:
        letters = "".join(random.choice(consonants) for _ in range(3))
        # Reject anything that happens to spell a common letter pattern.
        if letters in ("the", "and", "for", "but"):
            continue
        token = letters + "trn"
        # Stay clear of an adapter the user already has under this name
        # (the digit tail used to be what avoided that clash).
        try:
            if (LORAS_DIR / f"{token}_v2.safetensors").exists() or \
               (LORAS_DIR / f"{token}.style.safetensors").exists():
                continue
        except Exception:  # noqa: BLE001 — LORAS_DIR unset this early is fine
            pass
        return token


def _train_estimate_seconds(preset: str, image_count: int, *,
                            steps_override: int | None = None,
                            is_style: bool = False) -> int:
    """Wall-time estimate in seconds for a training run. The image count
    has a small overhead for the preprocess pass (image → VAE latent
    cache, ~3 s/image on M4 Max), then `steps * seconds_per_step` for
    the train loop itself.

    `is_style` switches the preset lookup table — style training pulls
    its seconds_per_step from TRAIN_STYLE_PRESETS, not TRAIN_PRESETS."""
    table = TRAIN_STYLE_PRESETS if is_style else TRAIN_PRESETS
    cfg = table.get(preset) or table["quick"]
    # Steps derive from epochs × image_count; advanced override wins.
    steps = steps_override if steps_override else _preset_steps_for(cfg, image_count)
    preprocess = 3.0 * max(0, image_count)
    train = float(steps) * float(cfg["seconds_per_step"])
    return int(preprocess + train + 30)  # +30 s for setup + checkpoint write


def _train_list_completed() -> list[dict]:
    """Scan mlx_models/loras/ for .safetensors with a Phosphene-trained
    sidecar (`kind=train_character` OR `kind=train_style`) and return one
    record per discovered run for the Trained-LoRAs list in the Train tab.
    Surfacing both kinds in a single list lets the user see their full
    training inventory in one place; the UI filters by `train_type` to show
    the kind that matches the active train-type toggle (and lists everything
    when "All" is selected)."""
    out: list[dict] = []
    if LORAS_DIR.exists():
        for p in sorted(LORAS_DIR.iterdir(),
                        key=lambda x: x.stat().st_mtime if x.exists() else 0,
                        reverse=True):
            if p.suffix.lower() != ".safetensors":
                continue
            # Style LoRAs use a `.style.safetensors` suffix, so the sidecar
            # is `.style.json` not `.json`. Probe both paths.
            sidecar_candidates = [p.with_suffix(".json")]
            if p.name.endswith(".style.safetensors"):
                sidecar_candidates.insert(
                    0, p.with_name(p.name[: -len(".safetensors")] + ".json")
                )
            sidecar = next((s for s in sidecar_candidates if s.is_file()), None)
            if sidecar is None:
                continue
            try:
                meta = json.loads(sidecar.read_text(encoding="utf-8"))
            except Exception:
                continue
            kind = meta.get("kind")
            if kind not in ("train_character", "train_style"):
                continue
            try:
                stat = p.stat()
            except OSError:
                continue
            verdict = _adapter_verdict(meta)
            out.append({
                "id": meta.get("job_id") or p.stem,
                "name": meta.get("name") or p.stem,
                "trigger": meta.get("trigger") or "",
                "preset": meta.get("preset") or "",
                "kind": kind,
                "train_type": meta.get("train_type")
                                or ("style" if kind == "train_style"
                                    else "character"),
                "path": str(p),
                "filename": p.name,
                "size_mb": round(stat.st_size / (1024 * 1024), 1),
                "created_at": meta.get("created_at") or stat.st_mtime,
                "image_count": meta.get("image_count") or 0,
                # WHETHER THIS FILE CAN DO ANYTHING, carried out of the
                # sidecar so the library can warn before somebody spends a
                # render finding out. "unknown" for anything trained by a
                # build that did not measure — silence is not weakness, and a
                # chip on every older LoRA would be noise nobody could act on.
                "adapter_verdict": verdict,
                # AND WHAT TO DO ABOUT IT. A verdict the user cannot act on
                # sends them to a GitHub thread to find out what their own
                # number meant (#62); the remedy travels with the verdict, and
                # is hardware-aware because on a sub-64 GB Mac "use High" is
                # not a thing that machine can do.
                "adapter_advice": (
                    _train_weak_advice(
                        verdict,
                        str(meta.get("preset") or ""),
                        kind == "train_style",
                    )
                    if verdict not in ("ok", "unknown") else ""
                ),
            })
    return out


def _adapter_verdict(meta: dict) -> str:
    """`ok` | `unknown` | whatever the trainer called it.

    A LoRA can train to completion, write a valid safetensors, load without a
    warning and change NOTHING — the deltas it learned are numerically too
    small to move the model. Every gate we had said "done"; only the render
    said otherwise. This is the one field that knows.
    """
    a = (meta or {}).get("adapter_strength")
    if isinstance(a, dict):
        v = str(a.get("verdict") or "unknown").lower()
        return v if v else "unknown"
    return "unknown"


def _train_weak_advice(verdict: str, preset: str = "", is_style: bool = False) -> str:
    """One sentence a user can ACT on when their adapter measures weak/inert.

    The measurement shipped in v4.6.0 and the number was correct; what it did
    not do was tell anyone what to do about it. A first-time user on the Quick
    preset read "1.98e-04", found nothing in the panel that explained it, and
    ended up reading a 21-comment GitHub thread to learn that rank 8 has never
    carried a face (#62). The verdict without the remedy is the actual product
    failure in that issue.

    The remedy is hardware-dependent, which is why this is a function and not
    a constant: on a Mac under 64 GB `_select_train_profile` rewrites the whole
    table and *High is rank 8 at 500 steps on two projections*, so "train again
    on High" would be advice that machine cannot honour.
    """
    verdict = (verdict or "").lower()
    if verdict == "inert":
        return (
            "This adapter carries no weight delta at all — every low-rank "
            "product is exactly zero, so it cannot change a single pixel. "
            "Treat the run as failed rather than as a weak result: nothing "
            "was learned. Check the Logs for a trainer error, then train "
            "again."
        )
    compact = bool(TRAIN_PROFILE.get("compact"))
    if is_style:
        head = ("This style adapter came out weak: the deltas it learned may "
                "be too small to visibly change a render.")
    else:
        head = ("This character came out weak: the deltas it learned are "
                "below the level any adapter that has carried a face here "
                "has ever measured, so renders will most likely look "
                "LoRA-free.")
    if compact:
        ram = TRAIN_PROFILE.get("ram_gb")
        where = f"{ram} GB" if ram else "under 64 GB"
        return (
            f"{head} This Mac has {where}, so training runs the compact "
            "profile — even High is rank 8 / 500 steps / 448px on two of the "
            "four attention projections, not the rank-32 recipe that was "
            "graded on a face. No preset on this machine reaches that recipe, "
            "so this is the hardware and not your photos. More images and "
            "sharper, more varied ones still help; a 64 GB-class Mac is what "
            "unlocks the graded recipe."
        )
    if (preset or "").lower() != "high":
        return (
            f"{head} Train again on the High preset — rank 8 (Quick) and "
            "rank 16 (Medium) have never carried an identity here, and High "
            "is the only recipe that has. Raising the character strength "
            "toward 2.0 helps a weak adapter a little; it cannot rescue one "
            "this far under the floor."
        )
    return (
        f"{head} This was already the High preset, so the next levers are the "
        "dataset rather than the recipe: more images (20-40), sharper and more "
        "varied in pose and lighting, and captions that name the trigger plainly. "
        "Please attach the training log to https://github.com/mrbizarro/phosphene/issues/62 "
        "— a weak High run is the case that issue is still open on."
    )


def _train_required_models() -> list[dict]:
    """Return the list of model files Train Character needs and whether each
    is present locally. Surfaces missing models to the UI so the user can
    one-click download them via the existing hf flow.

    Train Character requires the FULL-PRECISION `transformer-dev.safetensors`
    from the LTX-2.3 Q8 repo (~21 GB). The dev base is required because
    distilled is structurally wrong for training (different sigma schedule
    than the trainer's flow-matching objective) — and it must be the Q8
    repo's full-precision copy because the Q4 repo's transformer-dev is
    QUANTIZED (~11 GB): the trainer refuses it (train.py's
    FULL_DEV_MIN_BYTES) since it silently trains a near-zero LoRA (#35).
    The default install ships neither, to save disk for inference-only
    users.

    Gemma + the rest of the Q4 stack (vae, audio, etc.) are already required
    for inference so they should already be present, but we check anyway.
    """
    q4_local_dir = ROOT / "mlx_models" / "ltx-2.3-mlx-q4"
    q8_local_dir = ROOT / "mlx_models" / "ltx-2.3-mlx-q8"
    gemma_local_dir = ROOT / "mlx_models" / "gemma-3-12b-it-4bit"
    gemma_repo_id = "mlx-community/gemma-3-12b-it-4bit"

    def _file_present(local_dir: Path, repo_id: str, filename: str,
                      *, extra_dirs: list[Path] | None = None,
                      min_bytes: int = _MIN_FILE_BYTES) -> bool:
        """Check known locations for a model file in this order:

          1. The primary local_dir (where the helper expects it by default).
          2. Any `extra_dirs` callers list explicitly — used for files that
             can legitimately live in more than one place. The dev
             transformer is the canonical example: original downloads
             land in mlx_models/ltx-2.3-mlx-q4/ but Phosphene also ships
             a Q8-friendly copy under mlx_models/ltx-2.3-mlx-q8/, and the
             trainer happily loads either. Without this fallback the
             preflight reports "missing" on installs that only have the
             Q8-side copy and prompts an unnecessary 11 GB redownload.
          3. The configured HF_HOME hub for repo_id.
          4. The user-default HF cache (~/.cache/huggingface/hub) — covers
             installs where HF_HOME wasn't set at first download time and
             weights landed in the default location.
        """
        candidates: list[Path] = [local_dir / filename]
        for d in (extra_dirs or []):
            candidates.append(d / filename)
        cache_dir = _repo_hf_cache_dir(repo_id)
        if cache_dir is not None:
            candidates.append(cache_dir / filename)
        # Last-resort: default HF cache, regardless of HF_HOME. Matches what
        # huggingface_hub does when neither env var is set. Old downloads
        # often live here even when HF_HOME is now pointing elsewhere.
        safe = repo_id.replace("/", "--")
        default_root = Path.home() / ".cache" / "huggingface" / "hub" / f"models--{safe}" / "snapshots"
        try:
            if default_root.is_dir():
                snaps = sorted(default_root.iterdir(),
                               key=lambda d: d.stat().st_mtime, reverse=True)
                if snaps:
                    candidates.append(snaps[0] / filename)
        except OSError:
            pass
        for c in candidates:
            try:
                if c.exists() and c.stat().st_size >= min_bytes:
                    return True
            except OSError:
                continue
        return False

    # Mirror of lora_lab/train.py FULL_DEV_MIN_BYTES: anything smaller is a
    # quantized transformer-dev, which the trainer refuses. The preflight
    # must not show green on a file the trainer will reject (#35).
    _FULL_DEV_MIN_BYTES = 15 * 1000**3

    items = [
        {
            # THE ASSUMPTION THAT EXPIRED. This function's own docstring says
            # "the rest of the Q4 stack (vae, audio, etc.) are already required
            # for inference so they should already be present" — true right up
            # until v4.0, when a fresh install stopped fetching LTX-2.3 at all.
            # The trainer runs against 2.3 and needs its VAE, audio VAE and
            # vocoder; without this row the Train tab would have looked ready
            # and failed at load time on a pack nobody told the user about.
            "key": "ltx23_base",
            "label": "LTX-2.3 base pack (training runs against 2.3)",
            "blurb": "The trainer runs against LTX-2.3, not 2.5 — it needs 2.3's "
                     "VAE, audio VAE and vocoder. Your clips still render on "
                     "LTX-2.5; this is training-only. A fresh v4.0 install does "
                     "not download it, so it is fetched when you want to train.",
            "repo_id": "dgrauet/ltx-2.3-mlx-q4",
            "filename": "vae_decoder.safetensors",
            "local_dir": str(q4_local_dir),
            "size_gb": 20.48,
            "ready": _file_present(q4_local_dir, "dgrauet/ltx-2.3-mlx-q4",
                                   "vae_decoder.safetensors"),
        },
        {
            "key": "ltx_dev_transformer",
            "label": "LTX-2.3 dev transformer (training-only, full precision)",
            "blurb": "Required for training. Standard inference uses the distilled "
                     "transformer instead; the dev transformer has the right "
                     "flow-matching schedule for LoRA-from-images training. "
                     "Must be the full-precision (~21 GB) copy — a quantized "
                     "dev transformer trains a LoRA that never applies.",
            "repo_id": "dgrauet/ltx-2.3-mlx-q8",
            "filename": "transformer-dev.safetensors",
            "local_dir": str(q8_local_dir),
            "size_gb": 20.6,
            # Size-gated: an 11 GB quantized dev (the old preflight's Q4
            # download, still on many disks) must show NOT-ready, because
            # the trainer refuses it and the LoRA comes out dead (#35).
            "ready": _file_present(q8_local_dir, "dgrauet/ltx-2.3-mlx-q8",
                                   "transformer-dev.safetensors",
                                   extra_dirs=[q4_local_dir],
                                   min_bytes=_FULL_DEV_MIN_BYTES),
        },
        {
            "key": "gemma_text_encoder",
            "label": "Gemma 3 12B (text encoder)",
            "blurb": "Encodes prompts for both inference and training. Already "
                     "required by Phosphene's renderer, so this is usually green.",
            "repo_id": gemma_repo_id,
            "filename": "config.json",
            "local_dir": str(gemma_local_dir),
            "size_gb": 6.0,
            "ready": _file_present(gemma_local_dir, gemma_repo_id, "config.json"),
        },
    ]
    return items


def _train_install_dev_transformer(push_log) -> dict:
    """Trigger an hf download for just `transformer-dev.safetensors` from
    the LTX-2.3 Q8 repo — the FULL-PRECISION copy the trainer requires.
    (Until v3.4.1 this pulled the Q4 repo's transformer-dev, which is
    quantized: the trainer refuses it and the LoRA trains dead — #35.)
    Reuses the same `hf download` binary the existing
    HF download flow uses; runs synchronously in a worker thread so the
    caller can stream progress (the panel currently invokes this from a
    /train/install endpoint that returns quickly + then polls /status).

    Returns {"ok": True, "started": True, "repo_id": ...} or {"ok": False,
    "error": "..."} if the download couldn't be started (already running,
    binary missing, etc.).
    """
    import subprocess
    if DOWNLOAD["active"]:
        return {"ok": False,
                "error": f"another download is already active "
                         f"({DOWNLOAD.get('repo_id', '?')})."}

    repo_id = "dgrauet/ltx-2.3-mlx-q8"
    local_dir = ROOT / "mlx_models" / "ltx-2.3-mlx-q8"
    local_dir.mkdir(parents=True, exist_ok=True)

    hf_bin = HF_BIN if HF_BIN is not None else _resolve_hf()
    if hf_bin is None:
        return {"ok": False, "error": "hf CLI not found on PATH."}

    cmd = [str(hf_bin), "download", repo_id,
           "--include", "transformer-dev.safetensors",
           "--local-dir", str(local_dir)]

    env = dict(os.environ)
    hf_token = _active_hf_token()
    if hf_token:
        env["HF_TOKEN"] = hf_token
        env["HUGGING_FACE_HUB_TOKEN"] = hf_token

    with DOWNLOAD_LOCK:
        DOWNLOAD["active"] = True
        DOWNLOAD["key"] = "ltx_dev_transformer"
        DOWNLOAD["repo_id"] = repo_id
        DOWNLOAD["started_ts"] = time.time()
        DOWNLOAD["last_line"] = ""

    def _runner():
        try:
            push_log(f"[hf] dev transformer download started "
                     f"({repo_id} / transformer-dev.safetensors, ~21 GB — "
                     f"the full-precision copy training requires).")
            proc = subprocess.Popen(
                cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, bufsize=1, env=env, start_new_session=True)
            with DOWNLOAD_LOCK:
                DOWNLOAD["proc"] = proc
                try:
                    DOWNLOAD["pgid"] = os.getpgid(proc.pid)
                except ProcessLookupError:
                    DOWNLOAD["pgid"] = None
            buf = ""
            assert proc.stdout is not None
            while True:
                ch = proc.stdout.read(1)
                if not ch:
                    break
                if ch in ("\n", "\r"):
                    line = buf.strip()
                    buf = ""
                    if line:
                        with DOWNLOAD_LOCK:
                            DOWNLOAD["last_line"] = line[:200]
                        push_log(f"[hf:dev] {line[:300]}")
                else:
                    buf += ch
            rc = proc.wait()
            if rc == 0:
                push_log("[hf] dev transformer downloaded successfully.")
            else:
                push_log(f"[hf] dev transformer download exited with code {rc}.")
        except Exception as exc:
            push_log(f"[hf] dev transformer crashed: {exc}")
        finally:
            with DOWNLOAD_LOCK:
                DOWNLOAD["active"] = False
                DOWNLOAD["key"] = None
                DOWNLOAD["repo_id"] = None
                DOWNLOAD["started_ts"] = None
                DOWNLOAD["last_line"] = ""
                DOWNLOAD["proc"] = None
                DOWNLOAD["pgid"] = None

    threading.Thread(target=_runner, daemon=True, name="hf-dev-download").start()
    return {"ok": True, "started": True, "repo_id": repo_id,
            "filename": "transformer-dev.safetensors"}


# One in-flight Turbo fetch at a time, mirroring the sample-character lane:
# a daemon thread streaming to .partial, sha256 + exact-size verified, and an
# atomic rename so a killed download never leaves a file h3_turbo_paths()
# would resolve. status: idle | downloading | done | error.
_h3_turbo_dl_lock = threading.Lock()
# total_mb is a plain literal here because the H3_TURBO_ASSET_* pins are
# declared with the rest of the Turbo constants further down; every writer
# below stamps the real total at runtime.
_h3_turbo_dl_state: dict = {"status": "idle", "mb": 0, "total_mb": 0,
                            "error": None}


def _set_h3_turbo_dl(**kw) -> None:
    with _h3_turbo_dl_lock:
        _h3_turbo_dl_state.clear()
        _h3_turbo_dl_state.update(kw)


def _h3_turbo_asset(key: str | None = None) -> dict:
    """The managed adapter to fetch: v4-600 EMA from its author's repo by
    default; the LightX2V release asset when asked for by key."""
    key = key or H3_TURBO_DEFAULT_ASSET
    if key in H3_TURBO_ASSETS:
        return dict(H3_TURBO_ASSETS[key], key=key)
    return {"key": "v1.0", "file": H3_TURBO_LORA_FILE, "url": H3_TURBO_ASSET_URL,
            "sha256": H3_TURBO_ASSET_SHA256, "bytes": H3_TURBO_ASSET_BYTES}


def _h3_turbo_download_bg(target_dir, push_log, asset: dict | None = None) -> None:
    """Stream the digest-pinned v1.0 repack release asset into the H3 pack."""
    import urllib.request
    import hashlib
    asset = asset or _h3_turbo_asset()
    total_mb = asset['bytes'] // (1 << 20)
    tmp = None
    try:
        target_dir.mkdir(parents=True, exist_ok=True)
        target = target_dir / asset['file']
        if target.is_file():
            _set_h3_turbo_dl(status="done", mb=total_mb, total_mb=total_mb,
                             error=None)
            return
        tmp = target.with_suffix(target.suffix + ".partial")
        push_log(f"[h3:turbo] downloading {asset['file']} "
                 f"(~{total_mb} MB)…")
        req = urllib.request.Request(asset['url'],
                                     headers={"User-Agent": "Phosphene"})
        h = hashlib.sha256()
        written = 0
        last_log = 0.0
        with urllib.request.urlopen(req, timeout=60) as resp, \
                open(tmp, "wb") as fh:
            while True:
                chunk = resp.read(1 << 20)
                if not chunk:
                    break
                fh.write(chunk)
                h.update(chunk)
                written += len(chunk)
                now = time.time()
                if now - last_log > 2.5:
                    _set_h3_turbo_dl(status="downloading",
                                     mb=written // (1 << 20),
                                     total_mb=total_mb, error=None)
                    push_log(f"[h3:turbo] {written // (1 << 20)} / "
                             f"{total_mb} MB")
                    last_log = now
        if written != asset['bytes']:
            raise RuntimeError(
                f"size mismatch: got {written}, expected "
                f"{asset['bytes']} — please retry")
        if h.hexdigest() != asset['sha256']:
            raise RuntimeError("checksum mismatch (download corrupt) — "
                               "please retry")
        tmp.replace(target)
        _set_h3_turbo_dl(status="done", mb=total_mb, total_mb=total_mb,
                         error=None)
        push_log(f"[h3:turbo] adapter installed → {target}")
    except Exception as e:  # noqa: BLE001
        if tmp is not None:
            try:
                tmp.unlink()
            except OSError:
                pass
        _set_h3_turbo_dl(status="error", mb=0, total_mb=total_mb,
                         error=str(e)[:200])
        push_log(f"[h3:turbo] FAILED: {e}")


def _h3_install_turbo(push_log, download_fn=None) -> dict:
    """Fetch the digest-pinned runner-layout Turbo adapter on demand.

    The v1.0 repack is a published release asset with a pinned SHA-256
    (H3_TURBO_ASSET_SHA256, verified byte-identical against the repack the
    adapter selection was graded on). The raw LightX2V v0.1 file is still
    refused by name in the resolver: its alpha/rank factor lives outside the
    checkpoint, and at scale 1.0 it renders coloured noise.
    """
    paths = h3_paths()
    if paths["missing"]:
        return {"ok": False,
                "error": "Turbo is an add-on to the Hailuo H3 pack, and H3 "
                         "isn't fully installed yet: "
                         + "; ".join(paths["missing"])}
    if not h3_supports_lora():
        return {"ok": False,
                "error": "This Hailuo H3 checkout predates Turbo (no --lora "
                         "support in its runner). Re-run 'Install Hailuo H3' "
                         "from the Phosphene sidebar in Pinokio to update the "
                         "clone — it keeps every weight already on disk."}
    target = _h3_turbo_dir()
    if any((target / f).is_file() for f, _v, _fb in H3_TURBO_LORA_CANDIDATES):
        return {"ok": True, "started": False, "already_installed": True,
                "dir": str(target)}
    with _h3_turbo_dl_lock:
        if _h3_turbo_dl_state.get("status") == "downloading":
            return {"ok": False,
                    "error": "a Turbo adapter download is already active"}
        _h3_turbo_dl_state.clear()
        _h3_turbo_dl_state.update(status="downloading", mb=0,
                                  total_mb=_h3_turbo_asset()['bytes'] // (1 << 20),
                                  error=None)
    fn = download_fn or _h3_turbo_download_bg
    threading.Thread(target=fn, args=(target, push_log), daemon=True,
                     name="h3-turbo-download").start()
    return {"ok": True, "started": True, "dir": str(target),
            "asset": _h3_turbo_asset()['url'], "sha256": _h3_turbo_asset()['sha256'],
            "bytes": _h3_turbo_asset()['bytes']}


# Compatibility taxonomy for LoRAs across the panel's two render lanes
# (video via ltx_pipelines_mlx + image via mflux). The picker filters its
# library down to LoRAs that can fire with the user's current
# (mode, engine) selection. Source of truth is the CivitAI sidecar's
# `base_model` field; we map that to one or more compat tags.
#
# Compat tag vocabulary used throughout the panel + JS picker:
#   "video"           — LTX-Video LoRAs (any t2v / i2v / keyframe / extend)
#   "video:h3"        — MiniMax / Hailuo H3 LoRAs. Its OWN tag, deliberately
#                       NOT a flavour of "video": the two video engines share
#                       no weight layout and no runner, so an LTX LoRA offered
#                       on the H3 picker is a guaranteed failure rather than a
#                       maybe. The two libraries also live in two directories
#                       (see _h3_loras_dir) so the separation is structural.
#   "image:flux1"     — FLUX.1 [dev] / [schnell] (mflux flux1 family)
#   "image:flux2"     — FLUX.2 (klein-4b) base + Klein-Edit (flux2 + flux2_edit)
#   "image:qwen"      — Qwen-Image / Qwen-Image-Edit (qwen + qwen_edit)
#   "image:sdxl"      — SDXL 1.0 (mflux doesn't run SDXL today; flag for future)
#   "image:z_image"   — Z-Image / Z-Image Turbo (no LoRAs known yet)
#   "image:kontext"   — FLUX.1 Kontext-dev (image-conditioning family)
#   "unknown"         — sidecar missing base_model, or string we can't map.
#                       Surfaced in EVERY filter with a `?` indicator so the
#                       user can still try it (better to show + warn than to
#                       hide and leave the user confused).
def _classify_lora_modes(base_model) -> list[str]:
    """Map a CivitAI `base_model` sidecar string to compat tags.

    CivitAI is wildly inconsistent on this field — different uploaders
    write `Flux.1 D`, `flux 1 d`, `FLUX1`, `Flux1.D`, etc. for the same
    family. We lowercase + substring-match generously rather than
    exact-match. Returns a list because some LoRAs cover both the
    distilled + base flavors of one family.

    Anything we can't classify returns ["unknown"] so the picker can
    still surface it (with a `?` indicator) instead of silently hiding.
    """
    if not base_model:
        return ["unknown"]
    s = str(base_model).strip().lower()
    if not s:
        return ["unknown"]
    # Strip non-alphanumerics into a normalized lookup form so all of
    # "Flux.1 D", "flux1.d", "FLUX-1-D" collapse to "flux1d".
    norm = "".join(ch for ch in s if ch.isalnum())

    tags: list[str] = []
    # ---- Video lane: Hailuo H3 (MiniMax) ----
    # CivitAI's taxonomy string is "MiniMax H3" — VERIFIED 2026-08-09 against
    # the live /models endpoint: `baseModels=MiniMax H3` returns hits while
    # "MiniMax", "Hailuo" and "Hailuo H3" all return zero. Checked BEFORE the
    # LTX branch and returned INSTEAD of "video" (not alongside it), because
    # the whole point of the tag is that these two libraries must never bleed
    # into each other's picker.
    if ("minimax" in norm and "h3" in norm) or "hailuoh3" in norm:
        tags.append("video:h3")
    # ---- Video lane (LTX-Video) ----
    # CivitAI strings include "LTXV 2.3", "LTX-Video", "LTX-2", "LTXV2.3".
    elif "ltx" in norm:
        tags.append("video")
    # ---- Image lane: Qwen ----
    # "Qwen Image", "Qwen-Image-Edit", "Qwen Image Edit 2511" → image:qwen.
    if "qwen" in norm:
        tags.append("image:qwen")
    # ---- Image lane: FLUX.2 ----
    # Match BEFORE the FLUX.1 branch so "flux2" / "flux2d" don't fall
    # through to flux1 via the leading "flux" substring.
    if "flux2" in norm or "flux20" in norm:
        tags.append("image:flux2")
    elif "kontext" in norm:
        # FLUX.1 Kontext is its own image-conditioning model. Tag
        # separately so the kontext_high engine can filter cleanly.
        tags.append("image:kontext")
    elif "flux" in norm and "flux2" not in norm:
        # Catch flux1d, flux1s, flux1, "flux 1", "flux.1 d". The broader
        # `"flux" in norm` is enough for the FLUX.1 family.
        tags.append("image:flux1")
    # ---- Image lane: SDXL ----
    if "sdxl" in norm or "sd_xl" in norm:
        tags.append("image:sdxl")
    # ---- Image lane: Z-Image ----
    if "zimage" in norm or "ztoimage" in norm:
        tags.append("image:z_image")

    return tags or ["unknown"]


def _read_lora_sidecar(safetensors_path: Path) -> dict:
    """Read sidecar JSON next to a .safetensors LoRA. Falls back to bare
    filename + zero metadata when no sidecar is present, so users can
    drop in a raw .safetensors and get a usable picker entry without
    writing any metadata themselves.

    Sidecar schema (inspired by CivitAI's model JSON, kept compatible
    so a CivitAI download just writes its native shape):

      {
        "name": "Cinematic Post-Apocalyptic",
        "description": "...",
        "trigger_words": ["postapoc", "wasteland"],   // optional
        "recommended_strength": 0.8,                   // 0.0..1.5 typical
        "civitai_id": 2563394,                         // optional
        "civitai_version_id": 2880457,                 // optional
        "preview_url": "https://...",                  // optional
        "base_model": "LTXV 2.3",
        "downloaded_at": "2026-05-01T..."
      }
    """
    sidecar = safetensors_path.with_suffix(".json")
    meta = {
        "name": safetensors_path.stem.replace("_", " ").replace("-", " "),
        "description": "",
        "trigger_words": [],
        "recommended_strength": 1.0,
        "preview_url": None,
        "preview_type": None,        # "image" | "video" | None
        "base_model": None,
        "civitai_id": None,
        "civitai_version_id": None,
        "civitai_url": None,         # link back to source page (for "read instructions")
        "downloaded_at": None,
        # Optional local guardrail for style LoRAs that over-learn particle /
        # mesh artifacts. When present, make_job appends these to Avoid.
        "artifact_negative_prompt": "",
        # `kind` discriminates source: "train_character" for LoRAs produced
        # by Phosphene's in-app trainer, anything else (or absent) for
        # CivitAI / manual installs. The picker uses this to badge trained
        # LoRAs distinctly so users can find their own characters fast.
        "kind": None,
        # ---- H3 lane bookkeeping (2026-08-09) ----------------------------
        # `lora_layout` is the key layout the file was found in — "bare" (what
        # the MLX loader wants) or "comfyui" (the same tensors under a
        # `diffusion_model.` namespace). `lora_converted_prefix` records the
        # namespace we STRIPPED at install time, so the sidecar answers "was
        # this file modified, and how" without re-reading 700 MB of weights.
        # Both are None on every LTX-lane sidecar ever written; absent keys
        # fall back to these defaults, so no existing sidecar needs a rewrite.
        "lora_layout": None,
        "lora_converted_prefix": None,
        # `guide`: the planner-written paragraph (POST /loras/guide) — what
        # the LoRA does, how to prompt it, a strength to start from. The
        # reader is a whitelist, so a key it does not name never reaches the
        # picker: this row is what makes the guide survive the read.
        "guide": "",
    }
    if sidecar.exists():
        try:
            with sidecar.open("r") as fh:
                user = json.load(fh) or {}
            for k in meta:
                if k in user and user[k] is not None:
                    meta[k] = user[k]
        except Exception as exc:
            sys.stderr.write(f"WARN: bad sidecar at {sidecar} ({exc}); "
                             f"falling back to filename\n")
    return meta


def _active_ltx_transformer_path() -> Path | None:
    """Return the checkpoint the active generation's default LoRA lane uses."""
    from lora_compat import resolve_distilled_transformer

    model_dir = Path(base_model_dir())
    if not model_dir.is_dir():
        return None
    return resolve_distilled_transformer(model_dir)


def _ltx_lora_compatibility(path: str | Path) -> dict:
    """Library-safe compatibility fields for one local adapter.

    Missing active weights produce an unknown result rather than hiding the
    entire library during install.  A present checkpoint is authoritative: a
    malformed or mismatched adapter is marked unavailable and its exact file
    name travels to both the UI and the enqueue refusal.
    """
    from lora_compat import LoraCompatibilityError, inspect_lora_compatibility

    lora_path = Path(path)
    transformer_path = _active_ltx_transformer_path()
    if transformer_path is None:
        return {
            "ltx_compatible": None,
            "ltx_compat_reason": "active LTX transformer is not installed",
            "ltx_fusion_tally": None,
        }
    try:
        report = inspect_lora_compatibility(lora_path, transformer_path)
        reason = "" if report.compatible else report.failure_message()
        return {
            "ltx_compatible": report.compatible,
            "ltx_compat_reason": reason,
            "ltx_fusion_tally": report.tally,
        }
    except (LoraCompatibilityError, OSError, ValueError) as exc:
        return {
            "ltx_compatible": False,
            "ltx_compat_reason": (
                f"LoRA '{lora_path.name}' cannot be inspected for the active "
                f"LTX generation: {exc}"
            ),
            "ltx_fusion_tally": None,
        }


def list_user_loras() -> list[dict]:
    """Scan mlx_models/loras/ and return one entry per .safetensors found.
    Filenames are matched case-insensitive on the extension; subdirectories
    are not recursed (keeps the picker flat, no organizational ambiguity)."""
    out: list[dict] = []
    if not LORAS_DIR.exists():
        return out
    for path in sorted(LORAS_DIR.iterdir()):
        if not path.is_file() or path.suffix.lower() != ".safetensors":
            continue
        try:
            size_bytes = path.stat().st_size
        except OSError:
            continue
        meta = _read_lora_sidecar(path)
        # Heuristic: if preview_type wasn't recorded in the sidecar (older
        # downloads pre-this-field), infer from the URL extension so the UI
        # picks <video> vs <img> correctly.
        preview_url = meta.get("preview_url")
        preview_type = meta.get("preview_type")
        if preview_url and not preview_type:
            preview_type = "video" if preview_url.lower().split("?")[0].endswith(".mp4") else "image"
        # Backfill civitai_url from civitai_id when the sidecar predates the
        # explicit civitai_url field.
        civitai_url = meta.get("civitai_url")
        if not civitai_url and meta.get("civitai_id"):
            civitai_url = f"https://civitai.com/models/{meta.get('civitai_id')}"
        # Character-LoRA classification fallback (issue #5, 2026-06-07): an
        # in-app-trained character is written as `<trigger>_v2.safetensors`
        # plus a `<trigger>_v2.json` sidecar carrying trigger_words + kind.
        # list_characters() keys off the filename alone, but this picker read
        # only the sidecar — so a character whose sidecar is missing/empty
        # (hand-restored file, wiped .json, legacy import) got mislabeled
        # "style-only — no trigger word needed". Recover the trigger + the
        # character kind from the same `_v2` convention list_characters()
        # already trusts, so the picker and the Character tab can't disagree.
        trigger_words = list(meta.get("trigger_words") or [])
        kind = meta.get("kind")
        if path.name.endswith("_v2.safetensors"):
            _conv_trigger = path.name[: -len("_v2.safetensors")]
            if _CHARACTERS_ID_RE.match(_conv_trigger):
                if not trigger_words:
                    trigger_words = [_conv_trigger]
                if not kind:
                    kind = "train_character"
        ltx_compat = _ltx_lora_compatibility(path)
        out.append({
            "id": f"user:{path.name}",
            "name": meta["name"],
            "description": meta["description"],
            "path": str(path),
            "filename": path.name,
            "size_bytes": size_bytes,
            # Which ENGINE DIRECTORY this file was discovered in — "ltx" for
            # the panel's own mlx_models/loras/ tree (LTX video + every mflux
            # image family), "h3" for the Hailuo pack's loras/ dir. The picker
            # filters on THIS before it looks at compatible_modes, because a
            # sidecar-less drop classifies as "unknown" and "unknown" is
            # deliberately permissive — without the directory being
            # authoritative, an untagged LTX LoRA would surface in the H3
            # picker and vice versa. See list_h3_user_loras().
            "lane": "ltx",
            "trigger_words": trigger_words,
            "recommended_strength": float(meta.get("recommended_strength") or 1.0),
            "preview_url": preview_url,
            "preview_type": preview_type,
            "base_model": meta.get("base_model"),
            "kind": kind,    # "train_character" for in-app trained LoRAs
            # Compat tags (see _classify_lora_modes). The picker uses
            # this to filter the library down to LoRAs that can actually
            # fire with the user's CURRENT (mode, engine) selection. An
            # "unknown" tag means we couldn't classify the sidecar's
            # base_model — surface in every filter with a `?` chip so
            # the user can still try it.
            "compatible_modes": _classify_lora_modes(meta.get("base_model")),
            "civitai_id": meta.get("civitai_id"),
            "civitai_version_id": meta.get("civitai_version_id"),
            "civitai_url": civitai_url,
            # A written guide (Settings-free): what the LoRA does, how to prompt
            # it, a strength to start from. Written on request by the planner
            # model from the sidecar; kept in the sidecar under `guide`.
            "guide": str(meta.get("guide") or ""),
            "downloaded_at": meta.get("downloaded_at"),
            "is_curated": False,
            **ltx_compat,
        })
    return out


def _lora_artifact_negative_prompt(loras: list[dict]) -> str:
    """Collect sidecar-defined artifact Avoid terms for active LoRAs.

    Some style LoRAs intentionally learn lighting / grade but also pick up
    unwanted dataset habits like glowing particle fields or tiled mesh
    textures. A local sidecar can carry `artifact_negative_prompt` so the
    panel applies that guard whenever the LoRA is active, without hard-coding
    one-off LoRA names in the helper.
    """
    additions: list[str] = []
    seen: set[str] = set()
    for entry in loras or []:
        path_raw = str((entry or {}).get("path") or "").strip()
        if not path_raw:
            continue
        try:
            strength = float((entry or {}).get("strength", 1.0))
        except (TypeError, ValueError):
            strength = 1.0
        if strength == 0:
            continue
        path = Path(path_raw)
        if not path.is_file():
            continue
        neg = str(_read_lora_sidecar(path).get("artifact_negative_prompt") or "").strip()
        if not neg:
            continue
        key = neg.lower()
        if key in seen:
            continue
        additions.append(neg)
        seen.add(key)
    return ", ".join(additions)


def list_curated_loras() -> list[dict]:
    """Curated entries surfaced in the UI even though the actual weights
    are pulled lazily from HuggingFace at first use. We hide the HDR one
    from the picker because it's exposed as a plain toggle elsewhere
    (see is_hdr_toggle filtering on the JS side)."""
    return [dict(v) for v in CURATED_LORAS.values()]


# ---- Characters discovery ----------------------------------------------------
#
# A "character" is a paired face + audio LoRA bundle trained in lora-lab.
# Discovery scans mlx_models/loras/ for files matching `<trigger>_v2.safetensors`
# and looks for the matching `<trigger>.audio.safetensors`. Metadata
# (display name, pronoun, subject_noun, default_action) is read from
# mlx_models/characters/<trigger>/bundle.json when present.
#
# This drives the Characters tab — see GET /characters,
# GET /characters/<id>/preview, POST /characters/<id>/generate.

_CHARACTERS_ID_RE = re.compile(r"^[A-Za-z0-9 _-]+$")
_CHARACTERS_PREVIEW_LOCK = threading.Lock()
_CHARACTERS_CACHE_PATH = MODELS_DIR / "characters"
# Styles mirror the characters cache layout: mlx_models/styles/<trigger>/
# holds avatar.{ext} (first training frame) + optional bundle.json. The style
# id-validation regex piggybacks on _CHARACTERS_ID_RE — same [A-Za-z0-9 _-]+
# rule, no point in two regexes.
_STYLES_CACHE_PATH = MODELS_DIR / "styles"


def _character_safe_id(value: str) -> str:
    """Validate a character id from a URL path. Trigger ids ship as
    [A-Za-z0-9 _-]+ (a trigger can legitimately contain a space, e.g.
    "Annie Phosphene") — anything else is path traversal or junk."""
    # URL path segments arrive percent-encoded, so a spaced trigger reaches
    # us as "Annie%20Phosphene"; decode BEFORE validating. Unquote-then-
    # validate stays traversal-safe: any encoded "../" or "/" decodes to
    # literal chars the character class below then rejects.
    v = urllib.parse.unquote((value or "").strip()).strip()
    if not v or not _CHARACTERS_ID_RE.match(v):
        raise ValueError("invalid character id")
    return v


def _character_dataset_image(trigger: str) -> Path | None:
    """Find the most representative training image for `trigger`.

    Lookup order (first match wins):
      1. mlx_models/characters/<trigger>/avatar.{jpg,jpeg,png,webp} —
         panel-owned avatar. Written by run_train_job_inner after a
         successful face training (copies the first training image).
         New characters created via the Train tab end up here.
      2. lora-lab/dataset_<stem>_v2/images/<trigger>_001.png — the
         lora-lab convention Mr Bizarro set up manually for ariatrn / bizarrotrn
         pre-Train-tab automation. <stem> = trigger with trailing 'trn'
         stripped (ariatrn → aria).
      3. lora-lab/dataset_<stem>*/images/<trigger>_*.png — any glob match
         under any dataset_<stem>* subdir (legacy fallback).
    Returns None when nothing resolvable exists — the UI paints a
    letter placeholder.
    """
    # 1. Panel-owned avatar (Train-tab convention).
    char_dir = _CHARACTERS_CACHE_PATH / trigger
    if char_dir.is_dir():
        for ext in (".jpg", ".jpeg", ".png", ".webp"):
            avatar = char_dir / f"avatar{ext}"
            if avatar.is_file():
                return avatar
    # 2 + 3. lora-lab conventions (legacy / manual). LORA_LAB_ROOT is
    # the vendored install dir by default; the LTX_LORA_LAB_ROOT env
    # var can repoint it at an external authoring tree (e.g.
    # ~/AI/projects/lora-lab) for in-place iteration.
    lab_root = LORA_LAB_ROOT
    stem = trigger[:-3] if trigger.endswith("trn") else trigger
    candidates = [
        lab_root / f"dataset_{stem}_v2" / "images" / f"{trigger}_001.png",
        lab_root / f"dataset_{stem}" / "images" / f"{trigger}_001.png",
    ]
    for c in candidates:
        if c.is_file():
            return c
    if lab_root.is_dir():
        for child in sorted(lab_root.glob(
                f"dataset_{stem}*/images/{trigger}_*.png")):
            if child.is_file():
                return child
    return None


def _character_sheet_png(trigger: str) -> Path | None:
    """mlx_models/characters/<trigger>/sheet.png when a generated character
    sheet exists, else None.

    Unlike `_character_dataset_image` there is no lora-lab fallback — sheets
    are panel-generated only (generate_character_sheet writes them), so the
    single panel-owned location is the whole search space. Keeping this a
    one-liner helper (rather than inlining the path twice) means the record
    surfacing in list_characters and the /characters/<id>/sheet serve route
    can never disagree about where a sheet lives."""
    p = _CHARACTERS_CACHE_PATH / trigger / "sheet.png"
    return p if p.is_file() else None


def _character_bundle(trigger: str) -> dict:
    """Read mlx_models/characters/<trigger>/bundle.json if present.
    Returns an empty dict on missing or unparseable JSON — discovery
    still surfaces the character, just with reduced metadata."""
    bundle_path = _CHARACTERS_CACHE_PATH / trigger / "bundle.json"
    if not bundle_path.is_file():
        return {}
    try:
        return json.loads(bundle_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}


def list_characters() -> list[dict]:
    """Scan mlx_models/loras/ for character LoRAs and return one record per
    discovered character.

    Discovery rules:
      - face_lora  = `<trigger>_v2.safetensors`                  (REQUIRED)
      - audio_lora = `<trigger>.audio.safetensors` (same dir)    (optional)
      - voice_sample = `<trigger>.voice.<ext>`     (same dir)    (optional)
      - bundle = mlx_models/characters/<trigger>/bundle.json     (optional)
      - sample_image = first training image in lora-lab's dataset dir

    Characters without an audio LoRA are "silent" — they can still drive
    video generation (the face LoRA alone is enough for identity), but
    callers should skip audio cues in their prompts. `has_voice` exposes
    that state to the UI so a Silent badge + disabled audio toggle can
    render appropriately.
    """
    loras_dir = _safe_loras_dir()
    if not loras_dir.is_dir():
        return []
    voice_exts = sorted(TRAIN_VOICE_EXTS)
    out: list[dict] = []
    for face_path in sorted(loras_dir.glob("*_v2.safetensors")):
        trigger = face_path.name[: -len("_v2.safetensors")]
        if not _CHARACTERS_ID_RE.match(trigger):
            continue
        audio_path = loras_dir / f"{trigger}.audio.safetensors"
        has_audio = audio_path.is_file()
        # Look for any voice sample with a supported extension; pick the
        # first match in TRAIN_VOICE_EXTS order. The Train tab writes
        # whatever extension the user uploaded.
        voice_sample_path: Path | None = None
        for ext in voice_exts:
            candidate = loras_dir / f"{trigger}.voice{ext}"
            if candidate.is_file():
                voice_sample_path = candidate
                break
        bundle = _character_bundle(trigger)
        sample = _character_dataset_image(trigger)
        sheet = _character_sheet_png(trigger)
        compat_parts = [_ltx_lora_compatibility(face_path)]
        if has_audio:
            compat_parts.append(_ltx_lora_compatibility(audio_path))
        incompatible = next(
            (part for part in compat_parts if part["ltx_compatible"] is False),
            None,
        )
        compatibility_known = all(
            part["ltx_compatible"] is not None for part in compat_parts
        )
        out.append({
            "id": trigger,
            "trigger": trigger,
            "name": bundle.get("name") or trigger.replace("trn", "").title() or trigger,
            "pronoun": bundle.get("pronoun") or "they",
            "subject_noun": bundle.get("subject_noun") or "person",
            "default_action": bundle.get("default_action") or "",
            "sexy_directive": bool(bundle.get("sexy_directive", False)),
            "face_lora_path": str(face_path),
            # Legacy field — present iff the audio LoRA exists. New callers
            # should prefer `audio_lora` + `has_voice` for clarity.
            "audio_lora_path": str(audio_path) if has_audio else None,
            "audio_lora": str(audio_path) if has_audio else None,
            "voice_sample": str(voice_sample_path) if voice_sample_path else None,
            # Back-compat alias — some older calls used `voice_wav_path`
            # specifically (assumed .wav). New callers should use
            # `voice_sample`.
            "voice_wav_path": str(voice_sample_path) if voice_sample_path else None,
            "has_voice": has_audio,
            "sample_image_path": str(sample) if sample else None,
            "sample_image_url": (f"/characters/{trigger}/preview"
                                 if sample else None),
            # Generated character sheet (multi-view turnaround), when one
            # exists. Same path/url pairing as sample_image so UI code can
            # treat the two thumbnails uniformly.
            "sheet_image_path": str(sheet) if sheet else None,
            "sheet_image_url": (f"/characters/{trigger}/sheet"
                                if sheet else None),
            "ltx_compatible": (
                False if incompatible else (True if compatibility_known else None)
            ),
            "ltx_compat_reason": (
                incompatible["ltx_compat_reason"] if incompatible else ""
            ),
            "ltx_fusion_tallies": [
                part["ltx_fusion_tally"] for part in compat_parts
                if part.get("ltx_fusion_tally")
            ],
        })
    return out


def list_library_characters() -> list[dict]:
    """Characters the active generation can safely offer in the UI."""
    return [
        char for char in list_characters()
        if char.get("ltx_compatible") is not False
    ]


# ---- Shipped sample character ------------------------------------------------
# So a new user can try Character / Remix WITHOUT training a LoRA first (the #1
# barrier to trying the feature — nobody wants to spend an hour training before
# they know it even works). Hosted as a GitHub release asset on the public repo.
# The SERVER owns the URL — clients only trigger the fetch; this is not a generic
# downloader. Lands in mlx_models/loras/ where list_characters() discovers it by
# the <trigger>_v2.safetensors convention (→ shows up as "Bizarro").
SAMPLE_CHARACTER = {
    "trigger": "bizarrotrn",
    "name": "Bizarro (sample)",
    "filename": "bizarrotrn_v2.safetensors",
    "url": ("https://github.com/mrbizarro/phosphene/releases/download/"
            "sample-character-bizarro/bizarrotrn_v2.safetensors"),
    "sha256": "a52e648a4e3edccd279363acdc85337d1d9813ca5dab30f8948f79393a4ba615",
    "size_bytes": 855966824,
}

_sample_char_lock = threading.Lock()
# status: idle | downloading | done | error
_sample_char_state: dict = {"status": "idle", "mb": 0,
                            "total_mb": SAMPLE_CHARACTER["size_bytes"] // (1 << 20),
                            "error": None}


def _set_sample_state(**kw) -> None:
    """Rebind-free state update (mutate in place under the lock) so no route
    needs a `global` declaration."""
    with _sample_char_lock:
        _sample_char_state.clear()
        _sample_char_state.update(kw)


def _sample_character_present() -> bool:
    # Existence-only (NOT a size match): if any bizarrotrn_v2.safetensors is on
    # disk — ours or a user's own — the character already shows in the picker,
    # and we must never overwrite it.
    try:
        return (_safe_loras_dir() / SAMPLE_CHARACTER["filename"]).is_file()
    except OSError:
        return False


def _download_sample_character_bg() -> None:
    """Stream the sample character LoRA into mlx_models/loras/ in a daemon
    thread. Atomic (.partial → rename) + sha256-verified, so a mid-download kill
    or a corrupt transfer never leaves a file list_characters() would pick up."""
    import urllib.request
    import hashlib
    spec = SAMPLE_CHARACTER
    total_mb = spec["size_bytes"] // (1 << 20)
    tmp: Path | None = None
    try:
        loras_dir = _safe_loras_dir()
        loras_dir.mkdir(parents=True, exist_ok=True)
        target = loras_dir / spec["filename"]
        if target.is_file():
            # Never clobber an existing bizarrotrn_v2 (ours from a prior run, or
            # a user who trained their own with that trigger). It already lists.
            _set_sample_state(status="done", mb=total_mb, total_mb=total_mb, error=None)
            return
        tmp = target.with_suffix(target.suffix + ".partial")
        push(f"[sample-character] downloading {spec['name']} (~{total_mb} MB)…")
        req = urllib.request.Request(spec["url"], headers={"User-Agent": "Phosphene"})
        h = hashlib.sha256()
        written = 0
        last_log = 0.0
        with urllib.request.urlopen(req, timeout=60) as resp, open(tmp, "wb") as fh:
            while True:
                chunk = resp.read(1 << 20)
                if not chunk:
                    break
                fh.write(chunk)
                h.update(chunk)
                written += len(chunk)
                now = time.time()
                if now - last_log > 2.5:
                    _set_sample_state(status="downloading", mb=written // (1 << 20),
                                      total_mb=total_mb, error=None)
                    last_log = now
        if h.hexdigest() != spec["sha256"]:
            raise RuntimeError("checksum mismatch (download corrupt) — please retry")
        tmp.replace(target)
        _set_sample_state(status="done", mb=total_mb, total_mb=total_mb, error=None)
        push(f"[sample-character] installed → character '{spec['trigger']}' ({spec['name']})")
    except Exception as e:  # noqa: BLE001
        if tmp is not None:
            try:
                tmp.unlink()
            except OSError:
                pass
        _set_sample_state(status="error", mb=0, total_mb=total_mb, error=str(e)[:200])
        push(f"[sample-character] FAILED: {e}")


def _character_lora_basenames() -> set[str]:
    """Collect basenames of files that belong to a TRAINED character bundle —
    face LoRA, audio LoRA, voice clip. Used by the Manual-tab LoRA picker to
    suppress character files so the picker shows ONLY style/utility LoRAs.

    Two sources, unioned:

      1. Files discovered by `list_characters()` — that's the live truth
         (the file actually exists AND `_v2.safetensors` glob matched).
         Picks up `<trigger>_v2.safetensors`, `<trigger>.audio.safetensors`,
         `<trigger>.voice.<ext>` for every character on disk.

      2. Files declared in `mlx_models/characters/<trigger>/bundle.json`
         under `face.path`, `voice.path`, `voice.voice_clip`. These are
         basenames relative to `mlx_models/loras/`. The bundle may name
         a file that doesn't exist yet (e.g. `bizarrotrn.video.safetensors`
         on a fresh checkout) — we still suppress that name so when the
         user drops the weights in, it doesn't surface in the regular
         picker by accident.

    Returns a set of basenames (just `name.ext`, no path), so the caller
    can compare with `Path(p).name`.
    """
    blocked: set[str] = set()

    # Source 1: live discovery.
    try:
        for char in list_characters():
            for key in ("face_lora_path", "audio_lora_path", "voice_sample"):
                v = char.get(key)
                if v:
                    blocked.add(Path(v).name)
    except Exception:
        # Discovery failures shouldn't block the picker — just no exclusions
        # from this source. The picker stays usable; trained chars might
        # appear as duplicates next to the Characters card.
        pass

    # Source 2: bundle.json declarations (may reference yet-missing weights).
    if _CHARACTERS_CACHE_PATH.is_dir():
        for child in _CHARACTERS_CACHE_PATH.iterdir():
            if not child.is_dir():
                continue
            bundle_path = child / "bundle.json"
            if not bundle_path.is_file():
                continue
            try:
                bundle = json.loads(bundle_path.read_text(encoding="utf-8")) or {}
            except (OSError, json.JSONDecodeError):
                continue
            face = bundle.get("face") or {}
            voice = bundle.get("voice") or {}
            for v in (face.get("path"), voice.get("path"), voice.get("voice_clip")):
                if v:
                    blocked.add(Path(v).name)

    return blocked


def _is_character_lora(entry: dict, blocked_names: set[str] | None = None) -> bool:
    """Heuristic — return True if a LoRA picker entry should be HIDDEN from
    the Manual-tab style/utility picker because it's part of a trained
    character bundle (face / audio / voice).

    Rules (any one matches → it's a character file):
      - sidecar `kind` == "train_character"
      - basename ends with `.audio.safetensors`
      - basename ends with `.voice.<ext>` for ext in TRAIN_VOICE_EXTS
      - basename matches one of `blocked_names` (face / audio / voice
        files declared by an on-disk bundle.json or `list_characters()`)
    """
    if (entry.get("kind") or "") == "train_character":
        return True
    name = Path(str(entry.get("path") or entry.get("filename") or "")).name.lower()
    if not name:
        return False
    if name.endswith(".audio.safetensors"):
        return True
    for ext in TRAIN_VOICE_EXTS:
        if name.endswith(f".voice{ext}"):
            return True
    if blocked_names:
        # Compare case-insensitive to be defensive across filesystems.
        lower = {n.lower() for n in blocked_names}
        if name in lower:
            return True
    return False


def _style_dataset_image(trigger: str) -> Path | None:
    """Find the avatar image for a trained style. Mirrors
    `_character_dataset_image` but only checks the panel-owned styles cache —
    styles don't have a lora-lab legacy convention to fall back on.

    Returns the first avatar.{jpg,jpeg,png,webp} under
    mlx_models/styles/<trigger>/ or None if no avatar is on disk.
    """
    style_dir = _STYLES_CACHE_PATH / trigger
    if not style_dir.is_dir():
        return None
    for ext in (".jpg", ".jpeg", ".png", ".webp"):
        avatar = style_dir / f"avatar{ext}"
        if avatar.is_file():
            return avatar
    return None


def list_styles() -> list[dict]:
    """Scan mlx_models/loras/ for STYLE LoRAs and return one record per
    discovered style. Parallel to `list_characters()` but the discovery rule
    is the `<trigger>.style.safetensors` naming convention rather than the
    `<trigger>_v2.safetensors` character convention. Style LoRAs are
    standalone — there's no paired audio LoRA, no voice sample.

    Returns: [{trigger, name, lora_path, created_at, rank, steps,
               image_count, sample_image_path, sample_image_url}]
    """
    loras_dir = _safe_loras_dir()
    if not loras_dir.is_dir():
        return []
    out: list[dict] = []
    for style_path in sorted(loras_dir.glob("*.style.safetensors")):
        # Strip the ".style.safetensors" suffix to recover the trigger.
        trigger = style_path.name[: -len(".style.safetensors")]
        if not _CHARACTERS_ID_RE.match(trigger):
            continue
        # Read sibling sidecar JSON for metadata (rank, steps, etc.). Missing
        # sidecar isn't fatal — the LoRA still surfaces, just with reduced
        # metadata.
        sidecar_path = loras_dir / f"{trigger}.style.json"
        meta: dict = {}
        if sidecar_path.is_file():
            try:
                meta = json.loads(sidecar_path.read_text(encoding="utf-8")) or {}
            except (OSError, json.JSONDecodeError):
                meta = {}
        try:
            stat = style_path.stat()
        except OSError:
            continue
        sample = _style_dataset_image(trigger)
        out.append({
            "id": trigger,
            "trigger": trigger,
            "name": meta.get("name") or trigger,
            "lora_path": str(style_path),
            "filename": style_path.name,
            "size_mb": round(stat.st_size / (1024 * 1024), 1),
            "created_at": meta.get("created_at") or stat.st_mtime,
            "preset": meta.get("preset") or "",
            "rank": meta.get("rank"),
            "steps": meta.get("steps"),
            "resolution": meta.get("resolution"),
            "image_count": meta.get("image_count") or 0,
            "recommended_strength": float(meta.get("recommended_strength") or 1.0),
            "sample_image_path": str(sample) if sample else None,
            "sample_image_url": (f"/styles/{trigger}/preview"
                                 if sample else None),
        })
    return out


# Duration in seconds → frames the LTX 2.3 pipeline accepts. The
# constraint is `frames % 8 == 1`; 121 / 169 / 241 / 361 satisfy that and
# correspond to 5s / 7s / 10s / 15s at 24 fps. 15s pushes the helper
# past its usual sweet spot but works fine — Mr Bizarro measured 9.5min for
# 10s/241f on Q8 HQ, so 15s/361f extrapolates to ~14min.
def _character_duration_frames() -> dict[str, int]:
    """The Characters tab's duration axis — DERIVED from LTX_LENGTHS.

    This was a fourth hardcoded vocabulary for one concept (`{5s:121, 7s:169,
    10s:241, 15s:361}`), sitting beside the storyboard card's `[3,5,7,10]`, the
    Manual strip's free numeric field and H3's own table. It was honest — the
    tab is LTX-only and those frame counts are right on the 8k+1 grid — but four
    tables mean four things to keep in step, and the 7-second lie is what
    happens when one of them drifts.

    NOTE the shape change it implies: 15s LEAVES and 3s/20s ARRIVE, because the
    axis is now the one the engine actually publishes. 15 s was never on LTX's
    8k+1 axis as a named rung anyway — 361 frames is 15.0 s at 24 fps and
    renders fine, so any sidecar carrying it still resolves through the
    compatibility entry below."""
    out = {l["key"]: int(l["frames"]) for l in LTX_LENGTHS.values()}
    # Every value this endpoint has ever accepted keeps resolving. 15s is the
    # one the shipped chip row offered and clips exist at it.
    out.setdefault("15s", 361)
    return out


# Bound AFTER LTX_LENGTHS exists — see the assignment beside the tier table.
# Declared here as an empty dict so the name is defined for any import-time
# reader, and filled in one place rather than being re-derived per request.
_CHARACTER_DURATION_FRAMES: dict[str, int] = {}

# Quality-to-resolution map for the Characters tab. Nothing else.
# 2026-05-16 — Mr Bizarro's call: stop translating the user's request through
# a 25-field "locked recipe" composer. The Characters endpoint is now a
# thin wrapper around /queue/add that uses identical defaults; the only
# things the tab adds are the LoRA stack lookup and the duration→frames
# / quality→resolution mappings.
_CHARACTER_QUALITY_RESOLUTION = {
    # 704x384, not 736x416: both were off the 64-grid the two-stage lane snaps
    # to, so this chip advertised a canvas it never delivered either.
    "draft":    (704, 384),    # ~3:30 wall for 7s, Q8, lower per-frame detail
    "balanced": (1024, 576),   # reserved for a real fast-but-quality-equal tier
    "high":     (1024, 576),   # two-stage HQ character option
    "high_720p": (1280, 704),  # two-stage HQ at the native 720p delivery canvas
}


# ---- Version check / update notifier ----------------------------------------
# Phosphene ships fixes often (multiple commits a day in active periods) and
# users keep telling us "I clicked Update but I don't see anything new" — by
# the time their feedback lands, we've usually pushed three more commits.
# This module surfaces a small "Update available" pill in the header when the
# local install is behind origin/main, so users notice mismatch immediately
# instead of finding out later via a friend's tweet.
#
# How it works:
#   1. At startup we read the local commit SHA via `git rev-parse HEAD` and
#      branch name via `git rev-parse --abbrev-ref HEAD`. Stored once.
#   2. A daemon thread polls the GitHub commits API every 30 minutes (no
#      auth, public repo, well within unauthenticated rate limit).
#   3. We list `origin/main` commits newest-first and find the index of the
#      local SHA. If found at index N, we are N commits behind. If not found
#      in the first 30 commits, we report "30+ behind".
#   4. The /version endpoint returns the snapshot; the UI renders a pill
#      that links to the version modal listing each unseen commit.
#
# Suppressed cases (no pill rendered):
#   - User is on a non-main branch (local dev / fork)
#   - User has uncommitted local changes (in-progress work; we'd be wrong
#     to call them "behind")
#   - We can't reach the GitHub API (offline; suppress silently — we don't
#     bug users with red error toasts every 30 minutes)

_VERSION_LOCK = threading.Lock()
_VERSION_REPO_OWNER = "mrbizarro"
_VERSION_REPO_NAME = "phosphene"
_VERSION_POLL_INTERVAL_SEC = 30 * 60          # 30 minutes between checks
_VERSION_STARTUP_DELAY_SEC = 30                # don't compete with boot
_VERSION_STATE: dict = {
    "local_sha": None,            # 40-char hex of HEAD at panel start
    "local_short": None,           # 7-char display form
    "local_version": None,         # human label from /VERSION file (e.g. "Y1.001")
    "local_branch": None,          # branch name (e.g. "main") or "(detached)"
    "local_commit_date": None,     # ISO-day of HEAD commit (e.g. "2026-05-21") — for dev pill
    "local_dirty": False,          # uncommitted changes in the working tree
    "remote_sha": None,            # latest sha on origin/main per GitHub API
    "remote_short": None,
    "remote_version": None,        # /VERSION file at origin/main (raw fetch)
    "behind_by": 0,                # number of commits between local and remote (0 = current)
    "behind_more_than": False,     # True when behind > 30 (we cap the API response)
    "commits_ahead": [],           # list of {sha, short, message, author, date} for the dropdown
    "broadcast": None,             # maintainer message from BROADCAST.json on public main, or None
    "checked_ts": None,            # epoch seconds of last successful poll
    "error": None,                 # last failure reason (None when last check OK)
    "suppress_reason": None,       # set when we deliberately skip checking (dev mode, dirty, etc.)
    # Pull state — populated only when the user clicks the magic button on
    # the pill while behind. Kept on _VERSION_STATE so the UI can render a
    # "restart needed" pill without a separate state store.
    "pull_state": "idle",          # idle | pulling | pulled | error
    "pull_message": None,          # human-readable result line (last git output line, or error)
    "pull_pulled_to_short": None,  # SHA we ended up at after the pull
    "pull_pulled_to_version": None,# VERSION label after the pull
    "pull_requires_full_update": False,  # True if the diff touched deps/patches
}


def _git_capture(args: list[str], cwd: Path = ROOT) -> str | None:
    """Run a git subcommand and return stripped stdout (or None on any failure).
    No exceptions ever escape — we never want a missing git binary to crash
    the panel boot."""
    try:
        out = subprocess.check_output(
            ["git"] + args, cwd=str(cwd), stderr=subprocess.DEVNULL,
        )
        return out.decode("utf-8", "replace").strip()
    except (subprocess.CalledProcessError, FileNotFoundError, OSError):
        return None


def _read_local_version() -> str | None:
    """Return the contents of <repo>/VERSION as a single stripped string,
    or None if the file is missing / unreadable. We use this to surface a
    human-friendly label like 'Y1.001' instead of raw 7-char SHAs in the
    header pill. Older checkouts that predate this file fall back to the
    short SHA in the UI without breaking."""
    try:
        v = (ROOT / "VERSION").read_text().strip()
        return v or None
    except Exception:
        return None


def _fetch_raw_text(url: str, timeout: int = 10) -> str | None:
    """GET a public URL and return its body as a stripped string, or None
    on any error. Used for the raw VERSION-file fetch from origin/main on
    GitHub — `https://raw.githubusercontent.com/.../main/VERSION`. No
    auth, no rate-limit headers worth honouring at this volume (one
    request per 30-min poll)."""
    import urllib.request as _urlreq
    try:
        req = _urlreq.Request(url, headers={"User-Agent": "phosphene-panel-version-check"})
        with _urlreq.urlopen(req, timeout=timeout) as resp:
            return resp.read().decode("utf-8", "replace").strip() or None
    except Exception:
        return None


# The SHA this PROCESS loaded, captured once and never refreshed.
#
# v4.0.5 built stale-process detection on `_VERSION_STATE["local_sha"]`,
# described in its own docstring as "the boot snapshot". It is not one:
# `_check_remote_once()` calls `_detect_local_install_state()` at the top of
# every poll — deliberately, so a tree that was dirty at boot and is clean now
# stops being suppressed without a restart. That re-detect also refreshes
# local_sha, so within one poll interval local_sha equals disk again and
# `disk_sha != boot_sha` is false forever.
#
# Net effect: the "Restart to finish update" pill could never fire. Every user
# who pulled an update was told nothing, ran the old code, and concluded the
# update had done nothing — reported 2026-08-15 by the owner, who pulled 4.3.0
# and saw a 4.0.9 UI for seven hours.
#
# This is deliberately captured at IMPORT, not inside a function that anything
# else might call again.
#
# 2026-08-20 — except it was NOT captured at import. The only caller was
# `version_check_loop`, a thread `__main__` starts only `if
# VERSION_CHECK_ENABLED`. `PHOSPHENE_DISABLE_VERSION_CHECK=1` therefore left
# _BOOT_HEAD_SHA at None for the life of the process, and `disk != boot` is
# False when boot is None — the dead detector this comment is about, back
# through the side door. The capture runs beside the definition now, which is
# what "at IMPORT" has to mean.
#
# And it is a SNAPSHOT, not one SHA. Every field the header stamp renders —
# version label, branch, commit date — has to come from the same frozen
# moment. `_VERSION_STATE["local_*"]` re-reads all four from disk on every
# poll, so the stamp described the WORKING TREE, not the running process: pull
# under a live panel and the header immediately advertises the new build while
# the old code keeps serving. The restart tooltip degenerated with it, since
# both sides of "X is on disk but this process loaded Y" read the same
# disk-derived label — "Phosphene 4.6.0 is on disk, but this panel process
# loaded 4.6.0". The stamp is how the owner tells which build he is on; it
# has to name the code that is answering him.
_BOOT_HEAD_SHA: str | None = None
_BOOT_VERSION: str | None = None
_BOOT_BRANCH: str | None = None
_BOOT_COMMIT_DATE: str | None = None


def _capture_boot_head() -> None:
    """Record what THIS process loaded, exactly once. Idempotent by design.

    Runs at import. `version_check_loop` still calls it, belt-and-braces for
    any path that reaches the loop without the import-time call having taken
    (a test that reset the globals, a future entry point); the guard makes the
    second call a no-op rather than a re-point at whatever is on disk now."""
    global _BOOT_HEAD_SHA, _BOOT_VERSION, _BOOT_BRANCH, _BOOT_COMMIT_DATE
    if _BOOT_VERSION is None:
        # A zip install has no git and still ships a VERSION file. That file
        # is a property of the code this process loaded, so freeze it whether
        # or not the SHA lookup below works.
        _BOOT_VERSION = _read_local_version()
    if _BOOT_HEAD_SHA is not None:
        return
    sha = _git_capture(["rev-parse", "HEAD"])
    if not sha:
        return                      # not a checkout — the SHA fields stay None
    _BOOT_HEAD_SHA = sha
    _BOOT_BRANCH = _git_capture(["rev-parse", "--abbrev-ref", "HEAD"])
    _BOOT_COMMIT_DATE = _git_capture(
        ["log", "-1", "--format=%cd", "--date=format:%Y-%m-%d"])


def boot_build_stamp() -> dict:
    """What this process is running. ONE accessor, so a second reader cannot
    quietly grow a second answer to "which build is this?"."""
    return {
        "sha": _BOOT_HEAD_SHA,
        "short": _BOOT_HEAD_SHA[:7] if _BOOT_HEAD_SHA else None,
        "version": _BOOT_VERSION,
        "branch": _BOOT_BRANCH,
        "commit_date": _BOOT_COMMIT_DATE,
    }


def running_version() -> str:
    """The VERSION label of the code THIS PROCESS is running.

    Everything that stamps a label onto something the process produced — an
    analytics event, a rendered film, a sidecar — has to name the build that
    produced it. `_read_local_version()` re-reads the tree, so after a pull
    under a running panel every one of those said the NEW number while the
    OLD code was doing the work: an app_boot event from a build that never
    booted, a film crediting a renderer that never touched it. Same defect as
    the header stamp, same fix. Disk is the fallback for a zip install with
    no git, where the boot capture has no SHA to anchor to."""
    return boot_build_stamp()["version"] or _read_local_version() or "dev"


def build_stamp_text() -> str:
    """The build stamp as one greppable line, for the `phosphene-build` meta
    tag. The page is full of real SHAs in comments that reference historical
    commits ("the loadParams fix (b024bb5)"); thirteen of them as of today,
    and NONE of them the running build, which appeared nowhere in the served
    HTML at all. Anyone answering "which build is this?" by searching the page
    hit a decoy. This is the one line that is the answer."""
    b = boot_build_stamp()
    parts = [b["version"] or "dev", b["branch"] or "no-branch",
             b["short"] or "no-git"]
    if b["commit_date"]:
        parts.append(b["commit_date"])
    return " · ".join(parts)


_capture_boot_head()      # AT IMPORT — before anything can serve a request


def _detect_local_install_state() -> None:
    """Populate _VERSION_STATE.local_* fields. Called once at startup; result
    doesn't change while the panel is running (no auto-pull on the user's
    behalf). Pinokio's Update step kills + restarts the panel, so a fresh
    detect runs after every Update."""
    sha = _git_capture(["rev-parse", "HEAD"])
    branch = _git_capture(["rev-parse", "--abbrev-ref", "HEAD"]) or "(unknown)"
    # `git status --porcelain -uno` empty = no MODIFIED TRACKED files.
    #
    # -uno (untracked-files=no) is load-bearing, not a tidy-up. Plain
    # --porcelain also lists `??` untracked paths, and an install grows
    # those by design: the optional H3 pack clones minimax-h3-mlx/ into
    # this directory, Pinokio fills cache/ and logs/. That made the tree
    # permanently "dirty" for every H3 user, which suppressed the update
    # check outright — @Morac2 reported the pill stuck on "Update check
    # is paused: local changes uncommitted" with nothing but `?? minimax-
    # h3-mlx/` in his status (#52). .gitignore now covers those three
    # paths, but only for users who already got the new .gitignore, which
    # they can't without updating. -uno is what actually fixes it, and it
    # is the honest question anyway: untracked files are exactly the ones
    # a fast-forward pull (and the reset --hard fallback) leave alone. The
    # one case where an untracked file DOES matter — an incoming commit
    # adding a file at the same path — git refuses on its own, and that
    # error is surfaced verbatim by the /version/pull handler.
    porcelain = _git_capture(["status", "--porcelain", "-uno"])
    dirty = bool(porcelain and porcelain.strip())
    local_version = _read_local_version()
    # 2026-05-21 — capture HEAD commit date so the dev pill can show
    # users which dated build they're running. Reddit context: dev
    # users were reporting "I'm on 2.0.5" with character training,
    # confused because the panel showed an old VERSION value but they
    # had pulled fresh code. Showing the commit date alongside the
    # short SHA lets us tell them concretely "you're on the May 18
    # build — please pull again, latest is May 21."
    local_commit_date = _git_capture(["log", "-1", "--format=%cd",
                                       "--date=format:%Y-%m-%d"])
    with _VERSION_LOCK:
        _VERSION_STATE["local_sha"] = sha
        _VERSION_STATE["local_short"] = sha[:7] if sha else None
        _VERSION_STATE["local_version"] = local_version
        _VERSION_STATE["local_branch"] = branch
        _VERSION_STATE["local_commit_date"] = local_commit_date
        _VERSION_STATE["local_dirty"] = dirty
        # Suppress remote checks when the user is clearly running their own
        # variant — we'd be wrong to nag them about being "behind."
        if not VERSION_CHECK_ENABLED:
            _VERSION_STATE["suppress_reason"] = "disabled by PHOSPHENE_DISABLE_VERSION_CHECK"
        elif not sha:
            _VERSION_STATE["suppress_reason"] = "not a git checkout"
        elif branch != "main":
            _VERSION_STATE["suppress_reason"] = f"on branch '{branch}', not main"
        elif dirty:
            _VERSION_STATE["suppress_reason"] = "local changes uncommitted"
        else:
            _VERSION_STATE["suppress_reason"] = None


def _fetch_remote_commits(limit: int = 30) -> list[dict] | None:
    """GET the latest N commits on origin/main from the public GitHub API.
    Returns a list of raw commit dicts (newest first), or None on any error.
    Caller is expected to handle None gracefully — we don't show errors to
    the user every 30 minutes when their wifi is flaky."""
    import urllib.request as _urlreq
    import urllib.error as _urlerr
    url = (f"https://api.github.com/repos/{_VERSION_REPO_OWNER}/"
           f"{_VERSION_REPO_NAME}/commits?sha=main&per_page={limit}")
    req = _urlreq.Request(url, headers={
        "Accept": "application/vnd.github+json",
        "User-Agent": "phosphene-panel-version-check",
    })
    try:
        with _urlreq.urlopen(req, timeout=10) as resp:
            data = json.loads(resp.read().decode("utf-8"))
        if not isinstance(data, list):
            return None
        return data
    except (_urlerr.URLError, _urlerr.HTTPError, OSError, ValueError, TimeoutError):
        return None


def _parse_broadcast(raw: bytes | str, local_version: str = "") -> dict | None:
    """Validate a BROADCAST.json payload into the one message the UI may show.

    The maintainer's channel to every install: a JSON file committed to public
    main. Closed shape on purpose — id (string, the dismissal key), title,
    body (plain text, rendered as text never HTML), and optionally
    show_if_version_below ("4.9.0": installs at or past it skip the message,
    so "please update" posts stop nagging people who already did). Anything
    malformed returns None: a broken file must read as "no message", never as
    a broken panel.
    """
    try:
        data = json.loads(raw)
    except (ValueError, TypeError):
        return None
    if not isinstance(data, dict):
        return None
    mid = str(data.get("id") or "").strip()[:64]
    title = str(data.get("title") or "").strip()[:120]
    body = str(data.get("body") or "").strip()[:2000]
    if not mid or not (title or body):
        return None
    below = str(data.get("show_if_version_below") or "").strip()
    if below and local_version:
        def _v(v):
            try:
                return tuple(int(x) for x in v.strip().split("."))
            except ValueError:
                return None
        lv, bv = _v(local_version), _v(below)
        if lv is not None and bv is not None and lv >= bv:
            return None
    return {"id": mid, "title": title, "body": body}


def _fetch_broadcast() -> dict | None:
    """GET BROADCAST.json from public main. None on any failure or absence."""
    import urllib.request as _urlreq
    import urllib.error as _urlerr
    url = (f"https://raw.githubusercontent.com/{_VERSION_REPO_OWNER}/"
           f"{_VERSION_REPO_NAME}/main/BROADCAST.json")
    req = _urlreq.Request(url, headers={
        "User-Agent": "phosphene-panel-version-check",
    })
    try:
        with _urlreq.urlopen(req, timeout=10) as resp:
            raw = resp.read(64 * 1024)
    except (_urlerr.URLError, _urlerr.HTTPError, OSError, ValueError,
            TimeoutError):
        return None
    with _VERSION_LOCK:
        local = _VERSION_STATE.get("local_version") or ""
    return _parse_broadcast(raw, local)


def _check_remote_once() -> None:
    """Run one remote check, mutate _VERSION_STATE accordingly. Idempotent.
    Safe to call from a background thread or from a /version/check endpoint.
    Re-detects local state (HEAD, branch, dirty) at the top of every call so
    a tree that was dirty when the panel started but is clean now (e.g. user
    just committed) gets picked up without needing a panel restart. The
    earlier build only ran _detect_local_install_state once at startup,
    which left the suppress_reason stale across the panel's lifetime."""
    _detect_local_install_state()
    with _VERSION_LOCK:
        suppress = _VERSION_STATE["suppress_reason"]
        local_sha = _VERSION_STATE["local_sha"]
    if suppress:
        return                             # never poll in suppressed states
    commits = _fetch_remote_commits(limit=30)
    if commits is None:
        with _VERSION_LOCK:
            _VERSION_STATE["error"] = "could not reach github.com"
        return
    if not commits:
        with _VERSION_LOCK:
            _VERSION_STATE["error"] = "github returned no commits"
        return
    remote_sha = commits[0].get("sha")
    if not remote_sha:
        with _VERSION_LOCK:
            _VERSION_STATE["error"] = "github response missing sha"
        return

    # Find local SHA in the list. If it's at index N, we are N commits behind.
    behind_by = None
    for i, c in enumerate(commits):
        if c.get("sha") == local_sha:
            behind_by = i
            break
    if behind_by is None:
        # Local is older than what fits in the window OR has been rebased
        # away. Either way, "30+" is a fine UX answer — the modal will say
        # "many updates available, please run Pinokio Update."
        behind_by = len(commits)
        more = True
    else:
        more = False

    # Slim each commit dict down to what the modal renders. Keep only the
    # commits the user is missing.
    ahead: list[dict] = []
    for c in commits[:behind_by]:
        commit = c.get("commit") or {}
        author = (commit.get("author") or {}).get("name") or "unknown"
        date = (commit.get("author") or {}).get("date") or ""
        msg = (commit.get("message") or "").splitlines()[0]   # first line only
        sha = c.get("sha") or ""
        ahead.append({
            "sha": sha,
            "short": sha[:7],
            "message": msg,
            "author": author,
            "date": date,
        })

    # Fetch the upstream VERSION file in parallel with the commits API so
    # the pill can show the human-friendly label (Y1.NNN). This is a raw
    # GET on raw.githubusercontent.com — no rate limit concern at our
    # 30-min cadence. Tolerate missing-file silently: older origin/main
    # commits predate VERSION, and we still have the SHA fallback.
    remote_version = _fetch_raw_text(
        f"https://raw.githubusercontent.com/{_VERSION_REPO_OWNER}/"
        f"{_VERSION_REPO_NAME}/main/VERSION"
    )
    # The maintainer broadcast rides the same 30-min cadence. Failures and
    # absence read as "no message" — _fetch_broadcast never raises.
    broadcast = _fetch_broadcast()
    with _VERSION_LOCK:
        _VERSION_STATE["remote_sha"] = remote_sha
        _VERSION_STATE["remote_short"] = remote_sha[:7]
        _VERSION_STATE["remote_version"] = remote_version
        _VERSION_STATE["behind_by"] = behind_by
        _VERSION_STATE["behind_more_than"] = more
        _VERSION_STATE["commits_ahead"] = ahead
        _VERSION_STATE["checked_ts"] = time.time()
        _VERSION_STATE["error"] = None
        _VERSION_STATE["broadcast"] = broadcast


def version_check_loop() -> None:
    """Daemon thread entry: detect local state once, then poll the remote
    every _VERSION_POLL_INTERVAL_SEC. First poll happens after a 30s
    delay so we don't compete with boot-time work."""
    _capture_boot_head()          # BEFORE anything can re-detect local state
    _detect_local_install_state()
    time.sleep(_VERSION_STARTUP_DELAY_SEC)
    while True:
        try:
            _check_remote_once()
        except Exception as exc:                          # belt + braces
            sys.stderr.write(f"WARN: version check raised: {exc}\n")
        time.sleep(_VERSION_POLL_INTERVAL_SEC)


def get_version_state() -> dict:
    """Snapshot of _VERSION_STATE for the /version endpoint. Returns a copy
    so the caller can't mutate the live state under the lock.

    TWO BUILDS, ALWAYS BOTH. `local_*` is what THIS PROCESS LOADED — the boot
    snapshot, frozen at import. `disk_*` is the working tree right now, one
    `git rev-parse` per request (the pill polls every 5 minutes). On a healthy
    install they are equal, and that is the point: when they diverge the
    header has to keep naming the code that is actually answering, or the
    stamp stops being the thing the owner uses to tell which build he is on.
    The 2026-08-14 incident where :8198 served pre-4.0.4 HTML for three hours
    after the folder updated is what `stale_process` is for.

    `_VERSION_STATE["local_*"]` is NOT that snapshot, despite the name. It is
    re-detected from disk at the top of every remote poll, deliberately, so a
    tree that was dirty at boot and is clean now stops being suppressed
    without a restart. It stays the basis for `behind_by` — being behind
    origin/main is a fact about the TREE — and is overwritten here for
    display, which is a fact about the PROCESS."""
    with _VERSION_LOCK:
        snap = dict(_VERSION_STATE)
    boot = boot_build_stamp()
    disk_sha = _git_capture(["rev-parse", "HEAD"])
    # The header stamp answers exactly one question — what code is this
    # process running — so it is answered from the boot snapshot or not at
    # all. Never snap["local_*"]: that agrees with disk within one poll.
    if boot["sha"]:
        snap["local_sha"] = boot["sha"]
        snap["local_short"] = boot["short"]
        snap["local_version"] = boot["version"]
        snap["local_branch"] = boot["branch"] or snap.get("local_branch")
        snap["local_commit_date"] = boot["commit_date"]
    # Unconditional, not "only when stale". A consumer that must check
    # stale_process before it may trust disk_short is a consumer that will
    # eventually forget to.
    snap["disk_sha"] = disk_sha
    snap["disk_short"] = disk_sha[:7] if disk_sha else None
    snap["disk_version"] = _read_local_version()
    snap["stale_process"] = bool(
        disk_sha and boot["sha"] and disk_sha != boot["sha"])
    return snap


# ---------------------------------------------------------------------------
# Repo-stats background fetcher (Mr Bizarro's solo-maintainer dashboard).
# Runs the stdlib-only fetcher script as a subprocess once per 24h, appending
# a JSON line to state/stats-data.jsonl. Dashboard at /stats reads this file.
# 127.0.0.1-only by design (state/ is gitignored, file lives on the user's
# Mac only). Skipped silently if no GitHub token is resolvable — this fetcher
# is opt-in via "have a token configured". It only READS GitHub's API and
# sends nothing anywhere; the panel's outbound usage analytics is a separate
# module entirely (see "Anonymous usage analytics" / docs/ANALYTICS.md).
# ---------------------------------------------------------------------------

_STATS_POLL_INTERVAL_SEC = 24 * 60 * 60  # daily
_STATS_STARTUP_DELAY_SEC = 90            # let the panel finish booting first
_STATS_MIN_REFETCH_SEC   = 6 * 60 * 60   # don't re-fetch faster than every 6h


def _resolve_github_token() -> str:
    """Token resolution for the stats fetcher, in priority order:
       1. PHOSPHENE_REPO_STATS_TOKEN — explicit override for this purpose
       2. GH_STATS_TOKEN — fetcher's own preferred name
       3. GH_TOKEN / GITHUB_TOKEN — generic env vars
       4. `gh auth token` subprocess (when gh CLI is installed + authed)
    Returns empty string if nothing works — caller logs once and skips."""
    for name in ("PHOSPHENE_REPO_STATS_TOKEN", "GH_STATS_TOKEN",
                 "GH_TOKEN", "GITHUB_TOKEN"):
        v = (os.environ.get(name) or "").strip()
        if v:
            return v
    try:
        out = subprocess.run(
            ["gh", "auth", "token"], check=True, capture_output=True,
            timeout=5, text=True,
        )
        return (out.stdout or "").strip()
    except (FileNotFoundError, subprocess.SubprocessError):
        return ""


_STATS_WARNED_NO_TOKEN = False
_STATS_WARNED_FETCH_FAIL = False


def _run_stats_fetch_once() -> None:
    """Spawn scripts/fetch_repo_stats.py as a subprocess. Output to the
    panel's `push()` log so the user can see what happened. Idempotent —
    the fetcher itself replaces today's row on re-runs in the same UTC day."""
    global _STATS_WARNED_NO_TOKEN, _STATS_WARNED_FETCH_FAIL
    if not STATS_FETCHER.is_file():
        return  # repo install missing the script — fail silent
    token = _resolve_github_token()
    if not token:
        if not _STATS_WARNED_NO_TOKEN:
            push(
                "stats: no GitHub token resolvable (tried "
                "PHOSPHENE_REPO_STATS_TOKEN, GH_STATS_TOKEN, GH_TOKEN, "
                "GITHUB_TOKEN, `gh auth token`). Dashboard will be empty "
                "until you set one."
            )
            _STATS_WARNED_NO_TOKEN = True
        return
    env = os.environ.copy()
    env["GITHUB_TOKEN"] = token
    try:
        cp = subprocess.run(
            [sys.executable, str(STATS_FETCHER)],
            capture_output=True, text=True, timeout=120, env=env,
        )
        if cp.returncode != 0:
            # The stats dashboard is a maintainer-only nicety; a fetch failure
            # (403 rate-limit/token-scope, network blip, etc.) has ZERO effect
            # on generation, models, or training. Warn once, cosmetically, so a
            # transient 403 doesn't spam the log or read as a real failure that
            # sends users to the bug tracker (issue #43).
            if not _STATS_WARNED_FETCH_FAIL:
                _detail = (cp.stderr or cp.stdout or "").strip().splitlines()
                _detail = _detail[-1][:160] if _detail else "unknown error"
                push(f"stats: dashboard refresh skipped ({_detail}). "
                     "This only affects the maintainer stats panel — "
                     "generation, models, and training are unaffected.")
                _STATS_WARNED_FETCH_FAIL = True
            return
        # Success — clear the one-shot warning latch so a genuine future
        # failure can surface again.
        _STATS_WARNED_FETCH_FAIL = False
        # Last stdout line is the human-readable summary the fetcher prints
        # at exit. Forward to the panel log so /status surfaces it.
        last_line = ""
        for line in (cp.stdout or "").splitlines():
            if line.strip():
                last_line = line.strip()
        if last_line:
            push(f"stats: {last_line}")
    except subprocess.TimeoutExpired:
        if not _STATS_WARNED_FETCH_FAIL:
            push("stats: dashboard refresh timed out (harmless — maintainer "
                 "stats panel only; generation is unaffected).")
            _STATS_WARNED_FETCH_FAIL = True
    except Exception as exc:  # noqa: BLE001
        if not _STATS_WARNED_FETCH_FAIL:
            push(f"stats: dashboard refresh skipped ({exc!r}). Harmless — "
                 "maintainer stats panel only; generation is unaffected.")
            _STATS_WARNED_FETCH_FAIL = True


def stats_fetch_loop() -> None:
    """Daemon thread entry: fetch repo stats once at startup (if the data
    file is missing or stale), then daily on _STATS_POLL_INTERVAL_SEC.

    The startup-fetch is gated by _STATS_MIN_REFETCH_SEC so multiple panel
    restarts in a short window don't hammer the GitHub API for nothing."""
    time.sleep(_STATS_STARTUP_DELAY_SEC)
    # First-run / cold-start fetch — but only if it's been a while.
    try:
        last_age = (time.time() - STATS_DATA_FILE.stat().st_mtime
                    if STATS_DATA_FILE.exists() else float("inf"))
    except OSError:
        last_age = float("inf")
    if last_age >= _STATS_MIN_REFETCH_SEC:
        _run_stats_fetch_once()
    while True:
        time.sleep(_STATS_POLL_INTERVAL_SEC)
        try:
            _run_stats_fetch_once()
        except Exception as exc:  # noqa: BLE001 — belt + braces
            sys.stderr.write(f"WARN: stats fetch loop raised: {exc}\n")


def parse_loras_from_form(form: dict) -> list[dict]:
    """Parse the loras=<JSON> form field that the UI submits with each job.
    Shape on the wire is a JSON array of {id, path, strength}. We trust
    `id` only for routing in this layer; what gets sent to the helper is
    just the (path, strength) pair the fuser needs."""
    raw = form.get("loras", [""])
    if isinstance(raw, list):
        raw = raw[0] if raw else ""
    raw = (raw or "").strip()
    if not raw:
        return []
    try:
        items = json.loads(raw)
    except json.JSONDecodeError:
        return []
    out: list[dict] = []
    if not isinstance(items, list):
        return out
    for item in items:
        if not isinstance(item, dict):
            continue
        path = str(item.get("path") or "").strip()
        if not path:
            continue
        try:
            strength = float(item.get("strength", 1.0))
        except (TypeError, ValueError):
            strength = 1.0
        # Clamp; LoRA strengths beyond ±2 are usually nonsense and risk
        # numerical issues during fusion.
        strength = max(-2.0, min(2.0, strength))
        out.append({"path": path, "strength": strength})
    return out


def _repos() -> list[dict]:
    """All repo entries from required_files.json (list, in order)."""
    return list(_REQUIRED.get("repos", []))


def _repo_missing(repo: dict) -> list[str]:
    """Files missing or zero-byte for one repo, expressed as bare filenames
    (relative to the repo's local_dir). Bare names are friendlier in the UI
    than full paths."""
    base = ROOT / repo["local_dir"]
    missing = []
    for fname in repo.get("files", []):
        p = base / fname
        try:
            if not p.exists() or p.stat().st_size < _MIN_FILE_BYTES:
                missing.append(fname)
        except OSError:
            missing.append(fname)
    return missing


def _repo_complete(repo: dict) -> bool:
    return not _repo_missing(repo)


# ---- HF cache fallback -------------------------------------------------------
# Background:
#   - Pinokio installs use `hf download --local-dir mlx_models/<repo>/`. Files
#     live at the canonical local_dir path the manifest declares.
#   - Manual / dev installs that pass an HF repo id as LTX_MODEL get the
#     weights resolved via huggingface_hub's cache at ~/.cache/huggingface/.
#     Same files, different location.
#
# Without this fallback, dev-env users whose models were already pulled into
# the HF cache (e.g. by an earlier `huggingface-cli download` or by the helper
# itself on first run) saw the panel report Q4 as "MISSING" even though every
# render was working perfectly. That was the confusing "honest note" — fixing
# it here so the modal honestly reflects "available, just not in mlx_models/".
def _hf_cache_root() -> Path:
    """Resolve HF cache root the same way huggingface_hub does — env vars
    in the order the library checks, falling back to ~/.cache/huggingface/hub."""
    explicit = (
        os.environ.get("HF_HUB_CACHE")
        or os.environ.get("HUGGINGFACE_HUB_CACHE")
    )
    if explicit:
        return Path(explicit)
    hf_home = os.environ.get("HF_HOME")
    if hf_home:
        return Path(hf_home) / "hub"
    return Path.home() / ".cache/huggingface/hub"


def _repo_hf_cache_dir(repo_id: str) -> Path | None:
    """Return the most recent snapshot dir for repo_id in the HF cache, or
    None if not present. Layout: <cache>/models--<owner>--<repo>/snapshots/<rev>/"""
    safe = repo_id.replace("/", "--")
    base = _hf_cache_root() / f"models--{safe}" / "snapshots"
    if not base.is_dir():
        return None
    revs = []
    try:
        for d in base.iterdir():
            if d.is_dir():
                revs.append((d, d.stat().st_mtime))
    except OSError:
        return None
    if not revs:
        return None
    revs.sort(key=lambda t: t[1], reverse=True)
    return revs[0][0]


# ---- Ideogram 4 weights source -------------------------------------------
# The official ideogram-ai/ideogram-4-fp8 repo is license-gated, which forced
# every user through an HF token + "Agree and access" dance — the #1 support
# pain (cocktailpeanut hit it too). cocktailpeanut re-published an UN-GATED
# mirror with identical fp8 weights, so we pull from that: no token, no license
# click, no 403. We still prefer an already-downloaded official copy so existing
# users don't re-fetch 28 GB.
IDEOGRAM_REPO_UNGATED = "cocktailpeanut/ideogram-4-fp8"
IDEOGRAM_REPO_OFFICIAL = "ideogram-ai/ideogram-4-fp8"

def _ideogram_repo_cached(repo_id: str) -> bool:
    snap = _repo_hf_cache_dir(repo_id)
    return snap is not None and (snap / "transformer" / "diffusion_pytorch_model.safetensors").exists()

def _ideogram_any_cached() -> bool:
    return _ideogram_repo_cached(IDEOGRAM_REPO_OFFICIAL) or _ideogram_repo_cached(IDEOGRAM_REPO_UNGATED)

def _resolve_ideogram_repo() -> str:
    # Reuse an existing official download; otherwise the un-gated mirror so a
    # first-time user needs no Hugging Face token.
    return IDEOGRAM_REPO_OFFICIAL if _ideogram_repo_cached(IDEOGRAM_REPO_OFFICIAL) else IDEOGRAM_REPO_UNGATED


def _repo_missing_in_cache(repo: dict) -> list[str] | None:
    """Files missing from the HF cache snapshot for this repo, or None if
    the repo isn't in the cache at all (caller treats None as "fall back to
    local-dir reporting"). HF cache stores symlinks to ../blobs/<hash>; we
    follow them and check size on the actual blob."""
    cache_dir = _repo_hf_cache_dir(repo["repo_id"])
    if cache_dir is None:
        return None
    missing = []
    for fname in repo.get("files", []):
        p = cache_dir / fname
        try:
            actual = p.resolve()
            if not actual.exists() or actual.stat().st_size < _MIN_FILE_BYTES:
                missing.append(fname)
        except OSError:
            missing.append(fname)
    return missing


def base_missing() -> list[str]:
    """Aggregate of all base-kind repos' missing files (each prefixed with
    its local_dir for backwards-compat with existing /status consumers).

    Only checks the canonical Pinokio layout. If LTX_MODEL is set to an HF
    repo id rather than a local path, the helper resolves weights via the
    HF cache and the local-dir check would misreport — return [] there so
    the panel doesn't false-positive against a working manual install."""
    if not str(MODEL_ID).startswith("/"):
        return []
    return capability_missing("render")


def _capabilities() -> dict:
    return _REQUIRED.get("capabilities") or {}


def capability_repo_keys(name: str, version_id: str | None = None) -> list[str]:
    """Which repos a capability needs, for the ACTIVE generation.

    `render` is declared per version because which packs render is exactly what a
    generation IS: on ltx25 that is q4_25 + gemma4_25, and Gemma 3 is not in the list.
    """
    cap = _capabilities().get(name) or {}
    by_version = cap.get("repos_by_version")
    if by_version:
        vid = version_id or ACTIVE_MODEL_VERSION
        keys = by_version.get(vid)
        if keys is None:
            keys = by_version.get(cap.get("default_version") or "") or []
        return list(keys)
    return list(cap.get("repos") or [])


def capability_missing(name: str, version_id: str | None = None) -> list[str]:
    """Files this capability is missing, as `<local_dir>/<file>` — [] when it works.

    ONE QUESTION PER CAPABILITY. `kind: "base"` had come to mean both "fetched on a
    fresh install" and "the panel cannot render without it", and those are different
    questions with different answers: Gemma 3 is fetched on every install and the active
    2.5 generation does not render with it, so a half-downloaded planner model was
    reporting the RENDERER incomplete and hiding Start. The preview decoder had the same
    bug one commit earlier. Asking per capability is what stops the next one.
    """
    by_key = {r.get("key"): r for r in _repos()}
    out: list[str] = []
    for key in capability_repo_keys(name, version_id):
        repo = by_key.get(key)
        if not repo:
            continue
        for fname in _repo_effective_missing(repo):
            out.append(f"{repo['local_dir']}/{fname}")

    # PATHS, VENVS AND MODEL TREES COUNT TOO. This evaluated `repos` only and
    # silently returned [] for anything declared with the other three keys — so
    # the H3 capability reported ok:true on a machine where h3_paths() correctly
    # said not_installed. A capability that answers "fine" for a component set it
    # never looked at is worse than no capability, because the whole point of the
    # declaration was to stop two consumers disagreeing.
    cap = _capabilities().get(name) or {}
    for rel in cap.get("paths") or ():
        if not (ROOT / rel).exists():
            out.append(rel)
    venv_any = cap.get("venv_any") or ()
    if venv_any and not any(_venv_python_resolves(ROOT / rel) for rel in venv_any):
        out.append(venv_any[0] + " (no resolvable interpreter)")
    roots, models = cap.get("model_roots") or (), cap.get("models") or ()
    if models:
        for root in roots or ("",):
            base = ROOT / root if root else ROOT
            missing = [m for m in models if not (base / m).is_file()]
            if not missing:
                break
        else:
            missing = []
            for m in models:
                if not any((ROOT / r / m).is_file() for r in (roots or ("",))):
                    missing.append(m)
        out.extend(missing)
    return out


def _venv_python_resolves(path: Path) -> bool:
    """A venv entry counts only when it is an interpreter that still resolves.

    `bin/activate` existing proves nothing: uv creates bin/python as a symlink
    chain into a shared managed interpreter, and installing another pack can
    move it — leaving activate in place beside a dangling python. That is the
    v3.4.0 "installed other packs and Hailuo H3 vanished" report. `.exists()`
    follows symlinks, so a broken chain is definitively false.
    """
    try:
        return path.exists() and path.name != "activate"
    except OSError:
        return False


def capability_state(name: str, version_id: str | None = None) -> dict:
    """{ok, blocking, label, missing[]} — what the UI renders and the gate reads."""
    cap = _capabilities().get(name) or {}
    missing = capability_missing(name, version_id)
    return {
        "ok": not missing,
        "blocking": bool(cap.get("blocking")),
        "label": cap.get("label") or name,
        "engines": list(cap.get("engines") or []),
        "missing": missing,
    }


def capabilities_state(version_id: str | None = None) -> dict:
    return {name: capability_state(name, version_id)
            for name in _capabilities() if not name.startswith("_")}


def _repo_effective_missing(repo: dict) -> list[str]:
    """THE answer to "what is this repo missing" — the one /models already gives.

    There were two answers and they disagreed on a live install: /models reported all 11
    repos complete and model_integrity ok/42, while /status reported a base file missing,
    so the panel showed "Base models needed before you can render (1 files left)" over a
    perfectly working install and never stopped.

    The gap was not staleness, it was two different questions. repo_status_list() resolves
    each repo through the REGISTRY when it backs a registered pack (so a pack an env var
    moved, or one that shares a directory with another, is checked where it actually
    lives) and falls back to the HF CACHE when the local dir is short (what manual and dev
    installs use). base_missing() did neither: it walked ROOT/local_dir and believed it.

    Now both call this, so the blocker card and the Models modal cannot contradict each
    other again — the card is a rendering of the modal's answer, not a second opinion.
    """
    quant = _quant_for_repo_key(repo.get("key"))
    local_missing = pack_missing_files(quant) if quant else _repo_missing(repo)
    if not local_missing:
        return []
    total = len(repo.get("files", []))
    cache_missing = _repo_missing_in_cache(repo)
    if cache_missing is not None:
        if (total - len(cache_missing)) > (total - len(local_missing)):
            return cache_missing
    return local_missing


def pack_missing_files(quant: str, version_id: str | None = None) -> list[str]:
    """Files missing for ONE pack of ONE model version (bare filenames).

    This is the anti-mosaic primitive. The file list comes from the pack's
    `required_files.json` entry (reached through the registry by repo key,
    never by a literal), and the directory comes from the registry's resolved
    pack path — so the answer is always about the exact weights the job is
    going to load, and a second model version cannot inherit the first one's
    answer.

    Directory resolution keeps the pre-registry behaviour exactly: a pack
    under ROOT is checked ROOT-relative via `_repo_missing`; a pack an env
    var moved outside ROOT (LTX_Q8_LOCAL) is checked absolutely. Returns []
    for a quant this version doesn't ship, which is the honest answer — the
    caller's job is to notice the pack isn't registered, not to see phantom
    missing files."""
    repo = pack_repo(quant, version_id)
    if not repo:
        return []
    base = pack_path(quant, version_id)
    if base.is_relative_to(ROOT):
        override = repo.copy()
        override["local_dir"] = str(base.relative_to(ROOT))
        return _repo_missing(override)
    missing = []
    for fname in repo.get("files", []):
        p = base / fname
        try:
            if not p.exists() or p.stat().st_size < _MIN_FILE_BYTES:
                missing.append(fname)
        except OSError:
            missing.append(fname)
    return missing


def pack_available_anywhere(quant: str, version_id: str | None = None) -> bool:
    """True if (version, quant) is complete in EITHER its local dir OR the HF
    cache — the cache-aware form of `pack_missing_files`. Same reasoning as
    q8_available_anywhere below, generalised to any registered pack."""
    repo = pack_repo(quant, version_id)
    if not repo:
        return False
    for entry in repo_status_list():
        if entry.get("key") == repo.get("key"):
            return bool(entry.get("complete"))
    return False


def base_model_dir(version_id: str | None = None) -> str:
    """Model directory for a version's BASE (distilled) pipeline, as a job
    spec wants it.

    Every version resolves to its own registry q4 pack, with ONE exception:
    the version whose q4 pack is literally `Q4_LOCAL_PATH` gets `MODEL_ID`
    instead. That is not a special case for "the default" — it is a special
    case for **2.3 specifically**, because `MODEL_ID` is the env-aware
    spelling of that one install: `LTX_MODEL` overrides it, and it degrades
    to the bare HF repo id `dgrauet/ltx-2.3-mlx-q4` when the directory is
    absent. Those two shapes have to keep working byte-for-byte.

    KEYING THIS OFF PACK IDENTITY RATHER THAN DEFAULT-NESS IS LOAD-BEARING.
    Two earlier spellings both broke, in mirror image:

      `== ACTIVE_MODEL_VERSION` — read correctly only while ltx23 was the
      sole generation and so always both default and active. The day
      LTX_MODEL_VERSION=ltx25 made a second version active, 2.5 asked for its
      base pipeline and was handed MODEL_ID — the 2.3 pack — and rendered 2.3
      weights under 2.5 code, silently, at full speed. Caught by reading the
      helper's `ready` line, not by any test.

      `== default_model_version_id()` — correct until 2.5 BECAME the default,
      at which point it hands the 2.5 generation the 2.3 pack again.

    A pack's own path cannot drift out from under it, so this spelling
    survives the default moving in either direction."""
    wanted = version_id or ACTIVE_MODEL_VERSION
    pack = version_pack("q4", wanted)
    if pack is not None and Path(pack["path"]) == Q4_LOCAL_PATH:
        return str(MODEL_ID)
    return str(pack_path("q4", wanted))


def text_encoder_dir(version_id: str | None = None) -> str:
    """Text-encoder directory for a version, as the helper's env wants it.

    Each version names its own encoder in the registry, and 2.3's entry names
    the `GEMMA` constant itself — so `LTX_GEMMA_PATH` and every existing
    install layout are honoured byte-for-byte without a branch here. Like
    base_model_dir(), this deliberately does NOT ask which version is the
    default; that answer changes, and the encoder a generation needs does not.

    This exists because the conditioning half of the pipeline had no seam at
    all. `MODEL_VERSIONS` described which DiT weights a generation loads while
    the encoder stayed a module-level constant pointing at Gemma 3, so
    selecting 2.5 moved the transformer and left the text tower behind — and
    the mismatch is silent (see the ltx25 entry's note on 188160)."""
    te = model_version(version_id).get("text_encoder") or {}
    return str(te.get("path") or GEMMA)


def text_encoder_missing_files(version_id: str | None = None) -> list[str]:
    """Anti-mosaic primitive for the encoder, mirroring pack_missing_files().

    An encoder that is half-downloaded fails the same way a half-downloaded
    DiT does: it loads what is there, leaves the rest at whatever the module
    constructor produced, and renders something that looks like a bad model
    rather than a missing file."""
    te = model_version(version_id).get("text_encoder") or {}
    key = te.get("repo_key")
    if not key:
        return []
    repo = None
    for r in _REQUIRED.get("repos", []):
        if r.get("key") == key:
            repo = r
            break
    if not repo:
        return []
    base = Path(text_encoder_dir(version_id))
    return [f for f in (repo.get("files") or []) if not (base / f).exists()]


_HQ_WEIGHTS_FALLBACK = {
    "dev_transformer": "transformer-dev.safetensors",
    "distilled_lora": "ltx-2.3-22b-distilled-lora-384.safetensors",
}


def hq_weights(version_id: str | None = None) -> dict:
    """The dev transformer + distilled LoRA FILENAMES a version's two-stage HQ
    surface loads out of its hq pack.

    High, Extend, Keyframe and A2V all reach past `model_dir` and name a file
    inside it. `model_dir` alone is therefore not the whole seam: point a job
    at the 2.5 pack while the filename still says 2.3 and the loader looks for
    something that is not there.

    The fallback is the 2.3 pair rather than an empty dict on purpose — an
    unknown or malformed registry entry must behave exactly like the code did
    before this function existed, which is what makes adding it a no-op for
    every generation that does not override it."""
    names = model_version(version_id).get("hq_weights") or {}
    return {k: str(names.get(k) or v) for k, v in _HQ_WEIGHTS_FALLBACK.items()}


def hq_addon_missing(version_id: str | None = None) -> list[str]:
    """Missing files of this version's HQ ADD-ON pack (bare filenames).

    Returns [] for a version that declares no add-on -- which is 2.3, and which
    is why the split is inert for it: 2.3 ships its dev transformer and
    distilled LoRA inside its own q8 repo, so `pack_missing_files("q8")` already
    accounts for them and this adds nothing.

    Checked against the Q8 PACK PATH, not the registry's `local_dir`, so
    `LTX_Q8_LOCAL` keeps working: the add-on has no directory of its own, it
    lands in the q8 pack beside the weights it is loaded with.
    """
    key = model_version(version_id).get("hq_addon_repo_key")
    if not key:
        return []
    repo = next((r for r in _repos() if r.get("key") == key), None)
    if not repo:
        return []
    base = pack_path("q8", version_id)
    missing = []
    for fname in repo.get("files", []):
        fpath = base / fname
        try:
            if not fpath.exists() or fpath.stat().st_size < _MIN_FILE_BYTES:
                missing.append(fname)
        except OSError:
            missing.append(fname)
    return missing


def hq_surface_missing(version_id: str | None = None) -> list[str]:
    """Everything the two-stage HQ surface needs and doesn't have.

    High, Extend, Keyframe and A2V do not just point at the q8 pack -- they
    reach inside it and load two more files by name. Before the packs were
    split those two were listed in the q8 repo entry, so asking
    `q8_missing_files()` answered both questions at once; splitting them into
    their own download unit would have silently made every one of those gates
    wave through to a FileNotFoundError mid-render, which is the exact bug
    e870061 was written to end.

    So the gates ask THIS instead, and it is the union. Same names, same
    refusals, one more place they can come from.
    """
    missing = pack_missing_files("q8", version_id)
    for fname in hq_addon_missing(version_id):
        if fname not in missing:
            missing.append(fname)
    return missing


def ltx_floor_canvas(width, height) -> tuple[int, int]:
    """Floor a canvas onto the engine's /64 grid.

    The rule make_job applies to every LTX lane, extracted so the two lanes
    that derive their canvas from a SOURCE CLIP — Motion Control and Colorize,
    both computed inside run_job_inner, after make_job has already run — get
    the same answer instead of their own /32 copy of it. Every registered LTX
    lane is two-stage, stage 1 runs at half resolution, and the pipeline snaps
    to multiples of 64 on its own: /32 dims are a claim the render does not
    honour, and on a source-derived lane they also squash the picture, because
    the reference is resized onto whatever canvas we name.
    """
    return (max(64, (int(width) // 64) * 64),
            max(64, (int(height) // 64) * 64))


def ltx_model_dir(quant: str, version_id: str | None = None) -> str:
    """Pack directory for a job spec, with the fallback the IC-LoRA / HDR
    sites hand-rolled four times: if the pack directory isn't on disk, hand
    the helper the models root and let its own resolution take over rather
    than naming a path that doesn't exist."""
    p = pack_path(quant, version_id)
    return str(p) if p.is_dir() else str(MODELS_DIR)


def _canonical_layout() -> bool:
    """True when this panel is driving the canonical Pinokio model layout.

    False for the two shapes we must never second-guess: LTX_MODEL set to a
    bare HF repo id (weights resolve through the HF cache) and LTX_MODEL
    pointed at a directory the user assembled themselves. We have no
    manifest for either, so completeness claims about them would be lies.

    DEFECT-1, and it had been live since 2.5 became the default. This compared
    MODEL_ID against `pack_path("q4")` with no version_id — i.e. against
    whichever generation is ACTIVE. That was an identity while ltx23 was the
    only entry; from the day a second generation landed it compared the 2.3
    install path against the 2.5 pack path, which are never equal, so it was
    False on every stock install. It is the SOLE gate on ltx_pack_preflight(),
    so that function returned at line 1 and refused nothing: an incomplete pack
    rendered the June-2026 rainbow mosaic instead of naming the missing file —
    the exact two-week failure the preflight was written to end.

    The question it is asking is "is MODEL_ID the pack we installed, wherever
    it came from", and MODEL_ID is defaulted from Q4_LOCAL_PATH — a 2.3 path.
    So it must be compared WITHIN a version, against any generation's own q4
    pack, rather than against whatever happens to be default today."""
    mid = str(MODEL_ID)
    if not mid.startswith("/"):
        return False
    return any(mid == str(pack_path("q4", v["id"])) for v in MODEL_VERSIONS)


def ltx_pack_preflight(quant: str, feature: str,
                       version_id: str | None = None) -> None:
    """Refuse a render whose weights are incomplete, and NAME the file.

    This is the June-2026 lesson turned into four lines of control flow. One
    1 GB spatial upscaler fell out of a `download_include` allowlist; the
    pack still had every other file, the loader still built the module, and
    it built it from random initialisation. Output was a rainbow mosaic with
    no error anywhere -- two weeks and three wrong theories (Metal watchdog,
    corrupt download, an MLX 4-bit kernel bug) before anyone looked at the
    file list. A second model version multiplies that surface by the number
    of packs, so every pack a job is about to load gets asked first.

    Conservative by construction -- it can only fire where we have ground
    truth: the canonical layout, a registered pack, and the files absent
    from BOTH the pack directory and the HF cache. Anything else returns
    silently and the job proceeds exactly as it did before."""
    if not _canonical_layout():
        return
    repo = pack_repo(quant, version_id)
    if not repo:
        return
    if pack_available_anywhere(quant, version_id):
        return
    missing = pack_missing_files(quant, version_id)
    if not missing:
        return
    ver = model_version(version_id)
    shown = ", ".join(missing[:3]) + (" …" if len(missing) > 3 else "")
    raise RuntimeError(
        f"{feature} can't run: the {ver['label']} {quant.upper()} model is "
        f"incomplete. Missing {len(missing)} file(s) in "
        f"{pack_path(quant, version_id)}: {shown}. "
        f"Rendering anyway produces garbled 'mosaic' output rather than an "
        f"error, which is why this stops here. Use the Repair banner in "
        f"Settings → Model files, or re-download {repo['repo_id']}."
    )


def q8_missing_files() -> list[str]:
    """Files missing for the active version's Q8 pack (bare filenames).
    Honors $LTX_Q8_LOCAL via the registry's pack path.

    Kept as a named function because ~10 job-time gates and /status read it;
    the logic now lives in `pack_missing_files` so a second model version
    asks the same question about its OWN pack."""
    return pack_missing_files("q8")


def q8_available_anywhere() -> bool:
    """True if the Q8 repo is complete in EITHER the local dir OR the HF cache.

    `q8_missing_files()` only checks the local dir (Q8_LOCAL_PATH or
    LTX_Q8_LOCAL). `repo_status_list()` knows about both layers and picks
    the more-complete one. /status used to compute `q8_available = not
    q8_missing_files()`, which falsely reported "Q8 missing" for users who
    had Q8 in their HF cache but not in mlx_models/. The model browser
    modal — which IS cache-aware — would simultaneously show Q8 as
    complete. Two different answers from the same panel for the same repo.

    Issue #9 (oo2music, 2026-05-16): "This mode needs the Q8 model" gate
    on FFLF/Extend/HQ stayed on even after Q8 was downloaded to the HF
    cache. This helper is the single source of truth so the FFLF gate
    matches the model browser.
    """
    return pack_available_anywhere("q8")


def repo_status_list() -> list[dict]:
    """Per-repo status snapshot for the /models endpoint and the UI panel.

    Resolution order per repo:
      1. Check the canonical local_dir (mlx_models/<repo>/...) — what
         Pinokio installs always populate.
      2. If incomplete there, check HF cache (~/.cache/huggingface/...) —
         what manual installs / dev environments use.
      3. Whichever is more complete wins; the `where` field tells the UI
         which storage layer the files are in (so we can show "Cached"
         instead of "Installed" for cache-backed installs).

    This is the fix for the previously-reported false "MISSING" against
    HF-cache installs — the panel now sees them and reports honestly."""
    out = []
    for r in _repos():
        local_dir = r["local_dir"]
        if r.get("key") == "q8":
            # This row printed an ABSOLUTE path while all nine of its siblings
            # printed a ROOT-relative one — a leftover from when LTX_Q8_LOCAL
            # was the only way to move a pack. Relative when it is inside the
            # app (the normal case), absolute only when the env var really has
            # pointed it somewhere else, which is the one time the full path is
            # the information.
            local_dir = str(Q8_LOCAL_PATH)
            try:
                local_dir = str(Q8_LOCAL_PATH.relative_to(ROOT))
            except ValueError:
                pass

        # Completeness is asked of the registry when this repo backs a
        # registered pack, so the answer is per-(version, pack) and a second
        # model version gets its own answer instead of inheriting 2.3's.
        _quant = _quant_for_repo_key(r.get("key"))
        local_missing = pack_missing_files(_quant) if _quant else _repo_missing(r)
        # NOTE: _repo_effective_missing() above collapses this same local+cache choice
        # into one call for /status. This loop keeps the expanded form because it also
        # needs `where`/`location`/`present` for the row — same rule, more outputs.
        total = len(r.get("files", []))
        local_present = total - len(local_missing)

        cache_missing = _repo_missing_in_cache(r)
        cache_present = (total - len(cache_missing)) if cache_missing is not None else 0

        # Pick the layer with more files present — ties go to local_dir
        # because that's what Pinokio installs use and what the menu
        # consults.
        if cache_missing is not None and cache_present > local_present:
            where = "hf_cache"
            missing = cache_missing
            present = cache_present
            location = str(_repo_hf_cache_dir(r["repo_id"]) or _hf_cache_root())
        else:
            where = "local_dir"
            missing = local_missing
            present = local_present
            location = local_dir

        out.append({
            "key": r["key"],
            "kind": r.get("kind", "base"),
            "name": r["name"],
            "blurb": r.get("blurb", ""),
            "repo_id": r["repo_id"],
            "local_dir": local_dir,
            "where": where,                 # 'local_dir' | 'hf_cache'
            "location": location,           # actual on-disk path the files are in
            "size_gb": r.get("size_gb"),
            "total_files": total,
            "present_files": present,
            "missing_files": missing,
            "complete": not missing,
            # Does this row's download need the `hf` binary?
            #
            # The 2.3 packs come from HuggingFace via `hf download`; the 2.5
            # packs come from a GitHub release, fetched by scripts/
            # fetch_pack_release.py, which needs nothing but stdlib. The modal
            # used to gate EVERY row's button on hf_available, so an install
            # without `hf` could not start the download it is perfectly capable
            # of doing — and the modal's own header already told the user the
            # LTX-2.5 rows do not need it. Derived from the registry's `mirror`
            # block rather than a key list in JS, so a future mirrored pack is
            # right by construction.
            "needs_hf": not bool(r.get("mirror")),
            # WHICH GENERATION owns this row, and whether that is the one this
            # build renders with. Without it the modal called 2.3's base packs
            # "required" on a 2.5 install, with capability copy ("Drives
            # Quick / Balanced / Standard renders") that is simply false now —
            # and the footer's "Required: N/M" counted them, so §7.1's stated
            # first-visit contract was unreachable by construction.
            #
            # None = generation-neutral (the IC-LoRAs, the tiny decoder): those
            # are required or optional on their own terms, not a generation's.
            "generation": _repo_generation(r.get("key")),
            # `gemma` is 2.3's text encoder AND the prompt enhancer AND the
            # storyboard planner, on every generation — so it is genuinely in
            # use no matter which one renders, and badging it "previous
            # generation" would be as wrong as Storage offering to delete it.
            # Storage already carves out the same exception, for the same
            # reason; the two surfaces agree because the reason is the same one.
            "active": (r.get("key") == "gemma"
                       or _repo_generation(r.get("key")) in (None, ACTIVE_MODEL_VERSION)),
            # A guest pack: `local_dir` is another repo's directory and the
            # files are loaded from there BY NAME. Downloading one into an
            # absent host produces a folder holding two files and nothing else,
            # so the UI states the dependency instead of enforcing it silently.
            "host_key": _repo_host_key(r),
        })
    return out


def _dir_size_bytes(base: Path) -> int:
    """Sum of every regular file under `base`. 0 when it isn't there."""
    total = 0
    try:
        for p in base.rglob("*"):
            try:
                if p.is_file() and not p.is_symlink():
                    total += p.stat().st_size
            except OSError:
                continue
    except OSError:
        return 0
    return total


# NOTE: the size formatter for this section is `_fmt_gb`, which already existed
# further down this file. This block deliberately does NOT define a second one —
# a duplicate was written here first and was silently shadowed by the existing
# definition (later binding wins at module level), which is the same
# "two definitions of one thing" class the tier tables and the subtitle writers
# were. One formatter, and it is decimal GB (n / 1e9).
#
# THE UNIT IS LOAD-BEARING. The Models modal prints `size_gb` from
# required_files.json, which is decimal GB (~30.02 GB for a pack `du -h` calls
# 28G). Storage sits directly under it in the same dialog, so if one section
# used binary GiB the two would disagree by 7 % about the same folder and it
# would read as a bug. Never mix in `du -h`.


# What a pack is worth keeping FOR. Computed from things the panel already
# knows, not typed per row: the trainer preflight hardcodes 2.3's q8 + q4, and
# the IC-LoRA registry names ltx-2.3-* files, so removing 2.3 really does turn
# off Train and the four control-LoRA modes.
STORAGE_KEEP_IF = {
    # 2.3's keep-if clause. TRAIN CHARACTER IS THE WHOLE LIST, and the earlier
    # version of this sentence was wrong in a way that cost the user 20 GB: it
    # also named Colorize, Restore, Ingredients and HDR. Those four resolve
    # `ltx_model_dir("q4")`, which is the ACTIVE generation's base — they run on
    # 2.5 — and their control LoRAs are separate ~4 GB files in
    # mlx_models/loras/ic that the installer fetches regardless. Removing the
    # 2.3 pack does not touch them. Only the trainer genuinely needs it.
    # It used to be printed for whichever generation was inactive, so a user
    # pinned back with LTX_MODEL_VERSION=ltx23 was shown a row offering to
    # delete 80 GB of 2.5 with a sentence arguing that keeping 2.3 matters.
    # Keyed per generation now; see _storage_generation_note().
    "ltx23": ("Keep it only if you train characters — the Train tab trains "
              "against LTX-2.3. Nothing else needs it: your renders, and the "
              "Colorize, Restore, Ingredients and HDR modes, all run on "
              "LTX-2.5."),
    "hq_addon": ("Removing this turns off the High tier, Extend and Keyframes "
                 "until you fetch it again."),
    "q8": ("Removing this means trained characters render approximate faces "
           "and voices."),
}


def _storage_generation_note(vid: str) -> str:
    """Why keeping THIS generation might matter, or the honest default.

    A generation the product does not currently render with is still not
    interchangeable with any other: 2.3 carries the trainer and the control
    LoRAs, and 2.5 is what a user who unsets an env var will boot into with no
    weights. Saying "previous generation" about the newer one, under 2.3's
    keep-if sentence, was the shape of that bug."""
    if vid in STORAGE_KEEP_IF:
        return STORAGE_KEEP_IF[vid]
    ver = next((v for v in MODEL_VERSIONS if v["id"] == vid), None)
    label = (ver or {}).get("label", vid)
    if ver is not None and ver.get("default"):
        # The registry default: unset LTX_MODEL_VERSION and this is what boots.
        return (f"Keep it unless you are sure. {label} is what this build boots "
                f"into by default — it is only inactive because "
                f"LTX_MODEL_VERSION is set, and removing it leaves that default "
                f"lane with no weights.")
    return (f"{label} is not the generation this build is rendering with right "
            f"now. Removing it frees the space; re-installing it later is a "
            f"fresh download.")


def storage_rows() -> list[dict]:
    """What can be reclaimed on this disk, and what deliberately cannot.

    A row exists for every registered pack whose version is NOT the active one,
    plus the two generation-scoped extras. SIZES COME FROM WALKING THE ACTUAL
    DIRECTORY, not from required_files.json's `size_gb`: the honest number is
    what is on THIS disk, a partial pack must not claim a full one's footprint,
    and the planning note's own inventory was already 3 GB out on 2.3's q4 half.
    Measuring the row is the whole argument."""
    rows: list[dict] = []
    active = ACTIVE_MODEL_VERSION
    seen_dirs: set[str] = set()

    for v in MODEL_VERSIONS:
        if v["id"] == active:
            continue
        dirs, nbytes = [], 0
        for pack in v.get("packs", ()):
            p = Path(pack["path"])
            if str(p) in seen_dirs or not p.is_dir():
                continue
            seen_dirs.add(str(p))
            dirs.append(p)
            nbytes += _dir_size_bytes(p)
        if not dirs:
            continue
        # "previous" is only true of a generation that came BEFORE the active
        # one. Pinned back to 2.3, calling 2.5 "previous generation" inverted
        # the product's own story and invited the user to delete the default.
        _order = [x["id"] for x in MODEL_VERSIONS]
        _is_older = (_order.index(v["id"]) < _order.index(active)
                     if active in _order and v["id"] in _order else True)
        _suffix = "previous generation" if _is_older else "not the active generation"
        rows.append({
            "key": f"version:{v['id']}",
            "name": f"{v['label']} · {_suffix}",
            "paths": [str(d.relative_to(ROOT)) if d.is_relative_to(ROOT) else str(d)
                      for d in dirs],
            "bytes": nbytes,
            "size": _fmt_gb(nbytes),
            "note": _storage_generation_note(v["id"]),
            # A generation that is only inactive because an env var says so is
            # NOT safe to offer for deletion: unset the var and the panel boots
            # into it with nothing on disk. The registry default is protected;
            # everything else is the user's to reclaim.
            "removable": not bool(v.get("default")),
        })

    # The High add-on has NO DIRECTORY OF ITS OWN — its local_dir IS the q8
    # pack's — so it sizes itself from the two filenames hq_weights() names and
    # removing it deletes exactly those two. Getting this wrong deletes the q8
    # pack, which is why it is a separate branch and not a directory walk.
    addon_key = model_version().get("hq_addon_repo_key")
    if addon_key and not hq_addon_missing():
        base = pack_path("q8")
        files = [base / n for n in hq_weights().values()]
        nbytes = sum(f.stat().st_size for f in files if f.is_file())
        if nbytes:
            rows.append({
                "key": addon_key,
                "name": f"{model_version()['label']} High add-on",
                "paths": [str(f.relative_to(ROOT)) if f.is_relative_to(ROOT) else str(f)
                          for f in files],
                "bytes": nbytes,
                "size": _fmt_gb(nbytes),
                "note": STORAGE_KEEP_IF["hq_addon"],
                "removable": True,
            })

    # The ACTIVE generation's Q8 weights. Specified in §6.3 and missed in the
    # first pass — and it is the largest single reclaimable item for anyone who
    # does not use trained characters. Sized by walking the directory MINUS the
    # add-on's two files, which are their own row above: counting them twice
    # would advertise ~60 GB of reclaimable space where ~30 GB exists.
    q8_dir = pack_path("q8")
    if q8_dir.is_dir() and str(q8_dir) not in seen_dirs and not q8_missing_files():
        addon_names = set(hq_weights().values()) if addon_key else set()
        nbytes = 0
        for f in q8_dir.rglob("*"):
            try:
                if f.is_file() and not f.is_symlink() and f.name not in addon_names:
                    nbytes += f.stat().st_size
            except OSError:
                continue
        if nbytes:
            rows.append({
                "key": (version_pack("q8") or {}).get("repo_key") or "q8",
                "name": f"{model_version()['label']} Q8 weights",
                "paths": [str(q8_dir.relative_to(ROOT)) if q8_dir.is_relative_to(ROOT) else str(q8_dir)],
                "bytes": nbytes,
                "size": _fmt_gb(nbytes),
                "note": STORAGE_KEEP_IF["q8"],
                "removable": True,
            })

    # Gemma 3 is NEVER offered. It is 2.3's text encoder AND the prompt enhancer
    # AND the storyboard planner, so removing it silently breaks Enhance and
    # Storyboard on every generation. Stating why something CANNOT go is part of
    # this section's job — a user hunting 7 GB should find the answer here
    # rather than delete it and file a bug.
    gemma3 = next((r for r in _repos() if r.get("key") == "gemma"), None)
    if gemma3:
        base = ROOT / gemma3["local_dir"]
        nbytes = _dir_size_bytes(base)
        if nbytes:
            rows.append({
                "key": "gemma",
                "name": "Gemma 3 12B",
                "paths": [gemma3["local_dir"]],
                "bytes": nbytes,
                "size": _fmt_gb(nbytes),
                "note": "Kept — this is also what Enhance and the Storyboard "
                        "planner run on.",
                "removable": False,
            })
    return rows


def storage_payload() -> dict:
    rows = storage_rows()
    reclaimable = sum(r["bytes"] for r in rows if r["removable"])
    try:
        free = shutil.disk_usage(OUTPUT).free
    except OSError:
        free = 0
    return {
        "rows": rows,
        "reclaimable": reclaimable,
        "reclaimable_label": _fmt_gb(reclaimable),
        "free_label": _fmt_gb(free),
    }


def _repo_generation(repo_key: str | None) -> str | None:
    """Which model generation owns this repo, or None if it belongs to none.

    A pack, a text encoder or an HQ add-on belongs to exactly one generation.
    The IC-LoRAs and the tiny decoder belong to none — they are required or
    optional on their own terms, and calling them "previous generation" would
    be as wrong as calling 2.3's base "required" on a 2.5 build."""
    if not repo_key:
        return None
    for v in MODEL_VERSIONS:
        if any(p.get("repo_key") == repo_key for p in v.get("packs", ())):
            return v["id"]
        if (v.get("text_encoder") or {}).get("repo_key") == repo_key:
            return v["id"]
        if v.get("hq_addon_repo_key") == repo_key:
            return v["id"]
    return None


def _repo_host_key(repo: dict) -> str | None:
    """The repo key whose directory this one installs INTO, when that is a
    different repo. None for every repo that owns its own directory.

    The HQ add-on is the only such entry today: its `local_dir` IS the q8
    pack's directory, which is correct (it loads from there by name) and is why
    it is a separate download unit rather than part of that pack."""
    key = repo.get("key")
    # ONLY a declared GUEST has a host. `publish_scope: "files"` is exactly the
    # flag that says "I am a set of files landing in someone else's folder, and
    # I must not claim that folder's sidecars" — so it is the right predicate.
    #
    # Sharing a directory is NOT sufficient, and assuming it was is a bug this
    # function had for one revision: the three IC-LoRAs all live in
    # mlx_models/loras/ic and would have named each other as hosts, so an
    # incomplete Colorize would have put "Needs Q8" on the Ingredients row.
    if not key or not repo.get("publish_scope"):
        return None
    mine = str(repo.get("local_dir") or "")
    if not mine:
        return None
    for other in _repos():
        if other.get("key") == key or other.get("publish_scope"):
            continue
        if str(other.get("local_dir") or "") == mine:
            return other.get("key")
    return None


# ---- Model integrity (corrupt/partial-weight detection) ----------------------
# A truncated or corrupt safetensors decodes to garbage — the leading
# *non-Metal* explanation for the "mosaic" / latent-grid output some users hit
# (it hits some Macs and not others — exactly the observed pattern — and a clean
# re-download fixes it). These checks are header-only (no tensor load), so they
# are cheap enough to run at boot and surface in /status.
def _verify_safetensors(path: Path) -> tuple[bool, str]:
    """Validate a .safetensors file's structure WITHOUT loading tensors.

    Layout: [8-byte little-endian u64 header_len][header JSON][tensor data].
    Each tensor entry carries ``data_offsets`` [start, end] into the data blob,
    so the file must be exactly ``8 + header_len + max(end)`` bytes. A shorter
    file = an interrupted/partial download. Returns ``(ok, reason)``."""
    try:
        size = path.stat().st_size
    except OSError as e:
        return False, f"missing ({e})"
    if size < 8:
        return False, f"too small ({size} bytes)"
    try:
        with open(path, "rb") as fh:
            hdr_len = int.from_bytes(fh.read(8), "little")
            if hdr_len <= 0 or hdr_len > 100 * 1024 * 1024:
                return False, f"implausible header length ({hdr_len})"
            if 8 + hdr_len > size:
                return False, f"truncated header (need {8 + hdr_len}, file is {size})"
            header = json.loads(fh.read(hdr_len).decode("utf-8"))
    except Exception as e:  # noqa: BLE001 — any parse failure means corrupt
        return False, f"unreadable header ({e})"
    max_end = 0
    for name, meta in header.items():
        if name == "__metadata__":
            continue
        off = (meta or {}).get("data_offsets")
        if isinstance(off, list) and len(off) == 2:
            try:
                max_end = max(max_end, int(off[1]))
            except (TypeError, ValueError):
                return False, "corrupt data_offsets in header"
    expected = 8 + hdr_len + max_end
    if size < expected:
        return False, (f"incomplete: {size} bytes on disk, header declares "
                       f"{expected} ({expected - size} short — interrupted download)")
    return True, "ok"


# ---- Model file PLACEMENT verification ---------------------------------------
# A checksum answers "is this file's content correct?". It cannot answer "is the
# file in the right PLACE?" — and a byte-perfect weight at the wrong path fails
# just as hard as a corrupt one, while every existing check reports green:
#
#   * a 4-bit `transformer-dev.safetensors` left in the Q4 dir SHADOWS the
#     full-precision one in the Q8 dir. The trainer resolves the Q4 dir first, so
#     it silently optimizes against quantized weights and emits a near-zero LoRA
#     (GitHub #35 / #36, reported by @saved-j — every checksum passed).
#   * a declared weight that got moved reads as plain "missing", so the panel
#     offers a fresh ~19 GB download while the bytes sit one directory over.
#
# required_files.json already declares each file's expected RELATIVE PATH inside
# its repo dir, so placement is verifiable from the manifest we already load —
# no new metadata, no new network calls.
#
# Cost discipline: this is stat-only. One non-recursive listdir per declared
# model dir, no hashing. The deep pass may hand in a hasher, and even then a
# candidate is hashed ONLY when (a) the declared copy is MISSING — a file
# deep-verify therefore never hashed anyway — and (b) the candidate's size
# already matches the expected size. So placement verification adds zero
# full-file reads to a healthy install.
#
# False-positive discipline (these all occur on real installs):
#   * weight files only. Sidecar configs (`config.json`, `tokenizer.json`)
#     legitimately repeat across model dirs and are not placement-sensitive.
#   * a same-NAME, same-SIZE sibling copy is benign, not a shadow: the Q4 and Q8
#     repos both legitimately ship `ltx-2.3-22b-distilled-lora-384.safetensors`.
#     Only a copy that DIFFERS from the declared one can mis-resolve.
#   * nothing is flagged unless the declared copy actually exists to be shadowed.
#     On a Q4-only install the ~11 GB dev transformer in the Q4 dir is what our
#     own Train → Preflight puts there; it shadows nothing, so it stays quiet.
#   * repos that aren't installed at all are skipped (an absent optional Q8 is
#     not "misplaced"), and HF-cache-backed installs are skipped entirely: that
#     layer is a content-addressed blob farm with symlinked snapshots, where
#     placement is huggingface_hub's business, not ours.
_PLACEMENT_EXT = ".safetensors"


def _fmt_gb(n: int) -> str:
    return f"{n / 1e9:.1f} GB"


def _short_path(p: Path) -> str:
    """ROOT-relative when possible — matches how the manifest and UI name files."""
    try:
        return str(Path(p).relative_to(ROOT))
    except ValueError:
        return str(p)


def _placed_size(p: Path) -> int:
    """Size in bytes, or 0 if absent/too small to be a real weight. Uses the same
    `_MIN_FILE_BYTES` floor as `_repo_missing`, so 'present' means the same thing
    here as everywhere else in the panel."""
    try:
        size = p.stat().st_size
    except OSError:
        return 0
    return size if size >= _MIN_FILE_BYTES else 0


def _placement_dirs() -> list[tuple[dict, Path]]:
    """(repo_def, resolved_dir) for every manifest repo whose declared directory
    exists on disk. Honors the LTX_Q8_LOCAL override the rest of the panel uses."""
    out = []
    for r in _repos():
        base = Q8_LOCAL_PATH if r.get("key") == "q8" else (ROOT / r["local_dir"])
        try:
            if base.is_dir():
                out.append((r, base))
        except OSError:
            continue
    return out


def _placement_errors(expected: dict | None = None, hasher=None) -> list[dict]:
    """Audit installed weights against the placement the manifest declares.

    Returns entries in the exact shape the header and checksum checks emit —
    ``{"repo", "file", "reason"}`` — so /status, the red banner, the boot warning
    and one-click Repair all consume them unchanged. (Repair is also the correct
    cure for a shadow copy: it deletes that repo's copy of the file and re-runs
    the download, whose `download_include` allowlist never puts it back.) Two
    extra keys — ``placement``/``found_at``/``expected_at`` — ride along for
    consumers that want the two paths without parsing prose.

    expected: optional {(repo_key, relpath): {"size": int, "sha256": str}} of
              known-good metadata (upstream HF info, supplied by the deep pass).
              The manifest's own `file_sizes` block is always used as a fallback.
    hasher:   optional callable(Path) -> sha256 hex, supplied by the deep pass so
              a relocated file can be confirmed by CONTENT rather than by name.
    """
    dirs = _placement_dirs()
    meta = dict(expected or {})

    declared: list[tuple[dict, Path, str]] = []   # (repo, dir, relpath)
    pairs: set[tuple[str, str]] = set()           # (dir, relpath) the manifest declares
    homes: dict[str, list[tuple[dict, Path, str]]] = {}   # basename -> declared homes
    for r, base in dirs:
        for rel in r.get("files", []):
            if not rel.endswith(_PLACEMENT_EXT):
                continue
            declared.append((r, base, rel))
            pairs.add((str(base), rel))
            homes.setdefault(Path(rel).name, []).append((r, base, rel))
            man_size = int((r.get("file_sizes") or {}).get(rel, 0) or 0)
            if man_size and not meta.get((r["key"], rel), {}).get("size"):
                meta.setdefault((r["key"], rel), {})["size"] = man_size

    out: list[dict] = []
    seen: set[tuple[str, str]] = set()

    def _flag(repo_key: str, fname: str, reason: str, found: str, want: str) -> None:
        if (repo_key, fname) in seen:
            return
        seen.add((repo_key, fname))
        out.append({"repo": repo_key, "file": fname, "reason": reason,
                    "placement": True, "found_at": found, "expected_at": want})

    # Pass 1 — SHADOW copies. A weight sitting in a declared model dir under a
    # name the manifest places somewhere ELSE, whose content differs from the
    # declared copy. Reported against the repo that OWNS THE DIRECTORY holding
    # the stray, so Repair deletes the stray and never the good copy.
    for r, base in dirs:
        try:
            names = sorted(os.listdir(base))
        except OSError:
            continue
        for name in names:
            if not name.endswith(_PLACEMENT_EXT) or (str(base), name) in pairs:
                continue
            candidates = homes.get(name) or []
            if not candidates:
                continue          # a name we never place anywhere — the user's own file
            stray = base / name
            stray_size = _placed_size(stray)
            if not stray_size:
                continue
            for _hr, hbase, hrel in candidates:
                if hbase == base:
                    continue      # same dir, different relpath — not a misplacement
                home = hbase / hrel
                home_size = _placed_size(home)
                if not home_size or home_size == stray_size:
                    continue      # nothing to shadow (Pass 2's job), or a benign twin
                _flag(r["key"], name,
                      f"misplaced: {_short_path(stray)} ({_fmt_gb(stray_size)}) is not a "
                      f"file this model declares, and it shadows the real {name} at "
                      f"{_short_path(home)} ({_fmt_gb(home_size)}) - anything that "
                      f"resolves this directory first loads the wrong weights",
                      _short_path(stray), _short_path(home))
                break

    # Pass 2 — DISPLACED files. A declared weight is missing from where it
    # belongs while a same-named file sits in another declared model dir. This is
    # the case the plain "missing" report turns into a needless multi-GB
    # re-download. Only runs for repos that are actually installed, so an absent
    # optional repo is never described as misplaced.
    for r, base, rel in declared:
        if not any(_placed_size(base / f) for f in r.get("files", [])):
            continue              # repo not installed here at all — not our business
        home = base / rel
        if _placed_size(home):
            continue              # exactly where it should be
        name = Path(rel).name
        want = meta.get((r["key"], rel), {})
        want_size = int(want.get("size") or 0)
        want_sha = want.get("sha256") or ""
        for _r2, base2 in dirs:
            if base2 == base:
                continue
            cand = base2 / name
            if (str(base2), name) in pairs and _placed_size(cand):
                continue          # that dir declares this name too — it's their copy
            cand_size = _placed_size(cand)
            if not cand_size:
                continue
            detail = (f"same name, {_fmt_gb(cand_size)} - verify it is the same "
                      f"file before moving it")
            if want_size and cand_size != want_size:
                detail = (f"that copy is {_fmt_gb(cand_size)}, not the expected "
                          f"{_fmt_gb(want_size)} - a different build of {name}, "
                          f"so it will not stand in for the missing file")
            elif want_size and want_sha and hasher is not None:
                # The only hash placement ever asks for: the declared copy is
                # missing (so the checksum pass skipped it) and the candidate's
                # size already matches. Net-zero extra hashing on a healthy install.
                got = ""
                try:
                    got = hasher(cand)
                except OSError as e:   # unreadable candidate is not fatal
                    detail = f"could not read that copy to confirm it ({e})"
                if got == want_sha:
                    detail = (f"same content (sha256 matches) - move it back instead of "
                              f"re-downloading {_fmt_gb(cand_size)}")
                elif got:
                    detail = ("same size but different content (sha256 mismatch) - "
                              "not the missing file")
            elif want_size and cand_size == want_size:
                detail = (f"same name and exactly the expected {_fmt_gb(want_size)} - "
                          f"almost certainly the missing file in the wrong folder")
            else:
                detail = (f"same name, {_fmt_gb(cand_size)} - run Verify (deep) to "
                          f"confirm it is the same file before moving it")
            _flag(r["key"], rel,
                  f"wrong location: expected at {_short_path(home)}, found at "
                  f"{_short_path(cand)} - {detail}",
                  _short_path(cand), _short_path(home))
            break

    return out


_INTEGRITY_LOCK = threading.Lock()
_INTEGRITY_CACHE: dict = {"ts": 0.0, "data": None}


def _model_integrity(force: bool = False) -> dict:
    """Header-only integrity scan of installed model weights. Cached ~120 s so
    the frequently-polled /status doesn't re-read headers every tick.

    Returns {"ok": bool, "bad": [{"repo","file","reason"}], "checked": int,
             "scanned_ts": float}."""
    now = time.time()
    with _INTEGRITY_LOCK:
        cached = _INTEGRITY_CACHE["data"]
        if (not force) and cached is not None and (now - _INTEGRITY_CACHE["ts"] < 120):
            return cached
    result: dict = {"ok": True, "bad": [], "checked": 0, "scanned_ts": now}
    try:
        snap = repo_status_list()
    except Exception:  # noqa: BLE001 — integrity must never break /status
        snap = []
    defs = {r["key"]: r for r in _repos()}
    for r in snap:
        if not r.get("complete"):
            continue  # a missing model is the download flow's job, not integrity's
        base = Path(r.get("location") or (ROOT / r["local_dir"]))
        for fname in defs.get(r["key"], {}).get("files", []):
            if not fname.endswith(".safetensors"):
                continue
            fpath = base / fname
            if not fpath.exists():
                continue  # presence already vetted by repo_status_list; don't false-flag
            ok, reason = _verify_safetensors(fpath)
            result["checked"] += 1
            if not ok:
                result["ok"] = False
                result["bad"].append({"repo": r["key"], "file": fname, "reason": reason})
    # Placement audit — right content, wrong path. Folded into the same bad[] the
    # banner, boot warning and Repair already consume. It is stat-only, so it is
    # safe in the /status path, and unlike the header scan above it deliberately
    # runs for INCOMPLETE repos too: "a declared file is missing here and the
    # bytes are one directory over" is exactly what it exists to catch.
    try:
        already = {(b["repo"], b["file"]) for b in result["bad"]}
        placement = [p for p in _placement_errors()
                     if (p["repo"], p["file"]) not in already]
    except Exception:  # noqa: BLE001 — integrity must never break /status
        placement = []
    if placement:
        result["ok"] = False
        result["bad"].extend(placement)
    # Render-level output-codec audit — see _output_codec_report below. Its
    # own sub-block rather than a bad[] row on purpose: bad[] drives the
    # Repair (re-download) flow, and a wrong-codec clip is not fixable by
    # re-downloading weights. It also does not flip result["ok"] — the boot
    # warning and the banner's corrupt/misplaced headlines enumerate bad[];
    # consumers read output_codec.ok directly.
    try:
        result["output_codec"] = _output_codec_report()
    except Exception:  # noqa: BLE001 — integrity must never break /status
        result["output_codec"] = {"ok": True, "skipped": "audit crashed"}
    with _INTEGRITY_LOCK:
        _INTEGRITY_CACHE["ts"] = now
        _INTEGRITY_CACHE["data"] = result
    return result


# ---- render-level output-codec self-report (the v3.8.1 class) ----------------
# v3.8.1 shipped fleet-wide silent 4:2:0: the codec patch never applied, and
# every gate that existed was static (node --check, shell-line ceilings, patch
# exit codes) — nothing ever looked at a PRODUCED file, so renders completed,
# looked like renders, and carried chroma-subsampled block artifacts on faces
# for a whole release. This closes the class at the last possible layer:
# ffprobe the newest panel-rendered LTX clip and compare it against the codec
# its own sidecar says was requested at render time, plus the patched
# encoder's +faststart fingerprint (the unpatched upstream line writes
# neither, so it is detectable even when the requested pix_fmt equals
# upstream's hardcoded yuv420p). The implementation is
# scripts/check_output_codec.py — the SAME file the release checklist runs —
# imported here so the pre-promote gate and every install's self-report
# cannot drift apart. Cost: one ffprobe per NEW output (cached by
# path+mtime), riding _model_integrity's 120 s cache.
_CODEC_GATE_PATH = ROOT / "scripts" / "check_output_codec.py"
_codec_gate_mod = None
_OUTPUT_CODEC_CACHE: dict = {"key": None, "report": None, "warned_key": None}


def _codec_gate():
    """Lazy-import the gate script. Returns None if missing/unimportable —
    the self-report then skips; a broken gate must never break /status."""
    global _codec_gate_mod
    if _codec_gate_mod is not None:
        return _codec_gate_mod
    try:
        spec = importlib.util.spec_from_file_location(
            "phosphene_check_output_codec", _CODEC_GATE_PATH)
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        _codec_gate_mod = mod
    except Exception:  # noqa: BLE001 — retried on the next integrity refresh
        return None
    return _codec_gate_mod


def _output_codec_report() -> dict:
    """Codec state of this install's newest panel render. Shapes:
    {ok: True, skipped: str} when there is nothing checkable, else
    {ok, file, actual, expected, expected_source, faststart, problems}."""
    gate = _codec_gate()
    if gate is None:
        return {"ok": True, "skipped": "gate script unavailable"}
    if not FFPROBE.exists():
        return {"ok": True, "skipped": "ffprobe not found"}
    picked = gate.newest_panel_output(OUTPUT)
    if picked is None:
        return {"ok": True, "skipped": "no panel-rendered clip yet"}
    target, sidecar = picked
    try:
        key = (str(target), target.stat().st_mtime)
    except OSError:
        return {"ok": True, "skipped": "output vanished mid-check"}
    if _OUTPUT_CODEC_CACHE["key"] == key:
        return _OUTPUT_CODEC_CACHE["report"]
    try:
        rep = gate.check_file(target, FFPROBE, sidecar=sidecar)
        report = {
            "ok": rep["ok"],
            "file": Path(rep["file"]).name,
            "actual": rep["actual"],
            "expected": rep["expected"],
            "expected_source": rep["expected_source"],
            "faststart": rep["faststart"],
            "problems": rep["problems"],
        }
    except Exception as e:  # noqa: BLE001 — a half-written mp4 is a skip, not an alarm
        report = {"ok": True, "skipped": f"probe failed: {e}"}
    if not report["ok"] and _OUTPUT_CODEC_CACHE.get("warned_key") != key:
        # Once per offending file — the log is how this stays visible in the
        # panel UI without a render-blocking modal. ASCII only (emoji in
        # panel output can break the Pinokio/helper handshake, 2026-06-02).
        _OUTPUT_CODEC_CACHE["warned_key"] = key
        push("[codec-audit] OUTPUT CODEC MISMATCH on "
             f"{report['file']}: {'; '.join(report['problems'])} - the codec "
             "patch may not be applied (the v3.8.1 class). Click Update in "
             "Pinokio; if it persists, reinstall.")
    _OUTPUT_CODEC_CACHE["key"] = key
    _OUTPUT_CODEC_CACHE["report"] = report
    return report


# ---- deep (checksum) integrity vs upstream -----------------------------------
# _verify_safetensors catches a truncated/partial file (wrong SIZE). But a file
# that is the RIGHT size yet WRONG content — a stale upstream revision, silent
# bit-rot, a bad mirror, an interrupted resume that left a plausible size — passes
# the header+size check and STILL decodes to the rainbow-grid "mosaic". That is
# the residual, chip-independent cause behind GitHub #18 / #5: those users had
# every file present at the right size, and the only thing that fixed it was
# replacing the weights with a fresh upstream copy (a content mismatch).
#
# This verifies each installed weight's SHA-256 against the repo's PUBLISHED
# HuggingFace lfs.sha256 (verified to match a local `shasum -a 256` exactly) and
# feeds any mismatch into the SAME repair flow (delete + resumable re-download).
# It hashes every byte (~1-2 min/repo), so it is ON-DEMAND only — never on boot
# or in the /status hot path. Runs in a daemon thread; progress + result live in
# _DEEP_VERIFY and are surfaced via /status.deep_verify.
_UPSTREAM_SHA_CACHE: dict = {}          # repo_id -> {filename: sha256}
_UPSTREAM_SHA_LOCK = threading.Lock()
_DEEP_VERIFY_LOCK = threading.Lock()
_DEEP_VERIFY: dict = {"active": False, "result": None, "progress": "", "started_ts": 0.0}


def _upstream_meta(repo_id: str) -> dict:
    """filename -> {"sha256", "size"} from HuggingFace LFS metadata, cached for
    the session (upstream rarely changes mid-session). Returns {} on any
    network/lib failure — the caller treats 'unknown' as unverifiable, never as
    corrupt, so a flaky lookup can never trigger a spurious re-download.

    The published SIZE comes back in the same `files_metadata=True` response as
    the checksum (no extra request), and the placement audit uses it to decide
    whether a relocated file is even worth hashing."""
    with _UPSTREAM_SHA_LOCK:
        if repo_id in _UPSTREAM_SHA_CACHE:
            return _UPSTREAM_SHA_CACHE[repo_id]
    out: dict = {}
    try:
        from huggingface_hub import HfApi
        info = HfApi().repo_info(repo_id, files_metadata=True,
                                 token=_active_hf_token() or None)
        for s in info.siblings:
            lfs = getattr(s, "lfs", None)
            if isinstance(lfs, dict):
                sha, lfs_size = lfs.get("sha256"), lfs.get("size")
            else:
                sha = getattr(lfs, "sha256", None)
                lfs_size = getattr(lfs, "size", None)
            size = int(lfs_size or getattr(s, "size", 0) or 0)
            if sha or size:
                out[s.rfilename] = {"sha256": sha or "", "size": size}
    except Exception as e:  # noqa: BLE001 — network/lib failure → unverifiable
        push(f"[deep-verify] upstream checksum lookup failed for {repo_id}: {e}")
        return {}
    with _UPSTREAM_SHA_LOCK:
        _UPSTREAM_SHA_CACHE[repo_id] = out
    return out


def _upstream_shas(repo_id: str) -> dict:
    """filename -> published SHA-256. Thin view over `_upstream_meta` (same
    single cached lookup); files upstream publishes without a checksum are
    omitted, so callers still read a missing key as 'unverifiable'."""
    return {k: v["sha256"] for k, v in _upstream_meta(repo_id).items() if v.get("sha256")}


def _sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(8 * 1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


# The sidecar our own quantiser writes next to the weights it produces
# (scripts/quantize_ltx.py). Shape: {"files": {"<name>": {"sha256", "bytes"}}}.
PACK_MANIFEST_NAME = "phosphene_quant_manifest.json"


def _manifest_meta(base: Path) -> dict:
    """filename -> {"sha256", "size"} read from a pack's own manifest.

    The second source of truth for /models/verify-deep. HuggingFace publishes
    an LFS sha256 per file, which is where every expected hash has come from
    so far — but a pack mirrored through GitHub releases (the lane the 2.5
    packs take, because their upstream is gated and we publish our own
    quantisation) has no such API. Its hashes ride along in the pack instead.

    Returns {} on anything unexpected. The caller reads a missing entry as
    'unverifiable', never as corrupt, so a malformed or absent manifest can
    never trigger a spurious multi-GB re-download."""
    try:
        with open(base / PACK_MANIFEST_NAME, "r") as fh:
            data = json.load(fh)
    except (OSError, ValueError):
        return {}
    files = data.get("files")
    if not isinstance(files, dict):
        return {}
    out: dict = {}
    for name, entry in files.items():
        if not isinstance(entry, dict):
            continue
        sha = entry.get("sha256") or ""
        size = int(entry.get("bytes") or entry.get("size") or 0)
        if sha or size:
            out[name] = {"sha256": sha, "size": size}
    return out


def _pack_verify_source(repo_key: str | None) -> str:
    """Where the expected SHAs for this repo come from — "hf-api" (default,
    and what every 2.3 pack plus gemma and the IC-LoRAs use) or "manifest".

    Keyed off the PACK, across every generation (`pack_for_repo_key`), because
    where a pack's checksums live is a property of the pack, not of whichever
    generation happens to be active in this process."""
    pack = pack_for_repo_key(repo_key) or {}
    return pack.get("verify_source") or "hf-api"


def _expected_meta(repo_key: str | None, repo_id: str, base: Path) -> dict:
    """filename -> {"sha256", "size"} for one installed repo, from whichever
    source its registry entry declares.

    A "hf-api" pack additionally falls back to a manifest if one is sitting in
    the directory and the network lookup came back empty. That fallback is
    inert for every 2.3 pack — dgrauet's repos carry no manifest — and turns
    "unverified because the network blinked" into a real answer where we do
    ship one."""
    if _pack_verify_source(repo_key) == "manifest":
        return _manifest_meta(base)
    meta = _upstream_meta(repo_id) if repo_id else {}
    return meta or _manifest_meta(base)


def _deep_verify_thread() -> None:
    """Hash every installed weight + compare to upstream. Result mirrors
    _model_integrity's shape ({ok, bad:[{repo,file,reason}], checked}) so the
    existing Repair banner + /models/repair flow consume it unchanged."""
    result = {"ok": True, "bad": [], "checked": 0, "unverified": [],
              "scanned_ts": time.time(), "error": None}
    try:
        snap = repo_status_list()
        defs = {r["key"]: r for r in _repos()}
        for r in snap:
            if not r.get("complete"):
                continue
            repo_def = defs.get(r["key"], {})
            repo_id = repo_def.get("repo_id", "")
            base = Path(r.get("location") or (ROOT / r["local_dir"]))
            # Expected hashes come from whichever source the registry
            # declares for this pack: HuggingFace LFS metadata (every 2.3
            # pack, unchanged) or the pack's own manifest (a mirrored pack
            # with no checksum API, which is how the 2.5 packs ship).
            up = {k: v["sha256"]
                  for k, v in _expected_meta(r["key"], repo_id, base).items()
                  if v.get("sha256")}
            for fname in repo_def.get("files", []):
                if not fname.endswith(".safetensors"):
                    continue
                fpath = base / fname
                with _DEEP_VERIFY_LOCK:
                    _DEEP_VERIFY["progress"] = f"{r['key']}/{fname}"
                if not fpath.exists():
                    result["ok"] = False
                    result["bad"].append({"repo": r["key"], "file": fname, "reason": "missing"})
                    continue
                exp = up.get(fname)
                if not exp:
                    # Couldn't fetch upstream checksum — report as unverified,
                    # NOT corrupt (don't trigger a needless 11 GB re-download).
                    result["unverified"].append({"repo": r["key"], "file": fname})
                    continue
                try:
                    local = _sha256_file(fpath)
                except OSError as e:
                    result["ok"] = False
                    result["bad"].append({"repo": r["key"], "file": fname, "reason": f"unreadable ({e})"})
                    continue
                result["checked"] += 1
                if local != exp:
                    result["ok"] = False
                    result["bad"].append({
                        "repo": r["key"], "file": fname,
                        "reason": f"checksum mismatch (stale/corrupt: upstream {exp[:10]}…, local {local[:10]}…)",
                    })
        # Placement audit — right content, WRONG PATH. A checksum pass is blind
        # to it by construction: every byte can be correct and the loader still
        # resolves the wrong file (#35/#36). Hand it the published sizes and
        # checksums (already cached from the lookups above) so a relocated weight
        # can be confirmed by CONTENT, then fold findings into the same bad[].
        exp_meta: dict = {}
        for r in _repos():
            repo_id = r.get("repo_id", "")
            _q = _quant_for_repo_key(r.get("key"))
            base = pack_path(_q) if _q else (ROOT / r["local_dir"])
            if not any(_placed_size(base / f) for f in r.get("files", [])):
                continue                # not installed here — don't ask upstream
            for fname, m in _expected_meta(r.get("key"), repo_id, base).items():
                exp_meta[(r["key"], fname)] = m
        already = {(b["repo"], b["file"]) for b in result["bad"]}
        for p in _placement_errors(expected=exp_meta, hasher=_sha256_file):
            if (p["repo"], p["file"]) in already:
                continue
            result["ok"] = False
            result["bad"].append(p)
    except Exception as e:  # noqa: BLE001 — must never crash the thread silently
        result["error"] = str(e)
    finally:
        with _DEEP_VERIFY_LOCK:
            _DEEP_VERIFY["active"] = False
            _DEEP_VERIFY["progress"] = ""
            _DEEP_VERIFY["result"] = result
        if result.get("error"):
            push(f"[deep-verify] error: {result['error']}")
        elif not result.get("ok"):
            _misplaced = [b for b in result["bad"] if b.get("placement")]
            _corrupt = [b for b in result["bad"] if not b.get("placement")]
            _msg = "[deep-verify] DONE — "
            if _corrupt:
                _msg += ("checksum mismatch on: "
                         + ", ".join(f"{b['repo']}/{b['file']}" for b in _corrupt)
                         + ". Use Repair to re-download. ")
            if _misplaced:
                _msg += "misplaced file(s): " + "; ".join(b["reason"] for b in _misplaced)
            push(_msg.strip())
        else:
            uv = len(result.get("unverified") or [])
            push(f"[deep-verify] DONE — all {result['checked']} weight file(s) match upstream"
                 + (f" ({uv} unverifiable — no upstream checksum)." if uv else "."))


# ---- HF download (in-panel model fetcher) ------------------------------------
# `hf` is the v1+ huggingface_hub CLI. We resolve it from (in order):
#   1. $LTX_HF env var
#   2. ltx-2-mlx/.venv/bin/hf       (manual install)
#   3. ltx-2-mlx/env/bin/hf         (Pinokio)
#   4. shutil.which("hf")           (system PATH fallback)
def _resolve_hf() -> Path | None:
    candidates = [
        os.environ.get("LTX_HF"),
        str(MLX / ".venv/bin/hf"),
        str(MLX / "env/bin/hf"),
        shutil.which("hf"),
    ]
    for c in candidates:
        if c and Path(c).exists():
            return Path(c)
    return None


HF_BIN = _resolve_hf()

# Single global download slot — concurrent hf downloads compete for bandwidth
# anyway, and serializing them keeps the log readable. State protected by
# DOWNLOAD_LOCK; UI polls via /status to render progress.
DOWNLOAD_LOCK = threading.Lock()
DOWNLOAD: dict = {
    "active": False,
    "key": None,           # which repo (q4/gemma/q8)
    "repo_id": None,
    "started_ts": None,
    "last_line": "",       # most recent hf output line for UI display
    "proc": None,
    "pgid": None,
}


def _download_thread(repo: dict) -> None:
    """Run `hf download <repo_id> --local-dir <repo.local_dir>` and stream
    stdout/stderr line-by-line into STATE['log']. Sets DOWNLOAD["active"]
    back to False on exit (success or fail). Files land at repo['local_dir']
    relative to ROOT, which is exactly where the completeness checks look —
    so the moment hf finishes, /status flips to complete + the UI updates.

    Y1.022 — enables hf_transfer (Rust accelerator, ~5-10× faster on big
    repos) via env var, threads the user's HF token through if set
    (anonymous HF is throttled to ~50 KB/s and stalls Q8), and wraps the
    download in a 3-attempt retry loop with exponential backoff. hf is
    resumable, so retries pick up from where the previous attempt
    stopped. User cancellations (DOWNLOAD["active"] flipping to False)
    break the loop early.

    2026-08-12 - TWO LANES, ONE RETRY LOOP. A pack whose registry entry carries
    a `mirror` block is not on HuggingFace at all: the LTX-2.5 packs are our own
    quantisation of a gated upstream, our HF token is read-only, and they are
    published as GitHub release assets instead (the lane the sample-character
    LoRA already takes). For those we spawn `scripts/fetch_pack_release.py`
    instead of `hf`. Only the COMMAND differs -- the retry/backoff, the
    line-streaming into the panel log, the single download slot and
    cancel-by-killing-the-process-group are all shared, because the alternative
    is a second downloader that drifts from this one."""
    repo_id = repo["repo_id"]
    target = ROOT / repo["local_dir"]
    target.mkdir(parents=True, exist_ok=True)
    mirror = repo.get("mirror") or {}
    is_release_mirror = mirror.get("kind") == "github-release"
    env = os.environ.copy()

    if is_release_mirror:
        # sys.executable, not HF_BIN: the fetcher is stdlib-only and runs under
        # the panel's own interpreter. No hf, no token, no Hub. It shards, it
        # resumes, and it refuses to rename a file into place until the
        # reassembled sha256 matches the published manifest.
        dl_tag = "mirror"
        cmd = [sys.executable, str(ROOT / "scripts" / "fetch_pack_release.py"),
               "--repo-key", str(repo.get("key") or ""), "--root", str(ROOT)]
        push(f"[mirror] {repo.get('key')} → {target} (~{repo.get('size_gb','?')} GB) "
             f"from the {mirror.get('release_repo')} release "
             f"{mirror.get('tag')} — sharded, sha256-verified, resumable")
    else:
        dl_tag = "hf"
        cmd = [str(HF_BIN), "download", repo_id, "--local-dir", str(target)]
        # Y1.024 - apply --include filter when the repo entry declares one.
        # Without it `hf download` grabs every file in the upstream repo.
        # dgrauet's LTX repos host duplicate transformer variants (-distilled,
        # -distilled-1.1, -dev), duplicate distilled LoRAs, and unused
        # upscalers - turning a declared 25 GB Q8 into 82 GB on disk and a
        # 25 GB Q4 into 56 GB. `download_include` is the explicit allowlist of
        # patterns we ship to the user; everything else stays on the Hub. See
        # required_files.json for the comment block on this.
        include_patterns = repo.get("download_include") or []
        for pat in include_patterns:
            cmd.extend(["--include", pat])
        if include_patterns:
            push(f"[hf] filtering {repo_id} download to {len(include_patterns)} pattern(s) — only the files the panel actually loads.")
        push(f"[hf] {repo_id} → {target} (~{repo.get('size_gb','?')} GB) — resumable")

        # HF_HUB_ENABLE_HF_TRANSFER=1 turns on the Rust downloader; if
        # hf_transfer isn't installed the hf CLI logs a warning and falls back
        # to the Python downloader (slower but still works). HF_TOKEN unlocks
        # faster throughput for users who configured a token in Settings -
        # anonymous HF is throttled hard. Neither applies to the mirror lane,
        # which is why they live inside this branch.
        env["HF_HUB_ENABLE_HF_TRANSFER"] = "1"
        hf_token = _active_hf_token()
        if hf_token:
            env["HF_TOKEN"] = hf_token
            env["HUGGING_FACE_HUB_TOKEN"] = hf_token
            push(f"[hf] using authenticated download (HF token configured) — ~10× faster than anonymous.")
        else:
            push(f"[hf] no HF token configured — downloads run on the throttled anonymous tier. Set one in Settings → Hugging Face token for ~10× faster downloads.")

    # What to call this download in the log. A mirrored pack has no meaningful
    # `repo_id` (it names an HF repo that does not exist), so it is identified
    # by registry key + release tag instead.
    dl_label = (f"{repo.get('key')} ({mirror.get('tag')})"
                if is_release_mirror else repo_id)

    max_attempts = 3
    backoff_sec = 5
    try:
        for attempt in range(1, max_attempts + 1):
            with DOWNLOAD_LOCK:
                if not DOWNLOAD["active"]:
                    push(f"[{dl_tag}] {dl_label} cancelled before attempt {attempt}.")
                    break
            if attempt > 1:
                push(f"[{dl_tag}] {dl_label} attempt {attempt}/{max_attempts} — resuming from where the previous attempt stopped.")
            try:
                proc = subprocess.Popen(
                    cmd,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.STDOUT,
                    text=True,
                    bufsize=1,
                    env=env,
                    start_new_session=True,
                )
            except Exception as exc:
                push(f"[{dl_tag}] failed to spawn the downloader: {exc}")
                break
            with DOWNLOAD_LOCK:
                DOWNLOAD["proc"] = proc
                try:
                    DOWNLOAD["pgid"] = os.getpgid(proc.pid)
                except ProcessLookupError:
                    DOWNLOAD["pgid"] = None
            # Stream every line. hf emits a tqdm progress bar with carriage
            # returns; we split on \r as well as \n so progress updates show
            # up live in the panel log instead of being buffered until done.
            buf = ""
            while True:
                ch = proc.stdout.read(1)
                if not ch:
                    break
                if ch in ("\n", "\r"):
                    line = buf.strip()
                    buf = ""
                    if line:
                        with DOWNLOAD_LOCK:
                            DOWNLOAD["last_line"] = line[:200]
                        push(f"[{dl_tag}:{repo['key']}] {line[:300]}")
                else:
                    buf += ch
            if buf.strip():
                push(f"[{dl_tag}:{repo['key']}] {buf.strip()[:300]}")
            rc = proc.wait()
            if rc == 0:
                push(f"[{dl_tag}] {dl_label} downloaded successfully.")
                break
            with DOWNLOAD_LOCK:
                still_active = DOWNLOAD["active"]
            if not still_active:
                push(f"[{dl_tag}] {dl_label} cancelled (exit {rc}).")
                break
            if attempt < max_attempts:
                push(f"[{dl_tag}] {dl_label} attempt {attempt} failed (exit {rc}). Retrying in {backoff_sec}s — the downloader resumes from where it stopped.")
                # Sleep in 1-second slices so a cancel during backoff is responsive.
                for _ in range(backoff_sec):
                    time.sleep(1)
                    with DOWNLOAD_LOCK:
                        if not DOWNLOAD["active"]:
                            break
                backoff_sec = min(backoff_sec * 2, 60)   # 5 → 10 → 20s cap by attempt 3
            else:
                push(f"[{dl_tag}] {dl_label} FAILED after {max_attempts} attempts (last exit {rc}). Click Download again to keep retrying — it resumes.")
    except Exception as exc:
        push(f"[{dl_tag}] {dl_label} crashed: {exc}")
    finally:
        with DOWNLOAD_LOCK:
            DOWNLOAD["active"] = False
            DOWNLOAD["key"] = None
            DOWNLOAD["repo_id"] = None
            DOWNLOAD["started_ts"] = None
            DOWNLOAD["last_line"] = ""
            DOWNLOAD["proc"] = None
            DOWNLOAD["pgid"] = None


def _kill_active_download() -> None:
    """Best-effort kill the running hf process group. Called by atexit and
    by the /models/cancel endpoint."""
    with DOWNLOAD_LOCK:
        pgid = DOWNLOAD.get("pgid")
        proc = DOWNLOAD.get("proc")
    if pgid is not None:
        try:
            os.killpg(pgid, signal.SIGTERM)
        except (ProcessLookupError, PermissionError):
            pass
    elif proc is not None:
        try:
            proc.terminate()
        except Exception:
            pass


atexit.register(_kill_active_download)


# ---- CivitAI bridge ---------------------------------------------------------
# CivitAI is the de-facto LoRA distribution hub. We hit its public REST API
# (no auth required for SFW; an optional CIVITAI_API_KEY env var unlocks
# higher rate limits + NSFW listings tied to an account) and download via
# urllib so we don't need a third-party HTTP dependency.
#
# Filtering: baseModels=LTXV%202.3 + types=LORA narrows to LTX-2.3 LoRAs.
# CivitAI's response shape is documented at
# https://github.com/civitai/civitai/wiki/REST-API-Reference but we trim
# the response server-side so the panel only ships what the UI needs.

CIVITAI_API_BASE = "https://civitai.com/api/v1"
CIVITAI_USER_AGENT = "phosphene/1.0 (https://github.com/mrbizarro/phosphene)"


# 2026-05-31 security fix (deep-review). The CivitAI download path takes a
# `download_url` from model metadata (attacker-influenceable) and sends the
# user's API token in BOTH the URL (`?token=`) and an `Authorization: Bearer`
# header. Two holes were closed:
#   1. The old host gate was `netloc.endswith("civitai.com")` — which also
#      matches `evilcivitai.com`. Now an EXACT host allowlist.
#   2. Python's default HTTPRedirectHandler re-attaches the Authorization
#      header across redirects to ANY host, so a crafted/compromised download
#      that 30x-redirects off-domain would exfiltrate the token. The handler
#      below strips Authorization on any cross-host redirect.
def _civitai_host_allowed(netloc: str) -> bool:
    """True only for civitai.com itself or a real *.civitai.com subdomain."""
    host = (netloc or "").split("@")[-1].split(":")[0].strip().lower()
    return host == "civitai.com" or host.endswith(".civitai.com")


def _civitai_opener():
    """A urllib opener that strips the Authorization header on any cross-host
    redirect, so the CivitAI token never travels to a host the user didn't
    authenticate to. Built lazily so urllib.request is imported before the
    handler subclass is defined (no module-load import-order coupling)."""
    import urllib.request
    import urllib.parse

    class _AuthStrippingRedirectHandler(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, req, fp, code, msg, headers, newurl):
            new_req = super().redirect_request(req, fp, code, msg, headers, newurl)
            if new_req is None:
                return None
            try:
                # Keep Authorization only while staying inside the civitai.com
                # domain (civitai.com -> images.civitai.com is legit). Strip it
                # the moment a redirect leaves the domain — e.g. to a pre-signed
                # CDN (which needs no auth anyway) or to an attacker's host.
                new_netloc = urllib.parse.urlparse(newurl).netloc
                if not _civitai_host_allowed(new_netloc):
                    hdrs = {k: v for k, v in new_req.header_items()
                            if k.lower() != "authorization"}
                    new_req = urllib.request.Request(
                        new_req.full_url, headers=hdrs, method=new_req.get_method())
            except Exception:
                # Reasoning about the redirect failed — fail closed.
                try:
                    new_req.remove_header("Authorization")
                except Exception:
                    pass
            return new_req

    return urllib.request.build_opener(_AuthStrippingRedirectHandler())


def _civitai_request(path: str, params: dict | None = None,
                     timeout: float = 20.0) -> dict:
    """Minimal stdlib HTTP client for the CivitAI API. No third-party
    deps so we don't pin requests / httpx into the install. Returns the
    decoded JSON body or raises RuntimeError on non-2xx."""
    import urllib.parse, urllib.request
    url = f"{CIVITAI_API_BASE}{path}"
    if params:
        # urlencode handles the URL-quoting (spaces → %20 etc.) so
        # baseModels=LTXV 2.3 makes it through unmangled.
        url = url + "?" + urllib.parse.urlencode(params, doseq=True)
    req = urllib.request.Request(url, headers={
        "Accept": "application/json",
        "User-Agent": CIVITAI_USER_AGENT,
    })
    api_key = _active_civitai_key()
    if api_key:
        req.add_header("Authorization", f"Bearer {api_key}")
    # CivitAI's API throws the occasional 502/503/504 on a perfectly good
    # request (owner hit "HTTP error 503" mid-search). Three attempts with a
    # short back-off turn that into a pause instead of a dead search, and
    # the message a user finally sees says what to do, not a status code.
    import urllib.error
    last: Exception | None = None
    for attempt in range(3):
        try:
            with _civitai_opener().open(req, timeout=timeout) as resp:
                body = resp.read().decode("utf-8", "replace")
                return json.loads(body)
        except urllib.error.HTTPError as exc:
            last = exc
            if exc.code in (500, 502, 503, 504, 429) and attempt < 2:
                time.sleep(1.5 * (attempt + 1))
                continue
            if exc.code in (500, 502, 503, 504):
                raise RuntimeError("CivitAI is busy right now (it answered "
                                   f"{exc.code}). Try again in a few seconds.") from exc
            if exc.code == 429:
                raise RuntimeError("CivitAI is rate-limiting this Mac — wait a minute "
                                   "and search again.") from exc
            if exc.code in (401, 403):
                raise RuntimeError("CivitAI refused the request (401/403) — check the "
                                   "CivitAI API key in Settings.") from exc
            raise RuntimeError(f"CivitAI answered HTTP {exc.code}.") from exc
        except (urllib.error.URLError, TimeoutError, OSError) as exc:
            last = exc
            if attempt < 2:
                time.sleep(1.5 * (attempt + 1))
                continue
            raise RuntimeError("Could not reach civitai.com — check the connection "
                               "and try again.") from exc
        except Exception as exc:                               # noqa: BLE001
            raise RuntimeError(f"{type(exc).__name__}: {exc}") from exc
    raise RuntimeError(f"{type(last).__name__}: {last}")


# Sub-families for the image context. Each entry maps a UI family-pill id
# to the list of CivitAI baseModel strings it covers. The "all" pill is
# the union of every list below — built dynamically so adding a new
# family stays a one-line edit. Probed against the live CivitAI API
# 2026-05-20; CivitAI's taxonomy uses different names than what their
# own model-card UI shows.
#
# Flux LoRAs are intentionally excluded — Phosphene's image engines are
# Qwen-Image-Edit-2511 (via mflux) and HiDream-O1-Image-Dev. There's no
# Flux engine exposed today, so surfacing Flux LoRAs in the browser
# would just create install candidates that no engine can run.
_CIVITAI_IMAGE_FAMILIES: dict[str, list[str]] = {
    "qwen":    ["Qwen 2", "Qwen"],   # Qwen-Image-Edit-2511 + Qwen-Image (2509)
    "hidream": ["HiDream-O1"],       # HiDream-O1-Image-Dev
}
# Sub-families for the VIDEO context — one per video ENGINE. Same mechanism
# the image context uses, and for a stronger reason: LTX and H3 don't merely
# prefer different LoRAs, they cannot load each other's at all (different
# module tree, different runner, different loader). The family pill is
# therefore not a convenience filter here, it is the lane selector, and
# openCivitaiModal() preselects it from the ACTIVE engine so an LTX user's
# default view is byte-for-byte what it was before H3 LoRAs existed.
#
# Both strings probed against the live CivitAI API rather than guessed:
#   "LTXV 2.3"    verified 2026-05-20 — "LTX 2.3", "LTX-Video 2.3" and
#                 "LTXV2.3" all return zero.
#   "MiniMax H3"  verified 2026-08-09 — "MiniMax", "Hailuo" and "Hailuo H3"
#                 all return zero; "MiniMax H3" is the only spelling with hits.
_CIVITAI_VIDEO_FAMILIES: dict[str, list[str]] = {
    "ltx": ["LTXV 2.3"],
    "h3":  ["MiniMax H3"],
}
# family-map per context, so the `family` query param means the same thing on
# both surfaces and adding a family stays a one-line edit in ONE of the two
# dicts above.
_CIVITAI_FAMILIES_BY_CONTEXT: dict[str, dict[str, list[str]]] = {
    "video": _CIVITAI_VIDEO_FAMILIES,
    "image": _CIVITAI_IMAGE_FAMILIES,
}
_CIVITAI_BASE_MODELS_BY_CONTEXT = {
    # Video LoRAs — the default. Union of every video family; the `family`
    # query param on /civitai/search narrows it to one engine's lane.
    "video": [bm for bms in _CIVITAI_VIDEO_FAMILIES.values() for bm in bms],
    # Image LoRAs — union of every family in _CIVITAI_IMAGE_FAMILIES.
    # Sub-filtering happens via the `family` query param on /civitai/search.
    "image": [bm for bms in _CIVITAI_IMAGE_FAMILIES.values() for bm in bms],
}

def spicy_mode_enabled() -> bool:
    """Return the single server-side authorization predicate for NSFW UI/data."""
    return bool(get_settings().get("spicy_mode", False))


def _civitai_search(query: str = "", nsfw: bool = False,
                    cursor: str = "", limit: int = 20,
                    context: str = "video", family: str = "") -> dict:
    """Search LoRAs. Returns the trimmed shape:
        { "items": [{
            "id", "name", "creator", "description", "tags", "downloads",
            "rating", "nsfw", "preview_url", "version_id",
            "download_url", "trigger_words", "recommended_strength",
            "size_kb", "base_model"
          }, ...],
          "total_pages", "current_page" }
    Each item carries everything the front end needs to render a card
    AND everything the download endpoint needs to write a sidecar — no
    second round-trip required to install."""
    # Spicy mode gate (v2.0 — server-side authoritative). When the user
    # hasn't enabled Spicy mode in Settings, force nsfw=False regardless
    # of what the client sent. This keeps NSFW results out of casual /
    # kid-accessible installs even if someone fiddles the client param.
    spicy_on = spicy_mode_enabled()
    if not spicy_on:
        nsfw = False
    # CivitAI's /models endpoint uses cursor-style pagination
    # (`nextCursor` in the response → pass back as `cursor` on the next
    # request). Page numbers are deprecated for this endpoint. We expose
    # the same cursor flow to the panel UI so it can render a "Load more"
    # affordance without faking pagination on top of cursors.
    # Context-aware baseModels (2026-05-18). The Images workflow needs to
    # see Flux / Qwen / HiDream LoRAs, NOT LTX-2.3 video LoRAs. Unknown
    # contexts silently fall back to the video default so any caller that
    # forgets to set context still gets sensible results.
    base_models_filter = _CIVITAI_BASE_MODELS_BY_CONTEXT.get(
        context, _CIVITAI_BASE_MODELS_BY_CONTEXT["video"]
    )
    # Sub-family narrowing. The browser exposes pills per context — "LTX-2.3"
    # / "Hailuo H3" on video, "Qwen-Image" / "HiDream" on image — so users can
    # scope the result set to the engine they're about to use. family=""
    # (or missing, or "all") leaves the full context list active.
    fam = (family or "").strip().lower()
    _fam_map = _CIVITAI_FAMILIES_BY_CONTEXT.get(context) or {}
    if fam and fam in _fam_map:
        base_models_filter = _fam_map[fam]
    # The CivitAI API accepts multi-value baseModels as repeated query
    # params (`baseModels=X&baseModels=Y`), not comma-separated. Passing
    # a list here triggers `urlencode(..., doseq=True)` in _civitai_request
    # to emit the repeated form.
    params: dict[str, object] = {
        "types": "LORA",
        "baseModels": base_models_filter,
        "limit": limit,
        "sort": "Most Downloaded",
        "nsfw": "true" if nsfw else "false",
    }
    q = query.strip()
    if q:
        # CivitAI's text search (`query`) is a different backend from the
        # browse listing and it does NOT honour `baseModels`: the two
        # together return an empty page for every word ("turbo" → 0 while
        # "Minimax H3 Turbo Loras" sits on page one of the un-queried list).
        # So a typed search drops the server-side base filter, nudges the
        # search with the engine's own word (the backend ranks "minimax
        # turbo" all-H3), and the base-model filter is applied HERE on the
        # results, paging until the page is full or the well runs dry.
        _hint_words = {"h3": "minimax", "ltx": "ltx", "qwen": "qwen",
                       "hidream": "hidream"}
        # One engine → one hinted search. "All" → one hinted search per
        # engine in the context, merged (a bare "anime" search fills its
        # pages with SDXL LoRAs and the base filter leaves nothing).
        _hints = ([_hint_words.get(fam, "")] if fam
                  else [_hint_words.get(k, "") for k in (_fam_map or {}).keys()] or [""])
        params.pop("baseModels", None)
        params["limit"] = 50
        _want = {bm.lower() for bm in base_models_filter}
        raw_items: list[dict] = []
        _seen: set = set()
        raw = {}
        for _hint in _hints:
            _p = dict(params)
            _p["query"] = (f"{_hint} {q}" if _hint and _hint not in q.lower() else q)
            if cursor:
                _p["cursor"] = cursor
            for _page in range(4):
                raw = _civitai_request("/models", params=_p)
                for m in (raw.get("items") or []):
                    _bm = str(((m.get("modelVersions") or [{}])[0]).get("baseModel") or "").lower()
                    if _bm in _want and m.get("id") not in _seen:
                        _seen.add(m.get("id"))
                        raw_items.append(m)
                _next = (raw.get("metadata") or {}).get("nextCursor")
                if len(raw_items) >= limit or not _next:
                    break
                _p["cursor"] = _next
            if len(raw_items) >= limit:
                break
        raw = {**raw, "items": raw_items[:limit]}
    else:
        if cursor:
            params["cursor"] = cursor
        raw = _civitai_request("/models", params=params)
    items = []
    for m in (raw.get("items") or []):
        versions = m.get("modelVersions") or []
        if not versions:
            continue
        v = versions[0]
        files = v.get("files") or []
        # Pick the first .safetensors file. CivitAI sometimes hosts
        # multiple file variants (pruned, full, etc.); prefer the one
        # marked `primary: true` if present, otherwise fall back to the
        # first .safetensors.
        primary = next((f for f in files if f.get("primary") and
                        f.get("name", "").lower().endswith(".safetensors")),
                       None) or next((f for f in files if
                       f.get("name", "").lower().endswith(".safetensors")),
                       None)
        if not primary:
            continue
        images = v.get("images") or []
        # Prefer the first image-type preview if any exist (some LTX LoRAs
        # ship both video MP4s AND still images). Fall back to the first
        # entry of any type. We pass the type back to the client so the
        # renderer can pick <img> vs <video> appropriately — for LTX
        # video LoRAs the previews are usually MP4s, which would just
        # 404 inside an <img> tag.
        preview_obj = (
            next((img for img in images if img.get("type") == "image" and img.get("url")), None)
            or next((img for img in images if img.get("url")), None)
        )
        preview = preview_obj.get("url") if preview_obj else None
        preview_type = preview_obj.get("type") if preview_obj else None
        creator = (m.get("creator") or {}).get("username") or "unknown"
        # CivitAI puts trigger words on the version (`trainedWords`).
        trigger = list(v.get("trainedWords") or [])
        items.append({
            "id": m.get("id"),
            "version_id": v.get("id"),
            "name": m.get("name") or f"model-{m.get('id')}",
            "creator": creator,
            "description": (m.get("description") or "")[:600],
            "tags": list(m.get("tags") or []),
            "downloads": (m.get("stats") or {}).get("downloadCount"),
            "rating": (m.get("stats") or {}).get("rating"),
            "nsfw": bool(m.get("nsfw")),
            "preview_url": preview,
            "preview_type": preview_type,        # "image" | "video" | None
            "filename": primary.get("name"),
            "size_kb": primary.get("sizeKB"),
            "download_url": primary.get("downloadUrl"),
            "trigger_words": trigger,
            "recommended_strength": 1.0,    # CivitAI doesn't expose this; default
            "base_model": v.get("baseModel"),
            "civitai_url": f"https://civitai.com/models/{m.get('id')}",
        })
    # Defense-in-depth: when Spicy mode is off, also drop any items the
    # API returned with nsfw=true. CivitAI's `nsfw=false` request param
    # filters by image-tier (Soft/Mature/X) but model cards have a
    # separate boolean we re-check here so nothing slips through.
    if not spicy_on:
        items = [it for it in items if not it.get("nsfw")]
    metadata = raw.get("metadata") or {}
    return {
        "items": items,
        "next_cursor": metadata.get("nextCursor"),
        "has_more": bool(metadata.get("nextCursor")),
    }


# ---------------------------------------------------------------------------
# HUGGING FACE — a LoRA browser beside the CivitAI one
# ---------------------------------------------------------------------------
# Phosphene names no org and endorses nothing: the user searches Hugging Face
# the way they search CivitAI — a name, an author (`author:someone`), or an
# `owner/repo` — and the panel shows the repos that carry a LoRA for the lane,
# with the repo's own example clip when it has one. Installing one lands the
# file where a CivitAI download lands, with the same sidecar and layout probe.
HF_LORA_CATALOG_TTL = 600
_hf_lora_catalog_cache: dict[str, tuple[float, list]] = {}
_HF_H3_RE = re.compile(r"minima[xc][_ -]?h3|hailuo[_ -]?h3", re.I)
_HF_LTX_RE = re.compile(r"ltx[_ -]?2\.?[35]|ltx[_ -]?video|ltxv", re.I)
HF_LORA_DEFAULT_QUERY = {"h3": "MiniMax H3 LoRA", "ltx": "LTX-2.3 LoRA"}
# The HF search matches repo ids, and people spell the model three ways; an
# empty query runs all three and merges, so a character repo named
# `Minimax_H3-Someone` shows beside `minimax-h3-turbo-lora`.
HF_LORA_DEFAULT_SEARCHES = {"h3": ("Minimax_H3", "MiniMax-H3", "MiniMax H3 LoRA", "Hailuo H3 LoRA"),
                            "ltx": ("LTX-2.3", "LTX-2.5", "LTXV LoRA", "LTX-Video LoRA")}


def hf_lora_lane_of_repo(repo_id: str, tags=None) -> str | None:
    """Which lane a repo's LoRA is for, from its name (and tags when the
    listing carries them): 'h3', 'ltx', or None (an image LoRA, a showcase —
    not ours to list)."""
    tail = (repo_id or "").split("/")[-1]
    tagtxt = " ".join(str(t) for t in (tags or []))
    if _HF_H3_RE.search(tail) or _HF_H3_RE.search(tagtxt):
        return "h3"
    if _HF_LTX_RE.search(tail) or _HF_LTX_RE.search(tagtxt):
        return "ltx"
    return None


# WHAT KIND OF LoRA. Read from the repo name and its tags — the only things the
# listing carries. A character is a name (two capitalised words, or the word
# itself); speed is the distilled / accelerator family; style and motion by
# their words; everything else is "other". Used by the browser's filter row.
HF_LORA_KINDS = ("character", "style", "motion", "speed", "other")
_HF_KIND_WORDS = {
    "speed": r"turbo|lightx2v|distill|accel|acc[_ -]?lora|step|fast|pdd|speed",
    "motion": r"motion|camera|transition|dance|danc|dolly|orbit|zoom|action|walk|run|jump|fight|drift|move|pose|drop|shake|twerk|kiss|lick|suck|blow|strip|undress|helper|slider",
    "style": r"style|realism|realistic|anime|cartoon|toon|cinematic|film|noir|vintage|painterly|pixar|ghibli|aesthetic|look|lighting|grade|vhs|retro|detail|enhanc|texture",
}
_HF_CHAR_WORDS = r"character|person|celebrit|actor|actress|face|identity|likeness|portrait"
# Words that mean "not a person": model names, precisions, tools, packs.
_HF_TECH_WORDS = r"minimax|hailuo|h3|ltx|ltxv|int[48]|fp[48]|fp16|bf16|nvfp|gguf|convrot|controlnet|control|union|clipproj|proj|vae|encoder|decoder|qwen|vl|heretic|quant|q[48]|pruned|dit|transformer|model|weights|comfy|comfyui|workflow|lora|loras|text|embeddings|embedding|ref|patch|showcase|tests|test|acc|omni|bridge|semantic|upscaler|latent|i2v|t2v|r2v|ref2v|fl2v|a2v|v\d+"
# Anything bigger than this is a checkpoint, not a LoRA (the largest adapter
# in the wild, the LightX2V repack, is 1.96 GB).
HF_LORA_MAX_BYTES = 2_500_000_000


def hf_lora_kind(repo_id: str, tags=None) -> str:
    tail = (repo_id or "").split("/")[-1]
    stripped = hf_lora_pretty_name(repo_id)
    text = (tail + " " + " ".join(str(t) for t in (tags or []))).lower()
    for kind in ("speed", "motion", "style"):
        if re.search(_HF_KIND_WORDS[kind], text):
            return kind
    if re.search(_HF_CHAR_WORDS, text):
        return "character"
    # "Megan Fox", "The Dude — Jeff Bridges", "Sydney Sweeney": two to four
    # capitalised alphabetic words and not one of them model jargon.
    words = [w for w in re.split(r"[ \-—_]+", stripped) if w]
    particles = {"de", "da", "del", "della", "di", "van", "von", "der", "den", "la", "le", "du", "y", "e", "the", "of", "and", "al", "bin"}
    caps = [w for w in words if w.isalpha() and w[:1].isupper()]
    if 2 <= len(words) <= 5 and len(caps) >= 2 \
            and all(w.isalpha() and (w[:1].isupper() or w.lower() in particles) for w in words) \
            and not any(re.fullmatch(_HF_TECH_WORDS, w.lower()) for w in words):
        return "character"
    return "other"


def hf_lora_pretty_name(repo_id: str) -> str:
    tail = (repo_id or "").split("/")[-1]
    tail = re.sub(r"^(minima[xc][_ -]?h3|hailuo[_ -]?h3|ltx[_ -]?2\.?[35]|ltxv?)([_ -]?(dev(_and_sulphur)?|sulphur|lora))?[_ -]*", "", tail, flags=re.I)
    return tail.replace("_", " ").replace("-", " — ").strip() or repo_id


def _hf_api_get(path: str, timeout: float = 20.0) -> object:
    import urllib.request as _ur
    req = _ur.Request("https://huggingface.co" + path, headers={"Accept": "application/json",
                                                              "User-Agent": "Phosphene"})
    tok = _active_hf_token()
    if tok:
        req.add_header("Authorization", f"Bearer {tok}")
    with _ur.urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read().decode("utf-8", "replace"))


def hf_lora_query_params(lane: str, q: str) -> tuple[str, str | None]:
    """The HF listing call for what the user typed: an `owner/repo` is fetched
    directly, `author:name` (or a huggingface.co/name URL) lists that author,
    anything else is a search; empty means the lane's own default search."""
    q = (q or "").strip()
    m = re.match(r"^(?:https?://huggingface\.co/)?([\w.-]+)/([\w.-]+)/?$", q)
    if m and not q.lower().startswith("author:"):
        return ("repo", f"{m.group(1)}/{m.group(2)}")
    m = re.match(r"^(?:author:|https?://huggingface\.co/)([\w.-]+)/?$", q, re.I)
    if m:
        return ("author", m.group(1))
    return ("search", q or HF_LORA_DEFAULT_QUERY.get(lane, "LoRA"))


def hf_lora_catalog(lane: str = "h3", q: str = "", force: bool = False) -> list[dict]:
    """Repos on Hugging Face that carry a LoRA for `lane`, in the shape the
    CivitAI grid renders. Cached ten minutes per (lane, query); the per-repo
    file listings are fetched in parallel."""
    kind, value = hf_lora_query_params(lane, q)
    key = f"{lane}:{kind}:{value}"
    now = time.time()
    hit = _hf_lora_catalog_cache.get(key)
    if hit and not force and now - hit[0] < HF_LORA_CATALOG_TTL:
        return hit[1]
    if kind == "repo":
        repos = [{"id": value}]
    elif kind == "author":
        repos = _hf_api_get(f"/api/models?author={urllib.parse.quote(value)}&limit=200&sort=likes&direction=-1")
    else:
        searches = HF_LORA_DEFAULT_SEARCHES.get(lane, (value,)) if not (q or "").strip() else (value,)
        seen: dict[str, dict] = {}
        for term in searches:
            try:
                for m in (_hf_api_get(f"/api/models?search={urllib.parse.quote(term)}&limit=200&sort=likes&direction=-1") or []):
                    if isinstance(m, dict) and m.get("id") and m["id"] not in seen:
                        seen[m["id"]] = m
            except Exception:                                      # noqa: BLE001
                continue
        repos = list(seen.values())[:320]                          # the lane filter and the size filter below do the real narrowing
    wanted = [m for m in (repos or []) if isinstance(m, dict) and m.get("id")
              and (kind == "repo" or hf_lora_lane_of_repo(m["id"], m.get("tags")) == lane)]
    import concurrent.futures as _cf
    def one(m):
        rid = m["id"]
        try:
            info = _hf_api_get(f"/api/models/{rid}?blobs=true")
        except Exception:                                          # noqa: BLE001
            return None
        sib = info.get("siblings") or []
        weights = [s for s in sib if str(s.get("rfilename", "")).lower().endswith(".safetensors")
                   and 0 < int(s.get("size") or 0) <= HF_LORA_MAX_BYTES]
        if not weights:
            return None                                  # no LoRA-sized weights: a checkpoint or a pack
        w = max(weights, key=lambda s: int(s.get("size") or 0))
        prev = next((s for s in sib if str(s.get("rfilename", "")).lower().endswith((".mp4", ".webm", ".mov"))), None)
        if prev is None:
            prev = next((s for s in sib if str(s.get("rfilename", "")).lower().endswith((".png", ".jpg", ".jpeg", ".webp", ".gif"))), None)
        base = "https://huggingface.co/" + rid + "/resolve/main/"
        owner = rid.split("/")[0]
        return {
            "id": rid, "source": "huggingface", "name": hf_lora_pretty_name(rid),
            "creator": owner, "likes": int(info.get("likes") or m.get("likes") or 0),
            "downloads": int(info.get("downloads") or m.get("downloads") or 0),
            "updated": str(info.get("lastModified") or m.get("lastModified") or "")[:10],
            "size_kb": int(int(w.get("size") or 0) / 1024),
            "filename": w["rfilename"],
            "download_url": base + urllib.parse.quote(w["rfilename"]),
            "preview_url": (base + urllib.parse.quote(prev["rfilename"])) if prev else None,
            "preview_type": ("video" if prev and str(prev["rfilename"]).lower().endswith((".mp4", ".webm", ".mov")) else ("image" if prev else None)),
            "base_model": "MiniMax H3" if lane == "h3" else "LTXV 2.3",
            "lane": lane, "hf_url": "https://huggingface.co/" + rid, "civitai_url": None,
            "trigger_words": [], "description": "", "nsfw": False,
            "kind": hf_lora_kind(rid, list(info.get("tags") or m.get("tags") or [])),
        }
    items: list[dict] = []
    with _cf.ThreadPoolExecutor(max_workers=8) as ex:
        for it in ex.map(one, wanted):
            if it:
                items.append(it)
    items.sort(key=lambda x: (x["likes"], x["updated"]), reverse=True)
    _hf_lora_catalog_cache[key] = (now, items)
    return items


def _hf_lora_download(repo_id: str, filename: str, meta: dict) -> dict:
    """Install one LoRA from a Hugging Face repo into its lane's directory,
    with the same sidecar and layout probe a CivitAI install gets."""
    from huggingface_hub import hf_hub_download                     # noqa: PLC0415
    lane = (meta.get("lane") or hf_lora_lane_of_repo(repo_id) or "ltx")
    loras_dir = _safe_h3_loras_dir() if lane == "h3" else _safe_loras_dir()
    safe_fname = re.sub(r"[^A-Za-z0-9._-]+", "_", Path(filename).name).strip("_")
    if not safe_fname.lower().endswith(".safetensors"):
        safe_fname += ".safetensors"
    target = loras_dir / safe_fname
    if target.is_file() and target.stat().st_size > 1024:
        return {"ok": True, "skipped": True, "name": meta.get("name") or target.stem,
                "path": str(target), "lane": lane, "converted": False}
    push(f"[huggingface] downloading {meta.get('name') or safe_fname} from {repo_id}")
    stage = STATE_DIR / "hf_lora_stage"
    stage.mkdir(parents=True, exist_ok=True)
    got = hf_hub_download(repo_id=repo_id, filename=filename, token=_active_hf_token() or None,
                          local_dir=str(stage / re.sub(r"[^A-Za-z0-9._-]+", "_", repo_id)))
    loras_dir.mkdir(parents=True, exist_ok=True)
    shutil.move(got, target)
    layout_info = {"layout": None, "converted": False, "prefix": ""}
    if lane == "h3":
        try:
            layout_info = _h3_lora_prepare(target)
        except Exception as exc:                                   # noqa: BLE001
            push(f"[huggingface] layout probe failed: {exc}")
    sidecar = target.with_suffix(".json")
    data = {
        "name": meta.get("name") or target.stem, "description": meta.get("description") or "",
        "trigger_words": list(meta.get("trigger_words") or []),
        "recommended_strength": float(meta.get("recommended_strength") or 1.0),
        "preview_url": meta.get("preview_url"), "preview_type": meta.get("preview_type"),
        "base_model": meta.get("base_model") or ("MiniMax H3" if lane == "h3" else "LTXV 2.3"),
        "source": "huggingface", "hf_repo": repo_id,
        "hf_url": meta.get("hf_url") or ("https://huggingface.co/" + repo_id),
        "downloaded_at": iso_now(),
        "lora_layout": layout_info.get("layout"),
        "lora_converted_prefix": (layout_info.get("prefix") or None) if layout_info.get("converted") else None,
    }
    try:
        atomic_write_text(sidecar, json.dumps(data, indent=2))
    except Exception as exc:                                       # noqa: BLE001
        push(f"[huggingface] WARN: could not write sidecar ({exc})")
    push(f"[huggingface] installed → {target.name}")
    return {"ok": True, "skipped": False, "name": data["name"], "path": str(target),
            "sidecar_path": str(sidecar), "size_bytes": target.stat().st_size, "lane": lane,
            "layout": layout_info.get("layout"), "converted": bool(layout_info.get("converted"))}


def _civitai_download(download_url: str, meta: dict) -> dict:
    """Download a CivitAI .safetensors into the right LoRA dir for its base
    model and write a sidecar JSON. Returns
    { name, path, sidecar_path, size_bytes, lane }.
    Streams to a .partial file then renames atomically — a Pinokio kill
    mid-download leaves nothing the next scan would mistake for a
    complete LoRA.

    Lane routing (2026-08-09) is decided from the ITEM's own `base_model`,
    not from which browser context the click came from. A MiniMax H3 LoRA
    lands in the H3 weights tree even if the user found it while the browser
    was showing "All", because the file's family is a property of the file,
    and mis-filing it would put an unloadable adapter in the LTX picker."""
    import urllib.parse, urllib.request
    if not download_url:
        raise RuntimeError("download_url required")
    # Restrict to civitai.com to prevent the endpoint being used as a
    # generic HTTP fetcher. Subdomains (e.g. images.civitai.com) are
    # also OK because CivitAI sometimes redirects there.
    parsed = urllib.parse.urlparse(download_url)
    if parsed.scheme != "https" or not _civitai_host_allowed(parsed.netloc):
        raise RuntimeError(f"refusing to download from {parsed.netloc}; "
                           f"only civitai.com (and *.civitai.com) is allowed")
    # CivitAI's download endpoint started requiring auth for many models
    # in 2025+. The Authorization header sometimes works, but the
    # canonical path is `?token=<key>` on the URL — and many CDN hops
    # only honour the token in the URL. Try the URL form first when a
    # key is available.
    api_key_env = _active_civitai_key()
    if api_key_env and "token=" not in (parsed.query or ""):
        sep = "&" if parsed.query else "?"
        download_url = download_url + sep + "token=" + urllib.parse.quote(api_key_env)
    # Which engine's library does this belong to? _classify_lora_modes is the
    # single source for that mapping — the picker filter, the sidecar and this
    # router all read the same function, so a new family is one edit there.
    lane = ("h3" if "video:h3" in _classify_lora_modes(meta.get("base_model"))
            else "ltx")
    loras_dir = _safe_h3_loras_dir() if lane == "h3" else _safe_loras_dir()
    # Filename from meta (preferred — preserves CivitAI's name) or fall
    # back to the URL's last path segment.
    fname = (meta.get("filename") or
             os.path.basename(parsed.path) or
             f"civitai_{meta.get('id', 'unknown')}.safetensors")
    if not fname.lower().endswith(".safetensors"):
        fname += ".safetensors"
    # Sanitize aggressively — CivitAI names can contain spaces and
    # weirder characters; the helper later passes this filename through
    # the safetensors loader which is filesystem-only and fine with
    # spaces, but the picker UI is calmer with snake_case.
    safe_fname = re.sub(r"[^A-Za-z0-9._-]+", "_", fname).strip("_")
    target = loras_dir / safe_fname
    if target.exists():
        # Don't silently re-download. Surface the conflict so the user
        # can decide (the UI will offer a choice; for now just skip).
        return {
            "name": meta.get("name") or target.stem,
            "path": str(target),
            "size_bytes": target.stat().st_size,
            "lane": lane,
            "skipped": True,
            "reason": "already exists",
        }
    tmp = target.with_suffix(target.suffix + ".partial")
    push(f"[civitai] downloading {meta.get('name') or safe_fname}")
    api_key = _active_civitai_key()
    headers = {"User-Agent": CIVITAI_USER_AGENT}
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"
    req = urllib.request.Request(download_url, headers=headers)
    bytes_written = 0
    last_log = 0.0
    _opener = _civitai_opener()  # strips Authorization on cross-host redirect
    try:
        try:
            resp_ctx = _opener.open(req, timeout=60)
        except urllib.request.HTTPError as he:
            # Surface the 401 case with a clear remediation. CivitAI now
            # requires API tokens for most LoRA downloads, even SFW ones,
            # but the API key for the search endpoint is optional — so a
            # user can browse without setting up auth and only hit this
            # wall on first install.
            if he.code == 401:
                raise RuntimeError(
                    "CivitAI returned 401 Unauthorized. CivitAI requires an "
                    "API token for LoRA downloads. Get one at "
                    "https://civitai.com/user/account, then set the "
                    "CIVITAI_API_KEY environment variable before launching "
                    "the panel (or in Pinokio's Phosphene start script). "
                    "Restart Pinokio's Phosphene to pick it up."
                )
            raise
        with resp_ctx as resp:
            total = int(resp.headers.get("Content-Length") or 0)
            with tmp.open("wb") as fh:
                while True:
                    chunk = resp.read(1024 * 256)
                    if not chunk:
                        break
                    fh.write(chunk)
                    bytes_written += len(chunk)
                    now = time.time()
                    if now - last_log > 1.0:
                        if total:
                            pct = int(100 * bytes_written / total)
                            push(f"[civitai] {pct}% · "
                                 f"{bytes_written // (1024*1024)}/"
                                 f"{total // (1024*1024)} MB")
                        else:
                            push(f"[civitai] {bytes_written // (1024*1024)} MB")
                        last_log = now
        os.replace(tmp, target)
    except Exception:
        try: tmp.unlink()
        except OSError: pass
        raise
    push(f"[civitai] saved {target.name} ({bytes_written // (1024*1024)} MB)")
    # ---- H3 lane: classify the key layout NOW, at install time --------------
    # Doing it here rather than at render time means the ComfyUI rename happens
    # once, in front of the user, with the log open — and a diffusers-namespace
    # LoRA is refused at the moment they clicked Install instead of 30 s into a
    # 20-minute render. The file is REMOVED on refusal: leaving an unloadable
    # adapter in the library would put a permanently-failing entry in the
    # picker, which is worse than the wasted download it cost to find out.
    layout_info = {"layout": None, "converted": False, "prefix": ""}
    if lane == "h3":
        try:
            layout_info = _h3_lora_prepare(target)
        except Exception as exc:
            try:
                target.unlink()
            except OSError:
                pass
            push(f"[civitai] refused {target.name}: {exc}")
            raise RuntimeError(str(exc)) from exc
    # Write the sidecar — kept tolerant of meta gaps so a partial
    # payload still produces a usable picker entry.
    sidecar = target.with_suffix(".json")
    sidecar_data = {
        "name": meta.get("name") or target.stem,
        "description": meta.get("description") or "",
        "trigger_words": (list(meta.get("trigger_words") or [])
                          or list(layout_info.get("trigger_words") or [])),
        "recommended_strength": float(meta.get("recommended_strength") or 1.0),
        "preview_url": meta.get("preview_url"),
        "base_model": (meta.get("base_model")
                       or ("MiniMax H3" if lane == "h3" else "LTXV 2.3")),
        "civitai_id": meta.get("id"),
        "civitai_version_id": meta.get("version_id"),
        "civitai_url": meta.get("civitai_url"),
        "downloaded_at": iso_now(),
        "downloaded_size_bytes": bytes_written,
        # What we found, and what we did about it. Written for both lanes so
        # the field means the same thing everywhere; None on LTX, where the
        # panel does no layout surgery.
        "lora_layout": layout_info.get("layout"),
        "lora_converted_prefix": (layout_info.get("prefix") or None
                                  if layout_info.get("converted") else None),
    }
    try:
        atomic_write_text(sidecar, json.dumps(sidecar_data, indent=2))
    except Exception as exc:
        push(f"[civitai] WARN: could not write sidecar ({exc})")
    return {
        "name": sidecar_data["name"],
        "path": str(target),
        "sidecar_path": str(sidecar),
        "size_bytes": bytes_written,
        # "ltx" | "h3" — the client uses this to decide whether it may
        # auto-enable the new LoRA on the currently-selected engine.
        "lane": lane,
        "layout": layout_info.get("layout"),
        "converted": bool(layout_info.get("converted")),
        "skipped": False,
    }


