# ---- shared state ------------------------------------------------------------

STATE: dict = {
    "queue": [], "current": None, "history": [],
    "paused": False, "log": [],
    "running": False, "pid": None, "pgid": None,
    # Process group of an in-flight Hailuo H3 render (the optional second
    # video engine — a `caffeinate → python → ffmpeg` tree outside HELPER).
    # /stop and the atexit hook kill it by pgid, same contract as train_pgid.
    "h3_pgid": None,
}
LOCK = threading.RLock()
QUEUE_COND = threading.Condition(LOCK)

CAFFEINATE_PROC: subprocess.Popen | None = None
HIDDEN_PATHS: set[str] = set()


def push(line: str) -> None:
    line = line.rstrip()
    if not line:
        return
    stamped = f"[{time.strftime('%H:%M:%S')}] {line}"
    with LOCK:
        STATE["log"].append(stamped)
        STATE["log"] = STATE["log"][-LOG_LIMIT:]


def iso_now() -> str:
    return time.strftime("%Y-%m-%d %H:%M:%S")


def atomic_write_text(path: Path, text: str, *, mode: int = 0o600) -> None:
    """Write text to `path` via temp file + fsync + os.replace.

    Plain Path.write_text() can leave a half-written file if macOS sleeps,
    runs out of disk, or the panel crashes mid-write — corrupted queue or
    sidecar files would lose the user's work-in-progress. Atomic replace
    guarantees the file is either pre-write or fully post-write, never torn.

    The temp file is born with `mode` (default 0o600) via os.open with
    O_CREAT|O_EXCL — secrets in agent_config.json / agent_image_config.json
    (API keys) are never momentarily world-readable, even between
    os.replace and a follow-up chmod. Mirrors agent/runtime.save_session.
    """
    # Multiple request/worker threads can persist state close together. A
    # process-wide temp name lets one writer replace/unlink another writer's
    # temp file, producing ENOENT in the logs and risking a missed persist.
    tmp = path.with_name(f".{path.name}.{os.getpid()}.{threading.get_ident()}.{time.time_ns()}.tmp")
    try:
        # O_EXCL guarantees we don't reopen a temp file an attacker
        # could have raced into existence with a permissive mode.
        fd = os.open(
            str(tmp),
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_TRUNC,
            mode,
        )
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                f.write(text)
                f.flush()
                try:
                    os.fsync(f.fileno())
                except OSError:
                    pass
        except Exception:
            # If fdopen never wrapped the descriptor, close it manually
            # so we don't leak. Re-raise so the caller still sees the
            # error.
            try:
                os.close(fd)
            except OSError:
                pass
            raise
        # umask on some systems can widen the kernel-set mode; chmod
        # the temp explicitly before the rename so the renamed file is
        # provably 0o600 (POSIX preserves source mode across replace).
        try:
            os.chmod(tmp, mode)
        except OSError:
            pass
        os.replace(tmp, path)
        # Belt-and-braces: chmod the final path too. Cheap and protects
        # against weird mounts that don't preserve mode across rename.
        try:
            os.chmod(path, mode)
        except OSError:
            pass
    finally:
        try:
            if tmp.exists():
                tmp.unlink()
        except Exception:
            pass


# ---- caffeinate --------------------------------------------------------------

def caffeinate_on() -> None:
    global CAFFEINATE_PROC
    if CAFFEINATE_PROC and CAFFEINATE_PROC.poll() is None:
        return
    try:
        CAFFEINATE_PROC = subprocess.Popen(["caffeinate", "-i"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        push("caffeinate active — Mac won't idle-sleep while queue is running")
    except Exception as exc:
        push(f"caffeinate failed: {exc}")


def caffeinate_off() -> None:
    global CAFFEINATE_PROC
    if CAFFEINATE_PROC and CAFFEINATE_PROC.poll() is None:
        try:
            CAFFEINATE_PROC.terminate()
        except Exception:
            pass
    CAFFEINATE_PROC = None


# ---- system probes -----------------------------------------------------------

# find_comfy_pids feeds one status pill, but it was called from the /status
# handler — a pgrep FORK every 1.5 s poll, ~2,400 process spawns per hour per
# open tab, including during renders. Comfy starting or stopping is a
# once-a-session event; 30 s staleness on the pill is invisible, the constant
# forking was not. kill_comfy() bypasses the cache (it acts on the pids).
_COMFY_PIDS_CACHE: tuple[float, list] = (0.0, [])


def find_comfy_pids(fresh: bool = False) -> list[int]:
    global _COMFY_PIDS_CACHE
    ts, pids = _COMFY_PIDS_CACHE
    if not fresh and time.time() - ts < 30.0:
        return pids
    try:
        out = subprocess.run(["pgrep", "-f", COMFY_PATTERN],
            capture_output=True, text=True, timeout=2).stdout
        pids = [int(line) for line in out.splitlines() if line.strip().isdigit()]
    except Exception:
        pids = []
    _COMFY_PIDS_CACHE = (time.time(), pids)
    return pids


def kill_comfy() -> int:
    pids = find_comfy_pids(fresh=True)
    for pid in pids:
        try:
            os.kill(pid, signal.SIGTERM)
            push(f"Sent SIGTERM to Comfy PID {pid}")
        except ProcessLookupError:
            pass
        except PermissionError as exc:
            push(f"Could not signal {pid}: {exc}")
    if not pids:
        push("Comfy was not running.")
    return len(pids)


def open_pinokio() -> None:
    try:
        subprocess.run(["open", "-a", "Pinokio"], check=False, timeout=5)
        push("Opened Pinokio — start Comfy from the dashboard if you need it.")
    except Exception as exc:
        push(f"Could not open Pinokio: {exc}")


