def _detect_total_ram_gb() -> float:
    """Return physical unified memory in GiB, or 0.0 when unavailable."""
    try:
        out = subprocess.run(
            ["sysctl", "-n", "hw.memsize"],
            capture_output=True, text=True, timeout=1,
        ).stdout.strip()
        return int(out) / 1024**3
    except Exception:
        return 0.0


SYSTEM_RAM_GB = _detect_total_ram_gb()

# The RAM floor of each tier, in GB. `_detect_tier()` gates on these AND
# `min_ram_gb_for()` quotes them, so a refusal can no longer name a number the
# gate does not use.
#
# THE BUG THIS CLOSES (@fiction, Pinokio, 2026-08-29 — "the high720P Q8 is not
# clickable"): four separate refusals told the user to "bump to 64+ GB" for
# High, Extend, FFLF and the HQ chip. All four are `allows_*` flags that the
# table grants on `standard`, whose floor is 48 — and the tier modal three
# clicks away says so in its own words ("48-79 GB ... Every video mode works").
# So the app simultaneously told a 36 GB owner to buy 64 and told them 48 was
# enough, and 16 GB of unnecessary hardware is an expensive way to find out
# which sentence was maintained.
TIER_MIN_RAM_GB: dict[str, int] = {
    "base": 0,
    "standard": 48,
    "high": 80,
    "pro": 120,
}


def min_ram_gb_for(capability: str) -> int | None:
    """Lowest RAM in GB at which `capability` is True in CAPABILITIES.

    Returns None if no tier offers it — callers fall back to prose rather than
    printing "None GB", because a capability nothing serves is a bug in the
    table, not something to quote a number for.
    """
    floors = [TIER_MIN_RAM_GB[k] for k, caps in CAPABILITIES.items()
              if caps.get(capability) and k in TIER_MIN_RAM_GB]
    return min(floors) if floors else None


def _detect_tier() -> str:
    """Pick a tier based on `hw.memsize`. Cached at module load — RAM is
    fixed at boot. LTX_TIER_OVERRIDE env var lets advanced users force a
    tier (useful for demos / reproducing other-machine bugs)."""
    override = os.environ.get("LTX_TIER_OVERRIDE", "").strip().lower()
    if override in CAPABILITIES:
        return override
    gb = SYSTEM_RAM_GB
    if gb <= 0:
        return "standard"   # safe default
    if gb < TIER_MIN_RAM_GB["standard"]: return "base"
    if gb < TIER_MIN_RAM_GB["high"]:     return "standard"
    if gb < TIER_MIN_RAM_GB["pro"]:      return "high"
    return "pro"


SYSTEM_TIER = _detect_tier()
SYSTEM_CAPS = CAPABILITIES[SYSTEM_TIER]
TRAIN_PROFILE = _select_train_profile(SYSTEM_RAM_GB, SYSTEM_TIER)


def _select_generation_profile(total_ram_gb: float, tier_key: str) -> dict:
    """Hardware profile for video generation, separate from render tier labels.

    A 48 GB M5 Pro can run the model, but long native 24 fps clips plus large
    LoRA stacks push unified memory into swap. The regular `standard` tier is
    still correct for feature availability; this profile only changes how new
    T2V/I2V jobs are shaped so they do not start in the pathological state the
    current live render hit.
    """
    # Two escape hatches, because a hardcoded 64 GB threshold was making this
    # decision alone and was demonstrably too conservative on real hardware.
    #
    # Reported 2026-08-16 (Mac Studio M4 Max, 48 GB, v4.0.6): a requested
    # 1088x1472 was silently clamped to 768x1024 while memory sat at 9.4/48 GB.
    # The reporter patched the threshold out and ran the same i2v job at the
    # full size: 12.79 s/it versus 13.4 s/it clamped, 284 s, no swap, no OOM.
    # They also found the real inconsistency — LTX_TIER_OVERRIDE moved the tier
    # modal to "Studio" while this function kept reading physical RAM, so the
    # two disagreed about what the machine could do.
    #
    # 1. An EXPLICIT tier override now flows through. If you told us to treat
    #    this machine as high/pro, the shaping obeys that instead of the RAM
    #    reading it contradicts.
    # 2. LTX_GENERATION_PROFILE=full lifts the cap on its own, for anyone who
    #    wants the cap gone without also restating their tier.
    #
    # The threshold stays the DEFAULT because it was put here by a real swap
    # thrash, and one clean 48 GB result does not retire it — but it is no
    # longer the only voice.
    _forced = os.environ.get("LTX_GENERATION_PROFILE", "").strip().lower()
    if _forced in ("full", "off", "uncapped"):
        return {
            "key": "full_generation",
            "label": "Full generation (cap lifted by LTX_GENERATION_PROFILE)",
            "ram_gb": round(float(total_ram_gb or 0), 1),
            "tier": tier_key,
            "compact": False, "max_dim": 0,
            "auto_temporal_after_frames": 0, "warn_loras": 0,
        }
    _override = os.environ.get("LTX_TIER_OVERRIDE", "").strip().lower()
    _override_lifts = _override in ("high", "pro")
    if 0 < float(total_ram_gb or 0) < 64 and not _override_lifts:
        return {
            "key": "m5pro48_generation",
            "label": "48 GB fast generation",
            "ram_gb": round(float(total_ram_gb or 0), 1),
            "tier": tier_key,
            "compact": True,
            "max_dim": 1024,
            "auto_temporal_after_frames": 241,
            "warn_loras": 6,
            "note": (
                "Long Q4 T2V/I2V renders use 12->24 fps generation on "
                "48 GB-class Macs to avoid MLX swap thrash."
            ),
        }
    return {
        "key": "full_generation",
        "label": "Full generation",
        "ram_gb": round(float(total_ram_gb or 0), 1),
        "tier": tier_key,
        "compact": False,
        "max_dim": 0,
        "auto_temporal_after_frames": 0,
        "warn_loras": 0,
    }


GENERATION_PROFILE = _select_generation_profile(SYSTEM_RAM_GB, SYSTEM_TIER)


# ---- Hailuo H3 — the optional SECOND video engine ----------------------------
#
# MiniMax-H3 (FL2VA) renders joint video + audio from one prompt. It is NOT
# part of the LTX warm-helper pipeline and never touches it: H3 ships as an
# optional pack — a sibling checkout of mrbizarro/minimax-h3-mlx with its OWN
# venv — and runs exactly like the mflux image engines already do: spawn a CLI,
# stream its stdout into push(), read its metrics JSON when it exits.
#
# Why a subprocess and not a helper action:
#   * H3's staged runner materializes ONE large component at a time (Q8 text
#     encoder → free → bf16 pruned DiT → free → the two VAEs). Peak ~40 GiB.
#     The LTX warm helper holds its own weights resident. Both at once does not
#     fit on a 64 GB Mac, so run_h3_job_inner() KILLS the warm helper first
#     (it respawns lazily on the next LTX job — existing behaviour).
#   * It keeps a second engine's dependency tree (mlx-vlm, transformers,
#     pillow) out of the ltx-2-mlx venv, so an H3 install can never break LTX.
#
# Layout (both supported — see _h3_model_roots):
#   <H3_ROOT>/scripts/generate_staged.py     the validated CLI
#   <H3_ROOT>/.venv/bin/python               its own interpreter
#   <H3_MODELS>/deepbeep-pruned-bf16/MiniMax-H3-FL2VA-pruned_bf16.safetensors
#   <H3_MODELS>/ddalcu-q8/{text_encoder,video_vae,audio_vae}.safetensors + cfg
#   <H3_MODELS>/upstream-meta/FL2VA/text_encoder/config.json
#
# Both roots are env-overridable so a dev box can point at an existing 75 GB
# checkout instead of duplicating it under the Pinokio install:
#   LTX_H3_ROOT=/path/to/minimax-h3-mlx  LTX_H3_MODELS=/path/to/models
# See docs/H3_ENGINE.md.
H3_ROOT = Path(os.environ.get("LTX_H3_ROOT", str(ROOT / "minimax-h3-mlx")))
H3_MODELS = Path(os.environ.get("LTX_H3_MODELS", str(ROOT / "mlx_models" / "hailuo-h3")))
# 64 GB machines report ~63.x GiB after firmware reservations, so the floor is
# 60, not 64. Below this the staged runner swaps and a 3 s clip takes hours.
H3_MIN_RAM_GB = 60.0
# With the Q8 DiT (8-bit core + 8-bit AdaLN, the recipe quantize.py's own table
# calls measured-safe) the render peak drops from 42.8 to 27.3 GiB measured at
# 1024x576/124f — which puts H3 in reach of 48 GB Macs. 46 leaves the same
# ~4 GB guard band under the marketing number that 60-under-64 does.
# LOWERED 46 -> 36 on 2026-08-29, on measurement rather than on a guard band.
#
# 46 was picked to sit ~4 GB under a 48 GB Mac's marketing number, back when the
# only number anyone had was "27.3 GiB peak". The full phase profile since then:
#
#     text_encode    25.63 GiB   <- the run peak, a 7-second phase
#     dit_load       20.22
#     joint_denoise  21.26 (5 s) / 24.68 (10 s)
#     video_vae      8.42
#
# 25.63 GiB is 27.5 GB. The panel now also caps H3's memory budget so the render
# leaves the user real headroom (h3_memory_budget: the larger of 6 GB and RAM/8),
# where before it took everything but one gigabyte. 27.5 + 6 = 33.5, so a 36 GB
# Mac clears it with room; 48 GB was never the real requirement.
#
# EVIDENCE: Q8 rendered clean at a simulated 36 GB budget (--memory-gb 30
# --wired-gb 26) AND at a simulated 32 GB budget (26/22), both rc=0 and both
# byte-identical (sha256 ba65bc6a...) to the unconstrained render.
#
